package com.clueteleports;

import com.clueteleports.routing.AccountRouteState;
import com.clueteleports.routing.RouteGoals;
import com.clueteleports.routing.RouteRequirements;
import com.clueteleports.routing.RouteTransport;
import com.clueteleports.routing.RoutingData;
import com.clueteleports.routing.WalkingRouteResult;
import com.clueteleports.routing.WalkingRouteSearch;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.atomic.AtomicLong;
import java.util.stream.Collectors;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/** One cancellable background search, cached by clue and usable physical graph. */
final class AsyncRoutePlanner implements TeleportRouting
{
	interface Loader { RoutingData load() throws IOException; }
	private static final Logger log = LoggerFactory.getLogger(AsyncRoutePlanner.class);
	private final ExecutorService worker;
	private final WalkingRouteSearch search;
	private final AtomicLong generation = new AtomicLong();
	private volatile RoutingData data;
	private volatile List<RouteRequirements> requirements = Collections.emptyList();
	private volatile boolean loadFailed;
	private volatile boolean closed;
	private final Future<?> loading;
	private Future<?> pending;
	private Request request;
	private Plan plan = Plan.status(Plan.Status.PREPARING);

	AsyncRoutePlanner()
	{
		this(Executors.newSingleThreadExecutor(task ->
		{
			Thread thread = new Thread(task, "poh-clue-routes");
			thread.setDaemon(true);
			return thread;
		}), RoutingData::load, new WalkingRouteSearch());
	}

	AsyncRoutePlanner(ExecutorService worker, Loader loader, WalkingRouteSearch search)
	{
		this.worker = Objects.requireNonNull(worker);
		this.search = Objects.requireNonNull(search);
		loading = worker.submit(() ->
		{
			try
			{
				RoutingData loaded = loader.load();
				requirements = Collections.unmodifiableList(loaded.getTransports().stream()
					.map(RouteTransport::getRequirements).collect(Collectors.toList()));
				data = loaded;
			}
			catch (IOException | RuntimeException error)
			{
				loadFailed = true;
				log.warn("Unable to load bundled POH walking-route data", error);
			}
		});
	}

	@Override
	public Plan update(Client client, String profile, List<WorldPoint> targets,
		Collection<TeleportDestination> arrivals, int interactionRadius)
	{
		RoutingData loaded = data;
		if (closed || loadFailed) return Plan.status(Plan.Status.UNAVAILABLE);
		if (loaded == null) return Plan.status(Plan.Status.PREPARING);
		// All live Client reads finish here, on the caller's client thread.
		AccountRouteState state = AccountRouteState.capture(client, requirements);
		// Raw item quantities and skill boosts may change without opening or
		// closing a passage. Cache by the resulting graph to avoid bank churn.
		List<RouteTransport> eligible = loaded.getTransports().stream()
			.filter(edge -> edge.getRequirements().isSatisfied(state)).collect(Collectors.toList());
		Request next = new Request(profile, targets, arrivals, interactionRadius, eligible);
		synchronized (this)
		{
			if (closed) return Plan.status(Plan.Status.UNAVAILABLE);
			if (next.equals(request)) return plan;
			long version = generation.incrementAndGet();
			if (pending != null) pending.cancel(true);
			request = next;
			plan = Plan.status(Plan.Status.SEARCHING);
			pending = worker.submit(() ->
			{
				Plan answer;
				try
				{
					List<WorldPoint> goals = RouteGoals.qualify(loaded.getCollisionMap(), next.targets, next.interactionRadius);
					WalkingRouteResult result = search.search(loaded.getCollisionMap(), next.eligible, goals, next.arrivals,
						() -> closed || generation.get() != version || Thread.currentThread().isInterrupted());
					answer = Plan.from(result);
				}
				catch (RuntimeException error)
				{
					answer = Plan.status(Plan.Status.UNAVAILABLE);
					log.warn("Unable to calculate a POH walking route", error);
				}
				finish(version, answer);
			});
			return plan;
		}
	}

	private synchronized void finish(long version, Plan answer)
	{
		if (!closed && generation.get() == version) plan = answer;
	}

	@Override
	public synchronized void invalidate()
	{
		generation.incrementAndGet();
		if (pending != null) pending.cancel(true);
		pending = null;
		request = null;
		plan = Plan.status(data == null ? Plan.Status.PREPARING : Plan.Status.SEARCHING);
	}

	@Override
	public synchronized void close()
	{
		closed = true;
		invalidate();
		loading.cancel(true);
		worker.shutdownNow();
	}

	private static final class Request
	{
		final String profile;
		final List<WorldPoint> targets;
		final List<TeleportDestination> arrivals;
		final int interactionRadius;
		final List<RouteTransport> eligible;

		Request(String profile, List<WorldPoint> targets, Collection<TeleportDestination> arrivals, int radius, List<RouteTransport> eligible)
		{
			this.profile = profile;
			List<WorldPoint> copiedTargets = new ArrayList<>(targets);
			copiedTargets.sort(Comparator.comparingInt(WorldPoint::getPlane).thenComparingInt(WorldPoint::getX).thenComparingInt(WorldPoint::getY));
			this.targets = Collections.unmodifiableList(copiedTargets);
			List<TeleportDestination> copiedArrivals = new ArrayList<>(arrivals);
			copiedArrivals.sort(Comparator.comparing(TeleportDestination::getId));
			this.arrivals = Collections.unmodifiableList(copiedArrivals);
			this.interactionRadius = radius;
			this.eligible = List.copyOf(eligible);
		}

		@Override public boolean equals(Object other)
		{
			if (!(other instanceof Request)) return false;
			Request that = (Request) other;
			return interactionRadius == that.interactionRadius && Objects.equals(profile, that.profile)
				&& targets.equals(that.targets) && arrivals.equals(that.arrivals) && eligible.equals(that.eligible);
		}
		@Override public int hashCode() { return Objects.hash(profile, targets, arrivals, interactionRadius, eligible); }
	}
}

package com.clueteleports;

import java.util.Collection;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

/** Per-character snapshots. Missing and observed-empty sources are distinct. */
public final class AvailabilityCache
{
	private final Map<TeleportSource, Set<String>> sources = new EnumMap<>(TeleportSource.class);

	public void restore(TeleportSource source, String encoded)
	{
		if (encoded == null)
		{
			sources.remove(source);
		}
		else
		{
			sources.put(source, canonical(source, AvailableTeleports.decode(encoded)));
		}
	}

	/** True only for a new source or a changed set, independent of menu ordering. */
	public boolean record(TeleportSource source, Collection<String> ids)
	{
		Set<String> next = canonical(source, ids);
		if (next.equals(sources.get(source)))
		{
			return false;
		}
		sources.put(source, next);
		return true;
	}

	public Set<String> availableIds()
	{
		Set<String> result = new TreeSet<>();
		sources.values().forEach(result::addAll);
		return Collections.unmodifiableSet(result);
	}

	public Map<TeleportSource, Set<String>> snapshot()
	{
		return Collections.unmodifiableMap(new EnumMap<>(sources));
	}

	private static Set<String> canonical(TeleportSource source, Collection<String> ids)
	{
		Set<String> result = new TreeSet<>();
		for (String id : ids)
		{
			if (TeleportCatalog.byId(id).map(destination -> destination.getSource() == source).orElse(false))
			{
				result.add(id);
			}
		}
		return Collections.unmodifiableSet(result);
	}
}

package com.clueteleports;

import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Set;
import java.util.TreeSet;
import java.util.stream.Collectors;

/** Stable serialization for cached destination IDs. */
public final class AvailableTeleports
{
	private AvailableTeleports()
	{
	}

	public static Set<String> decode(String value)
	{
		if (value == null || value.trim().isEmpty())
		{
			return Collections.emptySet();
		}
		Set<String> ids = Arrays.stream(value.split(","))
			.map(String::trim).filter(id -> !id.isEmpty()).collect(Collectors.toCollection(TreeSet::new));
		return Collections.unmodifiableSet(ids);
	}

	public static String encode(Collection<String> ids)
	{
		return String.join(",", new TreeSet<>(ids));
	}
}

package com.clueteleports;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Optional;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarPlayerID;

/**
 * Reads the active perks of a transformed cape hanger in the player's own house.
 *
 * Object IDs are RuneLite gamevals at 9fad2c588ca957ae47d883b09544725a796ed9fe;
 * the Sailing cape IDs are in ObjectID1. Cosmetic max capes retain their own
 * original cape's perks, rather than the plain max cape's skillcape perks.
 *
 * Mounted behaviour: https://oldschool.runescape.wiki/w/Cape_hanger .
 * Music status and quest point requirements are also used by task-checker's
 * CapesTaskList at ddb4e230256ed459459f120d0f7f25b6f22fce51.
 */
public final class CapeReader
{
	private static final Set<String> CONSTRUCTION = ids(
		"cape-rimmington", "cape-taverley", "cape-pollnivneach", "cape-hosidius",
		"cape-rellekka", "cape-aldarin", "cape-brimhaven", "cape-yanille", "cape-prifddinas");
	private static final Set<String> CRAFTING = ids("cape-crafting-guild");
	private static final Set<String> FARMING = ids("cape-farming-guild");
	private static final Set<String> FISHING = ids("cape-fishing-guild", "cape-ottos-grotto");
	private static final Set<String> HUNTER = ids("cape-red-chinchompas", "cape-black-chinchompas");
	private static final Set<String> STRENGTH = ids("cape-warriors-guild");
	private static final Set<String> SAILING = ids("cape-pandemonium");
	private static final Set<String> QUEST = ids("cape-legends-guild");
	private static final Set<String> MUSIC = ids("cape-falo-the-bard");
	private static final Set<String> MYTHICAL = ids("cape-myths-guild");
	private static final Set<String> ARDOUGNE = ids("cape-ardougne-monastery", "cape-ardougne-farming-patch");
	private static final Set<String> DIARY = ids(
		"cape-diary-two-pints", "cape-diary-jarr", "cape-diary-sir-rebral", "cape-diary-thorodin",
		"cape-diary-flax-keeper", "cape-diary-jackie-the-fruit", "cape-diary-kaleb-paramaya",
		"cape-diary-jungle-forester", "cape-diary-tzhaar-mej", "cape-diary-elise",
		"cape-diary-hatius-cosaintus", "cape-diary-le-sabre", "cape-diary-toby",
		"cape-diary-lesser-fanatic", "cape-diary-elder-gnome-child", "cape-diary-twiggy-okorn");
	private static final Set<String> MAX = maxDestinations();

	private CapeReader()
	{
	}

	/**
	 * A present result describes the mounted cape's capabilities, including
	 * temporarily exhausted daily teleports. Call availableNow when ranking.
	 * Unsupported objects return empty Optional, not an empty cape snapshot.
	 */
	public static Optional<Set<String>> read(Client client, int transformedObjectId)
	{
		switch (transformedObjectId)
		{
			case 29167: // Achievement diary cape.
			case 29168:
				return Optional.of(DIARY);
			case 29170: // Plain max cape only.
				return Optional.of(MAX);
			case 29176: // Music cape.
			case 29177:
				return Optional.of(MUSIC);
			case 29178: // Quest point cape.
			case 29179:
				return Optional.of(QUEST);
			case 29184: // Construction cape.
			case 29185:
				return Optional.of(CONSTRUCTION);
			case 29188: // Crafting cape.
			case 29189:
				return Optional.of(CRAFTING);
			case 29192: // Farming cape.
			case 29193:
				return Optional.of(FARMING);
			case 29196: // Fishing cape.
			case 29197:
				return Optional.of(FISHING);
			case 29204: // Hunter cape.
			case 29205:
				return Optional.of(HUNTER);
			case 29220: // Strength cape.
			case 29221:
				return Optional.of(STRENGTH);
			case 29625: // Ardougne max cape retains cloak 4's unlimited teleports.
				return Optional.of(ARDOUGNE);
			case 31983: // Mythical cape on the hanger, not the quest hall trophy.
			case 39621: // Mythical max cape.
				return Optional.of(MYTHICAL);
			case 58664: // Sailing cape.
			case 58665:
				return Optional.of(SAILING);
			default:
				return isDecorativeCape(transformedObjectId)
					? Optional.of(Collections.emptySet()) : Optional.empty();
		}
	}

	/** Rechecks transient availability without forgetting the installed fixture. */
	public static boolean availableNow(Client client, String id)
	{
		if ("cape-red-chinchompas".equals(id) || "cape-black-chinchompas".equals(id))
		{
			int used = client.getVarbitValue(VarbitID.CHINCHOMPA_TELEPORTS);
			return used >= 0 && used < 5;
		}
		if ("cape-falo-the-bard".equals(id))
		{
			return client.getVarbitValue(VarbitID.MUSIC_CAPE_STATUS) >= 1;
		}
		if ("cape-legends-guild".equals(id))
		{
			int maximum = client.getVarbitValue(VarbitID.QP_MAX);
			return maximum > 0 && client.getVarpValue(VarPlayerID.QP) >= maximum;
		}
		if ("cape-prifddinas".equals(id))
		{
			return Quest.SONG_OF_THE_ELVES.getState(client) == QuestState.FINISHED;
		}
		// Apatura's Hunter Guild cape unlock is not exposed in client vars.
		// A mounted Hunter/Max cape alone does not prove it. Do not resurrect a
		// stale ID until a reliable positive unlock observation is implemented.
		return !"cape-hunter-guild".equals(id);
	}

	private static boolean isDecorativeCape(int id)
	{
		return id >= 29166 && id <= 29225
			|| id == 26713 || id == 26714 || id == 30403
			|| id >= 31979 && id <= 31982;
	}

	private static Set<String> maxDestinations()
	{
		Set<String> result = new LinkedHashSet<>();
		result.addAll(CONSTRUCTION);
		result.addAll(CRAFTING);
		result.addAll(FARMING);
		result.addAll(FISHING);
		result.addAll(HUNTER);
		result.addAll(STRENGTH);
		result.addAll(SAILING);
		return Collections.unmodifiableSet(result);
	}

	private static Set<String> ids(String... values)
	{
		return Collections.unmodifiableSet(new LinkedHashSet<>(Arrays.asList(values)));
	}
}

