package com.clueteleports;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.coords.WorldPoint;

/**
 * Verified task sites for location-specific Sherlock challenges.
 *
 * Task labels match RuneLite SkillChallengeClue in runelite-parent-1.13.3.
 * Altar, agility, and hunter coordinates follow that version's worldmap
 * RunecraftingAltarLocation, AgilityCourseLocation, and HunterAreaLocation.
 * The Slayer Tower approach is core EmoteClue's top-floor entrance marker.
 * Chest, gem stall, lectern, Nechryael, and pyre positions are adapted from
 * emerald000/clue-helper at b1a5e772d45373bac133bfa28a1ded6a38b910b3
 * (cluesteps/EliteClues.java and MasterClues.java).
 *
 * These are task sites or their normal access points, rather than every
 * possible route to them. Skullball uses the surface werewolf-course entrance.
 * Tasks possible at arbitrary banks, fires, furnaces, anvils, or resource
 * locations intentionally have no chosen point.
 */
final class ChallengeLocations
{
	private static final String BLOOD = "bind a blood rune at the blood altar.";
	private static final WorldPoint KOUREND_BLOOD_ALTAR = new WorldPoint(1716, 3827, 0);
	private static final WorldPoint TRUE_BLOOD_ALTAR = new WorldPoint(3625, 9717, 0);
	private static final Map<String, WorldPoint> FIXED;

	static
	{
		Map<String, WorldPoint> fixed = new LinkedHashMap<>();
		fixed.put("craft a nature rune.", new WorldPoint(2869, 3019, 0));
		fixed.put("craft multiple cosmic runes from a single essence.", new WorldPoint(2408, 4377, 0));
		fixed.put("score a goal in skullball.", new WorldPoint(3542, 3463, 0));
		fixed.put("complete a lap of ape atoll agility course.", new WorldPoint(2752, 2742, 0));
		fixed.put("complete a lap of rellekka's rooftop agility course", new WorldPoint(2624, 3677, 0));
		fixed.put("catch a mottled eel with aerial fishing in lake molch.", new WorldPoint(1363, 3632, 0));
		fixed.put("catch a tecu salamander.", new WorldPoint(1475, 3096, 0));
		fixed.put("create a barrows teleport tablet.", new WorldPoint(1679, 3765, 0));
		fixed.put("steal from a chest in ardougne castle.", new WorldPoint(2588, 3291, 1));
		fixed.put("steal a gem from the ardougne market.", new WorldPoint(2667, 3303, 0));
		fixed.put("cremate a set of fiyr remains.", new WorldPoint(3507, 3276, 0));
		fixed.put("kill a nechryael in the slayer tower.", new WorldPoint(3440, 3566, 2));
		fixed.put("equip an abyssal whip in front of the abyssal demons of the slayer tower.",
			new WorldPoint(3421, 3537, 2));
		FIXED = Collections.unmodifiableMap(fixed);
	}

	private ChallengeLocations()
	{
	}

	static List<WorldPoint> forChallenge(String challenge, Client client)
	{
		if (challenge == null)
		{
			return Collections.emptyList();
		}
		String key = challenge.trim().toLowerCase(Locale.ROOT);
		if (BLOOD.equals(key))
		{
			List<WorldPoint> altars = new ArrayList<>();
			altars.add(KOUREND_BLOOD_ALTAR);
			// Both altars complete this task. The true altar requires Sins of
			// the Father; Kourend's altar has no equivalent quest gate.
			// https://oldschool.runescape.wiki/w/Sherlock#Master_skill_challenges
			if (client != null && Quest.SINS_OF_THE_FATHER.getState(client) == QuestState.FINISHED)
			{
				altars.add(TRUE_BLOOD_ALTAR);
			}
			return Collections.unmodifiableList(altars);
		}
		WorldPoint point = FIXED.get(key);
		return point == null ? Collections.emptyList() : Collections.singletonList(point);
	}
}

package com.clueteleports;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.plugins.cluescrolls.ClueScrollPlugin;
import net.runelite.client.plugins.cluescrolls.clues.ClueScroll;
import net.runelite.client.plugins.cluescrolls.clues.FaloTheBardClue;
import net.runelite.client.plugins.cluescrolls.clues.LocationClueScroll;
import net.runelite.client.plugins.cluescrolls.clues.LocationsClueScroll;
import net.runelite.client.plugins.cluescrolls.clues.NpcClueScroll;
import net.runelite.client.plugins.cluescrolls.clues.ObjectClueScroll;
import net.runelite.client.plugins.cluescrolls.clues.SkillChallengeClue;

/** Reads the destinations already identified by RuneLite's Clue Scroll plugin. */
public final class ClueTargetResolver
{
	// Core keeps Falo's coordinate private despite exposing his clue type publicly.
	// https://github.com/runelite/runelite/blob/master/runelite-client/src/main/java/net/runelite/client/plugins/cluescrolls/clues/FaloTheBardClue.java
	private static final WorldPoint FALO = new WorldPoint(2689, 3550, 0);
	// Return-task NPC coordinates match the corresponding talk-to clues in core.
	// https://github.com/runelite/runelite/blob/master/runelite-client/src/main/java/net/runelite/client/plugins/cluescrolls/clues/CrypticClue.java
	private static final WorldPoint CHARLIE = new WorldPoint(3209, 3390, 0);
	private static final WorldPoint SHERLOCK = new WorldPoint(2733, 3415, 0);

	public Resolution resolve(ClueScrollPlugin plugin)
	{
		return resolve(plugin == null ? null : plugin.getClue(), plugin);
	}

	public Resolution resolve(ClueScroll clue, ClueScrollPlugin plugin)
	{
		if (clue == null)
		{
			return new Resolution(State.NO_CLUE, Collections.emptyList());
		}

		WorldPoint[] locations;
		boolean alternativeTaskLocations = false;
		if (clue instanceof LocationsClueScroll)
		{
			locations = ((LocationsClueScroll) clue).getLocations(plugin);
		}
		else if (clue instanceof LocationClueScroll)
		{
			locations = ((LocationClueScroll) clue).getLocations(plugin);
		}
		else if (clue instanceof FaloTheBardClue)
		{
			locations = new WorldPoint[]{FALO};
		}
		else if (clue instanceof SkillChallengeClue)
		{
			SkillChallengeClue challenge = (SkillChallengeClue) clue;
			locations = getChallengeLocations(challenge, plugin);
			alternativeTaskLocations = !challenge.isChallengeCompleted() && locations.length > 1;
		}
		else
		{
			return new Resolution(State.NO_LOCATION, Collections.emptyList());
		}

		Set<WorldPoint> uniqueLocations = new LinkedHashSet<>();
		if (locations != null)
		{
			for (WorldPoint location : locations)
			{
				if (location != null)
				{
					uniqueLocations.add(location);
				}
			}
		}

		List<WorldPoint> targets = new ArrayList<>(uniqueLocations);
		State state = targets.isEmpty() ? State.NO_LOCATION
			: targets.size() == 1 ? State.RESOLVED : State.MULTIPLE_LOCATIONS;
		return new Resolution(state, targets, alternativeTaskLocations && targets.size() > 1, interactionRadius(clue, plugin));
	}


	private int interactionRadius(ClueScroll clue, ClueScrollPlugin plugin)
	{
		if (clue instanceof SkillChallengeClue && !((SkillChallengeClue) clue).isChallengeCompleted()) return 2;
		if (clue instanceof FaloTheBardClue) return 1;
		if (clue instanceof NpcClueScroll)
		{
			String[] npcs = ((NpcClueScroll) clue).getNpcs(plugin);
			if (npcs != null && npcs.length > 0) return 1;
		}
		if (clue instanceof ObjectClueScroll)
		{
			int[] objects = ((ObjectClueScroll) clue).getObjectIds();
			if (objects != null && objects.length > 0) return 1;
		}
		return 0;
	}

	private WorldPoint[] getChallengeLocations(SkillChallengeClue clue, ClueScrollPlugin plugin)
	{
		if (clue.isChallengeCompleted())
		{
			for (String npc : clue.getNpcs(plugin))
			{
				if ("Charlie the Tramp".equals(npc))
				{
					return new WorldPoint[]{CHARLIE};
				}
				if ("Sherlock".equals(npc))
				{
					return new WorldPoint[]{SHERLOCK};
				}
			}
		}
		if (!clue.isChallengeCompleted())
		{
			return ChallengeLocations.forChallenge(clue.getChallenge(), plugin == null ? null : plugin.getClient())
				.toArray(new WorldPoint[0]);
		}
		return new WorldPoint[0];
	}

	public enum State
	{
		NO_CLUE,
		NO_LOCATION,
		RESOLVED,
		MULTIPLE_LOCATIONS
	}

	/** A snapshot; a clue's possible locations can change without its identity changing. */
	public static final class Resolution
	{
		private final State state;
		private final List<WorldPoint> locations;
		private final boolean alternativeTaskLocations;
		private final int interactionRadius;

		private Resolution(State state, List<WorldPoint> locations)
		{
			this(state, locations, false, 0);
		}

		private Resolution(State state, List<WorldPoint> locations, boolean alternativeTaskLocations, int interactionRadius)
		{
			this.state = state;
			this.alternativeTaskLocations = alternativeTaskLocations;
			this.interactionRadius = interactionRadius;
			this.locations = Collections.unmodifiableList(new ArrayList<>(locations));
		}

		public int getInteractionRadius() { return interactionRadius; }

		public State getState()
		{
			return state;
		}

		/** All listed sites can complete this task; they are not unresolved clue candidates. */
		public boolean hasAlternativeTaskLocations()
		{
			return alternativeTaskLocations;
		}

		public List<WorldPoint> getLocations()
		{
			return locations;
		}
	}
}

package com.clueteleports;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.FontMetrics;
import java.util.Collections;
import java.util.EnumSet;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.util.Text;
import net.runelite.client.ui.overlay.components.TitleComponent;

public final class ClueTeleportsOverlay extends OverlayPanel
{
	private static final Color LEARNED_COLOR = new Color(126, 215, 137);
	private static final Color NOT_LEARNED_COLOR = new Color(255, 196, 93);
	private final ClueTeleportsPlugin plugin;

	@Inject
	ClueTeleportsOverlay(ClueTeleportsPlugin plugin)
	{
		super(plugin);
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
		setResizable(false);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Forget learned sources", "POH Clue Teleports",
			entry -> plugin.forgetAvailability());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Display display = plugin.getDisplay();
		if (display == null)
		{
			return null;
		}
		panelComponent.getChildren().clear();
		setPreferredSize(null);
		panelComponent.setPreferredSize(new Dimension(contentWidth(graphics.getFontMetrics(), display), 0));
		if (display.isLearning())
		{
			panelComponent.getChildren().add(TitleComponent.builder().text(display.first).color(Color.CYAN).build());
			panelComponent.getChildren().add(LineComponent.builder().left(display.second).leftColor(Color.LIGHT_GRAY).build());
			for (TeleportSource source : display.getRequiredSources())
			{
				boolean learned = display.getLearnedSources().contains(source);
				panelComponent.getChildren().add(LineComponent.builder()
					.left(source.getDisplayName())
					.right(learned ? "Learned" : "Not learned")
					.rightColor(learned ? LEARNED_COLOR : NOT_LEARNED_COLOR)
					.build());
			}
		}
		else
		{
			panelComponent.getChildren().add(TitleComponent.builder().text("POH clue teleport").color(Color.CYAN).build());
			panelComponent.getChildren().add(LineComponent.builder().left(display.first).build());
			panelComponent.getChildren().add(LineComponent.builder().left(display.second).build());
			if (display.third != null)
			{
				panelComponent.getChildren().add(LineComponent.builder().left(display.third).leftColor(Color.LIGHT_GRAY).build());
			}
		}
		// PanelComponent sizes its background from its previous layout. Measure
		// without painting first so content changes resize correctly this frame.
		Graphics2D measurement = (Graphics2D) graphics.create();
		try
		{
			measurement.setClip(0, 0, 0, 0);
			panelComponent.render(measurement);
		}
		finally { measurement.dispose(); }
		return super.render(graphics);
	}


	private static int contentWidth(FontMetrics metrics, Display display)
	{
		int width = textWidth(metrics, display.isLearning() ? display.first : "POH clue teleport");
		width = Math.max(width, textWidth(metrics, display.first));
		width = Math.max(width, textWidth(metrics, display.second));
		width = Math.max(width, textWidth(metrics, display.third));
		for (TeleportSource source : display.getRequiredSources())
		{
			String status = display.getLearnedSources().contains(source) ? "Learned" : "Not learned";
			width = Math.max(width, textWidth(metrics, source.getDisplayName()) + 12 + textWidth(metrics, status));
		}
		return Math.max(100, Math.min(300, width + 2 * ComponentConstants.STANDARD_BORDER));
	}

	private static int textWidth(FontMetrics metrics, String text)
	{
		return text == null ? 0 : metrics.stringWidth(Text.removeTags(text));
	}

	static final class Display
	{
		final String first;
		final String second;
		final String third;
		private final Set<TeleportSource> learnedSources;
		private final Set<TeleportSource> requiredSources;

		Display(String first, String second, String third)
		{
			this(first, second, third, null, Collections.emptySet());
		}

		private Display(String first, String second, String third, Set<TeleportSource> learnedSources, Set<TeleportSource> requiredSources)
		{
			this.first = first;
			this.second = second;
			this.third = third;
			this.learnedSources = learnedSources;
			this.requiredSources = requiredSources;
		}

		static Display learning(Map<TeleportSource, Set<String>> snapshots, Set<TeleportSource> required, String hint)
		{
			Objects.requireNonNull(snapshots, "snapshots");
			Set<TeleportSource> learned = EnumSet.noneOf(TeleportSource.class);
			learned.addAll(snapshots.keySet());
			learned.retainAll(required);
			Set<TeleportSource> copied = EnumSet.noneOf(TeleportSource.class);
			copied.addAll(required);
			return new Display("Learn POH teleports (" + learned.size() + "/" + required.size() + ")",
				Objects.requireNonNull(hint, "hint"), null, Collections.unmodifiableSet(learned), Collections.unmodifiableSet(copied));
		}

		Set<TeleportSource> getRequiredSources() { return requiredSources; }

		boolean isLearning()
		{
			return learnedSources != null;
		}

		Set<TeleportSource> getLearnedSources()
		{
			return learnedSources == null ? Collections.emptySet() : learnedSources;
		}
	}
}

package com.clueteleports;

import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.cluescrolls.ClueScrollPlugin;
import net.runelite.client.ui.overlay.OverlayManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "POH Clue Teleports",
	description = "Compare available POH teleports using account-aware walking routes to the active clue",
	tags = {"poh", "house", "clue", "teleport", "nexus", "obelisk"}
)
@PluginDependency(ClueScrollPlugin.class)
public class ClueTeleportsPlugin extends Plugin
{
	static final String CONFIG_GROUP = "clueteleports";
	static final String HOUSE_INVENTORY_KEY = "houseFacilities";
	private static final Logger log = LoggerFactory.getLogger(ClueTeleportsPlugin.class);
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ConfigManager configManager;
	@Inject private PluginManager pluginManager;
	@Inject private OverlayManager overlayManager;
	@Inject private ClueTeleportsOverlay overlay;
	private final ClueTargetResolver targetResolver = new ClueTargetResolver();
	private final FairyRingTravelLog fairyTravelLog = new FairyRingTravelLog();
	private final NexusMenuScroll nexusMenuScroll = new NexusMenuScroll();
	private TeleportRouting routing;
	private final HouseContext houseContext = new HouseContext();
	private final MenuObservations observations = new MenuObservations();
	private final Map<TeleportSource, String> pendingFixtures = new EnumMap<>(TeleportSource.class);
	private AvailabilityCache availability = new AvailabilityCache();
	private HouseInventory houseInventory = new HouseInventory();
	private String pendingInventory;
	private boolean ownHouse;
	private HouseLearningOverlay learningOverlay;
	private volatile HouseLearningOverlay.Guidance guidance = new HouseLearningOverlay.Guidance(false,
		Collections.emptySet(), null, null);
	private volatile ClueTeleportsOverlay.Display display;
	private volatile boolean running;
	private String profileKey;
	private String learningHint = "Enter via Home or Teleport to House";

	@Override
	protected void startUp()
	{
		running = true;
		routing = new AsyncRoutePlanner();
		log.info("POH Clue Teleports started with house entry detection");
		houseContext.reset();
		observations.clear();
		pendingFixtures.clear();
		pendingInventory = null;
		overlayManager.add(overlay);
		learningOverlay = new HouseLearningOverlay(client, this::getGuidance);
		overlayManager.add(learningOverlay);
		clientThread.invokeLater(() -> refresh(false));
	}

	@Override
	protected void shutDown()
	{
		running = false;
		if (routing != null) routing.close();
		routing = null;
		clearGuidance();
		ownHouse = false;
		houseInventory = new HouseInventory();
		display = null;
		profileKey = null;
		availability = new AvailabilityCache();
		houseContext.reset();
		observations.clear();
		pendingFixtures.clear();
		pendingInventory = null;
		overlayManager.remove(overlay);
		if (learningOverlay != null) overlayManager.remove(learningOverlay);
		learningOverlay = null;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		refresh(true);
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (running)
		{
			houseContext.onMenuOptionClicked(event, client);
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		int group = event.getGroupId();
		if (running && (group == InterfaceID.FAIRYRINGS || group == InterfaceID.FAIRYRINGS_LOG))
		{
			fairyTravelLog.reset();
		}
		if (running && group == InterfaceID.TELENEXUS_TELEPORT)
		{
			nexusMenuScroll.reset();
		}
		if (running && (group == InterfaceID.TELENEXUS_TELEPORT || group == InterfaceID.POH_JEWELLERY_BOX
			|| group == InterfaceID.FAIRYRINGS || group == InterfaceID.MENU || group == InterfaceID.MENU_NEW))
		{
			log.debug("Travel interface {} opened; own house confirmed={}", group, houseContext.isOwnHouse(client));
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		houseContext.onGameStateChanged(event.getGameState());
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			invalidateRoute();
			ownHouse = false;
			clearGuidance();
			display = null;
			observations.clear();
			pendingFixtures.clear();
			pendingInventory = null;
		}
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			profileKey = null;
			availability = new AvailabilityCache();
		}
	}

	private void refresh(boolean learnFromHouse)
	{
		refreshDisplay(learnFromHouse);
		HouseLearningOverlay.Guidance current = guidance;
		fairyTravelLog.update(client, running && current.isOwnHouse() && current.getSource() == TeleportSource.FAIRY_RING
			? current.getDestinationId() : null);
		nexusMenuScroll.update(client, running && current.isOwnHouse() && current.getSource() == TeleportSource.PORTAL_NEXUS
			? current.getDestinationId() : null);
	}

	private void refreshDisplay(boolean learnFromHouse)
	{
		if (!running)
		{
			return;
		}
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		String currentProfile = loggedIn ? configManager.getRSProfileKey() : null;
		if (!Objects.equals(profileKey, currentProfile))
		{
			if (profileKey != null)
			{
				houseContext.reset();
			}
			invalidateRoute();
			profileKey = currentProfile;
			availability = new AvailabilityCache();
			houseInventory = new HouseInventory();
			ownHouse = false;
			clearGuidance();
			observations.clear();
			pendingFixtures.clear();
			pendingInventory = null;
		}
		if (!loggedIn || currentProfile == null)
		{
			invalidateRoute();
			clearGuidance();
			display = null;
			return;
		}

		for (TeleportSource source : TeleportSource.values())
		{
			availability.restore(source, configManager.getRSProfileConfiguration(CONFIG_GROUP, source.getCacheKey()));
		}
		houseInventory.restore(configManager.getRSProfileConfiguration(CONFIG_GROUP, HOUSE_INVENTORY_KEY));
		if (learnFromHouse)
		{
			observeHouseTravel();
		}
		Set<String> selected = availability.availableIds().stream()
			.filter(id -> TeleportCatalog.byId(id).map(destination -> houseInventory.installedSources().contains(destination.getSource())).orElse(false))
			.filter(id -> CapeReader.availableNow(client, id)).collect(Collectors.toSet());

		// Use the managed dependency; injecting its class can construct an inactive
		// second instance on clients that export only ClueScrollService.
		ClueScrollPlugin clues = pluginManager.getPlugins().stream()
			.filter(ClueScrollPlugin.class::isInstance).map(ClueScrollPlugin.class::cast)
			.filter(pluginManager::isPluginEnabled).findFirst().orElse(null);
		ClueTargetResolver.Resolution target = targetResolver.resolve(clues);
		Map<TeleportSource, Set<String>> learned = availability.snapshot();
		Set<TeleportSource> required = houseInventory.requiredMenus();
		Set<TeleportSource> pending = EnumSet.noneOf(TeleportSource.class);
		pending.addAll(required);
		pending.removeAll(learned.keySet());
		guidance = new HouseLearningOverlay.Guidance(ownHouse, pending, null, null);
		boolean hasClue = target.getState() != ClueTargetResolver.State.NO_CLUE;
		if (!hasClue && !ownHouse)
		{
			invalidateRoute();
			display = null;
			return;
		}
		if (!houseInventory.isSurveyed())
		{
			invalidateRoute();
			display = new ClueTeleportsOverlay.Display(ownHouse ? "Checking POH facilities" : "Visit your POH",
				ownHouse ? "Wait for the house to finish loading" : "Enter via Home or Teleport to House", null);
			return;
		}
		if (!pending.isEmpty())
		{
			invalidateRoute();
			display = ClueTeleportsOverlay.Display.learning(learned, required, learningHint);
			return;
		}
		if (!hasClue)
		{
			invalidateRoute();
			display = null;
			return;
		}
		switch (target.getState())
		{
			case NO_LOCATION:
				invalidateRoute();
				display = new ClueTeleportsOverlay.Display("Clue location not known", "Follow the clue's current task", null);
				break;
			case MULTIPLE_LOCATIONS:
				if (!target.hasAlternativeTaskLocations())
				{
					invalidateRoute();
					display = new ClueTeleportsOverlay.Display("Multiple clue locations", "Narrow down the current clue", null);
					break;
				}
				// Known alternative task sites are all valid, unlike unresolved clue steps.
			case RESOLVED:
				if (selected.isEmpty())
				{
					invalidateRoute();
					display = new ClueTeleportsOverlay.Display("No available POH teleports", "No usable destinations in learned sources", null);
					break;
				}
				TeleportRouting.Plan route = routing == null ? TeleportRouting.Plan.status(TeleportRouting.Plan.Status.UNAVAILABLE)
					: routing.update(client, profileKey, target.getLocations(), TeleportCatalog.all().stream()
						.filter(destination -> selected.contains(destination.getId())).collect(Collectors.toList()), target.getInteractionRadius());
				if (route.status == TeleportRouting.Plan.Status.FOUND)
				{
					guidance = new HouseLearningOverlay.Guidance(ownHouse, pending,
						route.destination.getSource(), route.destination.getId());
					display = new ClueTeleportsOverlay.Display(route.destination.getSource().getDisplayName(),
						route.destination.getName(), describeRoute(route));
				}
				else display = routeStatus(route.status);
				break;
		}
	}


	private void invalidateRoute()
	{
		if (routing != null) routing.invalidate();
	}

	private static String describeRoute(TeleportRouting.Plan route)
	{
		long seconds = (long) Math.ceil(route.costHalfTicks * 0.3);
		String duration = seconds < 60 ? seconds + "s" : seconds / 60 + "m " + seconds % 60 + "s";
		return "~" + duration + " running, " + route.walkingTiles + " walking tiles";
	}

	private static ClueTeleportsOverlay.Display routeStatus(TeleportRouting.Plan.Status status)
	{
		switch (status)
		{
			case PREPARING: return new ClueTeleportsOverlay.Display("Loading walking map", "Preparing paths and passage data", null);
			case SEARCHING: return new ClueTeleportsOverlay.Display("Finding best POH route", "Checking paths and usable shortcuts", null);
			case LIMIT: return new ClueTeleportsOverlay.Display("Route search incomplete", "Minimum route could not be confirmed", null);
			case NO_ROUTE: return new ClueTeleportsOverlay.Display("No mapped walking route", "Known paths do not reach this clue", null);
			default: return new ClueTeleportsOverlay.Display("Walking routes unavailable", "Unable to calculate a walking route", null);
		}
	}

	private void observeHouseTravel()
	{
		ownHouse = houseContext.isOwnHouse(client);
		if (!ownHouse)
		{
			learningHint = "Enter via Home or Teleport to House";
			observations.clear();
			pendingFixtures.clear();
			pendingInventory = null;
			return;
		}
		learningHint = "Open the travel menus marked Not learned";
		HouseTransportReader.Observation fixtureReading = HouseTransportReader.readSnapshot(client);
		recordHouseInventory(fixtureReading);
		recordFixtures(TeleportSource.PORTAL_CHAMBER, fixtureReading.coveredTiles, fixtureReading.portalFixtures);
		recordFixtures(TeleportSource.CAPE_HANGER, fixtureReading.coveredTiles, fixtureReading.capeFixtures);
		Map<TeleportSource, Set<String>> fixtures = fixtureReading.sources;
		for (TeleportSource source : TeleportSource.values())
		{
			if (TeleportSource.menuSources().contains(source) || source == TeleportSource.PORTAL_CHAMBER
				|| source == TeleportSource.CAPE_HANGER)
			{
				continue;
			}
			Optional<Set<String>> reading = Optional.ofNullable(fixtures.get(source));
			recordObservation(source, reading);
		}
		for (TeleportSource source : TeleportSource.menuSources())
		{
			if (!houseInventory.installedSources().contains(source) && !fixtureReading.installedSources.contains(source))
			{
				observations.observe(source, Optional.empty());
				continue;
			}
			Optional<Set<String>> reading;
			switch (source)
			{
				case FAIRY_RING:
					reading = FairyRingReader.readOpenMenu(client);
					break;
				case SPIRIT_TREE:
					reading = SpiritTreeReader.readOpenMenu(client);
					break;
				case PORTAL_NEXUS:
					reading = NexusImporter.readOpenMenu(client);
					break;
				case JEWELLERY_BOX:
					reading = JewelleryBoxReader.readOpenMenu(client);
					break;
				case MOUNTED_DIGSITE_PENDANT:
				case MOUNTED_XERICS_TALISMAN:
					reading = Optional.ofNullable(fixtures.get(source));
					break;
				default:
					throw new IllegalStateException("Unknown teleport source: " + source);
			}
			if (reading.isPresent())
			{
				learningHint = "Reading " + source.getDisplayName() + " destinations";
			}
			recordObservation(source, reading);
		}
	}


	private void recordHouseInventory(HouseTransportReader.Observation reading)
	{
		if (reading.coveredTiles.isEmpty() || !houseInventory.isSurveyed() && !reading.sceneReady)
		{
			pendingInventory = null;
			return;
		}
		HouseInventory next = new HouseInventory();
		next.restore(houseInventory.isSurveyed() ? houseInventory.encode() : null);
		next.observe(reading.coveredTiles, reading.installedFixtures, reading.installedFixtureIds);
		String encoded = next.encode();
		if (encoded.equals(pendingInventory))
		{
			if (houseInventory.isSurveyed())
			{
				for (TeleportSource source : next.requiredMenus())
				{
					if (!houseInventory.installedSources().contains(source)
						|| !houseInventory.capabilitySignature(source).isEmpty()
							&& !houseInventory.capabilitySignature(source).equals(next.capabilitySignature(source)))
					{
						configManager.unsetRSProfileConfiguration(CONFIG_GROUP, source.getCacheKey());
						availability.restore(source, null);
						observations.observe(source, Optional.empty());
					}
				}
			}
			String saved = configManager.getRSProfileConfiguration(CONFIG_GROUP, HOUSE_INVENTORY_KEY);
			if (!encoded.equals(saved)) configManager.setRSProfileConfiguration(CONFIG_GROUP, HOUSE_INVENTORY_KEY, encoded);
			houseInventory = next;
		}
		pendingInventory = encoded;
	}

	private void clearGuidance()
	{
		fairyTravelLog.reset();
		nexusMenuScroll.reset();
		guidance = new HouseLearningOverlay.Guidance(false, Collections.emptySet(), null, null);
	}

	HouseLearningOverlay.Guidance getGuidance() { return guidance; }

	private void recordFixtures(TeleportSource source, Set<String> coveredTiles, Map<String, Set<String>> seen)
	{
		String key = source.getCacheKey() + "Fixtures";
		String saved = configManager.getRSProfileConfiguration(CONFIG_GROUP, key);
		if (coveredTiles.isEmpty() || saved == null && seen.isEmpty())
		{
			pendingFixtures.remove(source);
			return;
		}
		FixtureCache fixtures = new FixtureCache(source);
		fixtures.restore(saved);
		fixtures.observe(coveredTiles, seen);
		String next = fixtures.encode();
		String pending = pendingFixtures.put(source, next);
		if (next.equals(pending) && running && Objects.equals(profileKey, configManager.getRSProfileKey()))
		{
			if (!next.equals(saved))
			{
				configManager.setRSProfileConfiguration(CONFIG_GROUP, key, next);
			}
			recordAvailable(source, fixtures.availableIds());
		}
	}

	private void recordAvailable(TeleportSource source, Set<String> ids)
	{
		if (availability.record(source, ids))
		{
			configManager.setRSProfileConfiguration(CONFIG_GROUP, source.getCacheKey(), AvailableTeleports.encode(ids));
			log.info("Cached {} {} destinations", ids.size(), source.getDisplayName());
		}
	}

	private void recordObservation(TeleportSource source, Optional<Set<String>> reading)
	{
		observations.observe(source, reading).ifPresent(ids ->
		{
			if (running && Objects.equals(profileKey, configManager.getRSProfileKey()))
			{
				recordAvailable(source, ids);
			}
		});
	}

	void forgetAvailability()
	{
		String expectedProfile = profileKey;
		clientThread.invokeLater(() ->
		{
			if (!running || expectedProfile == null || client.getGameState() != GameState.LOGGED_IN
				|| !expectedProfile.equals(configManager.getRSProfileKey()))
			{
				return;
			}
			for (TeleportSource source : TeleportSource.values())
			{
				configManager.unsetRSProfileConfiguration(CONFIG_GROUP, source.getCacheKey());
				configManager.unsetRSProfileConfiguration(CONFIG_GROUP, source.getCacheKey() + "Fixtures");
			}
			configManager.unsetRSProfileConfiguration(CONFIG_GROUP, HOUSE_INVENTORY_KEY);
			houseInventory = new HouseInventory();
			observations.clear();
			pendingFixtures.clear();
			pendingInventory = null;
			refresh(false);
		});
	}

	ClueTeleportsOverlay.Display getDisplay()
	{
		return display;
	}

}

package com.clueteleports;

import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

/**
 * Captures known fairy-ring access when the player opens the code selector.
 *
 * The travel log records visits, not the full set of available destinations.
 * Ordinary unvisited rings are therefore included, and restricted rings use
 * quest and region access state. Prior successful travel is only a positive
 * fallback for partial-quest or island access that cannot be fully established
 * from a published client-side requirement.
 *
 * Network permission: runelite/cs2-scripts [proc,helper_agility_requirements].
 * Travel-log semantics: [proc,script7866] and [proc,script7317].
 * Current ring requirements: https://oldschool.runescape.wiki/w/Fairy_rings .
 * BLQ's LOTG stage >= 50 also appears in shortest-path/fairy_rings.tsv at
 * 50f30435f37d1d5c5e2af790925fa7aa70b7840d.
 *
 * BJR and AKP can unlock before quest completion; without a previous successful
 * visit they are conservatively omitted until their quest is complete. CJQ can
 * unlock before Troubled Tortugans; a previous successful visit is accepted.
 * This class never treats a missing travel-log entry as a general access denial.
 * Invoke on the client thread; the same read-only status script as Quest.getState is used.
 */
public final class FairyRingReader
{
	private static final Quest[] ACCESS_QUESTS = {
		Quest.DEATH_TO_THE_DORGESHUUN,
		Quest.REGICIDE,
		Quest.THE_FREMENNIK_TRIALS,
		Quest.MONKEY_MADNESS_I,
		Quest.IN_SEARCH_OF_THE_MYREQUE,
		Quest.HOLY_GRAIL,
		Quest.BENEATH_CURSED_SANDS,
		Quest.TROUBLED_TORTUGANS
	};

	private FairyRingReader()
	{
	}

	/**
	 * Empty means the selector is closed or not ready; it must not replace an
	 * existing character snapshot. A result contains only positively known access.
	 */
	public static Optional<Set<String>> readOpenMenu(Client client)
	{
		Widget confirm = client.getWidget(InterfaceID.Fairyrings.CONFIRM);
		Widget log = client.getWidget(InterfaceID.FairyringsLog.CONTENTS);
		if (confirm == null || confirm.isHidden() || log == null || log.isHidden()
			|| confirm.getText() == null || confirm.getText().isBlank())
		{
			return Optional.empty();
		}
		if (client.getVarbitValue(VarbitID.FAIRYRING_USE) < 1
			|| client.getVarbitValue(VarbitID.FAIRYRING_PERMISSION) < 2)
		{
			return Optional.empty();
		}

		Map<Quest, QuestState> quests = new EnumMap<>(Quest.class);
		for (Quest quest : ACCESS_QUESTS)
		{
			client.runScript(ScriptID.QUEST_STATUS_GET, quest.getId());
			int[] stack = client.getIntStack();
			if (stack == null || stack.length == 0 || stack[0] < 0 || stack[0] > 2)
			{
				return Optional.empty();
			}
			quests.put(quest, stack[0] == 2 ? QuestState.FINISHED
				: stack[0] == 1 ? QuestState.NOT_STARTED : QuestState.IN_PROGRESS);
		}

		Set<String> available = new LinkedHashSet<>();
		for (TeleportDestination destination : TeleportCatalog.forSource(TeleportSource.FAIRY_RING))
		{
			if (accessible(client, quests, destination.getId()))
			{
				available.add(destination.getId());
			}
		}
		return Optional.of(Collections.unmodifiableSet(available));
	}

	private static boolean accessible(Client client, Map<Quest, QuestState> quests, String id)
	{
		switch (id)
		{
			case "fairy-ais":
			case "fairy-ajp":
			case "fairy-ckq":
				return client.getVarbitValue(VarbitID.VARLAMORE_VISITED) == 1;
			case "fairy-akr":
			case "fairy-bls":
			case "fairy-cir":
			case "fairy-cis":
			case "fairy-djr":
				return client.getVarbitValue(VarbitID.ZEAH_PLAYERHASVISITED) == 1;
			case "fairy-ajq":
				return finished(quests, Quest.DEATH_TO_THE_DORGESHUUN);
			case "fairy-bjs":
				return finished(quests, Quest.REGICIDE);
			case "fairy-cip":
				return finished(quests, Quest.THE_FREMENNIK_TRIALS);
			case "fairy-clr":
				return finished(quests, Quest.MONKEY_MADNESS_I);
			case "fairy-dls":
				return finished(quests, Quest.IN_SEARCH_OF_THE_MYREQUE);
			case "fairy-bjr":
				return finished(quests, Quest.HOLY_GRAIL)
					|| client.getVarbitValue(VarbitID.FAIRYRINGS_LOG_BJR) == 1;
			case "fairy-akp":
				return finished(quests, Quest.BENEATH_CURSED_SANDS)
					|| client.getVarbitValue(VarbitID.FAIRYRINGS_LOG_AKP) == 1;
			case "fairy-blq":
				return client.getVarbitValue(VarbitID.LOTG) >= 50;
			case "fairy-cjq":
				return finished(quests, Quest.TROUBLED_TORTUGANS)
					|| client.getVarbitValue(VarbitID.FAIRYRINGS_LOG_CJQ) == 1;
			case "fairy-dlp":
				return client.getVarbitValue(VarbitID.GRIMSTONE_VISITED) == 1;
			default:
				return true;
		}
	}

	private static boolean finished(Map<Quest, QuestState> quests, Quest quest)
	{
		return quests.get(quest) == QuestState.FINISHED;
	}
}

package com.clueteleports;

import java.awt.Rectangle;
import java.util.Locale;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;

/**
 * Brings an existing native travel-log action into view without operating it.
 *
 * Native fairyrings_sort_update (8080) positions the static destination rows
 * inside CONTENTS, and draws their red code labels as separate dynamic text.
 * The static rows retain the native "Use code" action. Their positions follow
 * the selected native sort order, rather than the numeric component order.
 * See runelite/cs2-scripts at 1d418ffb6bce96c2d0712eb2652712d28e01b115,
 * scripts/[proc,fairyrings_sort_update].cs2.
 *
 * Native rebuilds restore FAIRYRINGS_SCROLLPOS, so the one-shot also stores
 * the actual scroll in that client-only UI variable. Later native scrolling
 * owns both values. No game action, script, search, or server variable changes.
 */
public final class FairyRingTravelLog
{
	private static final Pattern TAGS = Pattern.compile("<[^>]*>");
	private static final Pattern DISABLED_COLOUR = Pattern.compile("<col=(?:7f7f7f|808080|999999)>", Pattern.CASE_INSENSITIVE);
	private Widget openContents;
	private String destination;
	private boolean positioned;

	/** Pass null whenever no applicable recommendation should guide this interface. */
	public void update(Client client, String destinationId)
	{
		if (!client.isClientThread())
		{
			throw new IllegalStateException("Fairy-ring travel-log scrolling requires the client thread");
		}
		String code = code(destinationId);
		if (code == null)
		{
			reset();
			return;
		}
		Widget contents = client.getWidget(InterfaceID.FairyringsLog.CONTENTS);
		Widget confirm = client.getWidget(InterfaceID.Fairyrings.CONFIRM);
		Rectangle viewport = bounds(contents);
		if (bounds(confirm) == null || viewport == null)
		{
			reset();
			return;
		}
		if (contents != openContents || !code.equals(destination))
		{
			openContents = contents;
			destination = code;
			positioned = false;
		}
		if (positioned)
		{
			return;
		}
		Widget entry = readableEntry(client, destinationId);
		Rectangle row = bounds(entry);
		if (row == null || row.x >= viewport.x + viewport.width || row.x + row.width <= viewport.x)
		{
			return;
		}
		int scroll = contents.getScrollY();
		int height = contents.getScrollHeight();
		if (scroll < 0)
		{
			return;
		}
		if (row.y >= viewport.y && row.y + row.height <= viewport.y + viewport.height)
		{
			// Even an already-visible row consumes the one-shot. Later manual
			// scrolling must not make the plugin pull the log back again.
			client.setVarcIntValue(VarClientID.FAIRYRINGS_SCROLLPOS, contents.getScrollY());
			positioned = true;
			return;
		}
		int top = row.y - viewport.y + scroll;
		if (top < 0 || height <= 0 || top + row.height > height)
		{
			// A partially hydrated layout must remain eligible for a later retry.
			return;
		}
		int desired = Math.max(0, Math.min(Math.max(0, height - viewport.height),
			top - Math.max(0, (viewport.height - row.height) / 2)));
		if (desired != scroll)
		{
			contents.setScrollY(desired);
			contents.revalidateScroll();
		}
		// fairyrings_sort_update restores this saved UI value on its next
		// rebuild. Store the actual result after any native clamping.
		client.setVarcIntValue(VarClientID.FAIRYRINGS_SCROLLPOS, contents.getScrollY());
		positioned = true;
	}

	public void reset()
	{
		openContents = null;
		destination = null;
		positioned = false;
	}

	/** Returns the existing clickable destination row, including when vertically clipped. */
	static Widget readableEntry(Client client, String destinationId)
	{
		String code = code(destinationId);
		if (code == null || bounds(client.getWidget(InterfaceID.Fairyrings.CONFIRM)) == null
			|| bounds(client.getWidget(InterfaceID.FairyringsLog.CONTENTS)) == null)
		{
			return null;
		}
		int index = "ABCD".indexOf(code.charAt(0)) * 16
			+ "IJKL".indexOf(code.charAt(1)) * 4 + "PQRS".indexOf(code.charAt(2));
		Widget entry = client.getWidget(InterfaceID.FairyringsLog.AIP + index * 2);
		if (bounds(entry) == null)
		{
			return null;
		}
		String text = entry.getText();
		if (text == null || TAGS.matcher(text).replaceAll("").replace('\u00a0', ' ').isBlank()
			|| text.toLowerCase(Locale.ROOT).contains("<str") || DISABLED_COLOUR.matcher(text).find())
		{
			return null;
		}
		int colour = entry.getTextColor();
		if (colour == 0x7f7f7f || colour == 0x808080 || colour == 0x999999)
		{
			return null;
		}
		String[] actions = entry.getActions();
		if (actions != null)
		{
			for (String action : actions)
			{
				if ("Use code".equals(action))
				{
					return entry;
				}
			}
		}
		return null;
	}

	private static String code(String destinationId)
	{
		if (destinationId == null || !destinationId.startsWith("fairy-"))
		{
			return null;
		}
		String code = destinationId.substring(6).toUpperCase(Locale.ROOT);
		return code.matches("[ABCD][IJKL][PQRS]") ? code : null;
	}

	private static Rectangle bounds(Widget widget)
	{
		if (widget == null || widget.isHidden())
		{
			return null;
		}
		Rectangle bounds = widget.getBounds();
		return bounds != null && bounds.width > 0 && bounds.height > 0 ? bounds : null;
	}
}

package com.clueteleports;

import java.util.Collection;
import java.util.Collections;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.stream.Collectors;

/** Keeps separate arrivals for repeated fixtures in positively observed POH tiles. */
final class FixtureCache
{
	private final TeleportSource source;
	private final Map<String, Set<String>> fixtures = new TreeMap<>();

	FixtureCache(TeleportSource source)
	{
		this.source = source;
	}

	void restore(String encoded)
	{
		fixtures.clear();
		if (encoded == null || encoded.isEmpty())
		{
			return;
		}
		for (String entry : encoded.split(";"))
		{
			String[] parts = entry.split("=", 2);
			if (parts.length == 2 && validPosition(parts[0]))
			{
				put(parts[0], AvailableTeleports.decode(parts[1]));
			}
		}
	}

	/** Only loaded, completely read tiles can replace or remove an older fixture. */
	void observe(Set<String> coveredTiles, Map<String, Set<String>> observed)
	{
		coveredTiles.forEach(fixtures::remove);
		observed.forEach((position, ids) ->
		{
			if (validPosition(position) && coveredTiles.contains(position))
			{
				put(position, ids);
			}
		});
	}

	Set<String> availableIds()
	{
		Set<String> ids = new TreeSet<>();
		fixtures.values().forEach(ids::addAll);
		return Collections.unmodifiableSet(ids);
	}

	String encode()
	{
		return fixtures.entrySet().stream().map(entry -> entry.getKey() + "=" + AvailableTeleports.encode(entry.getValue()))
			.collect(Collectors.joining(";"));
	}

	private void put(String position, Collection<String> candidates)
	{
		Set<String> ids = new TreeSet<>();
		for (String id : candidates)
		{
			TeleportCatalog.byId(id).filter(destination -> destination.getSource() == source)
				.ifPresent(destination -> ids.add(id));
		}
		if (!ids.isEmpty())
		{
			fixtures.put(position, Collections.unmodifiableSet(ids));
		}
	}

	private static boolean validPosition(String position)
	{
		if (position == null || !position.matches("[0-3]:[0-9]{1,5}:[0-9]{1,5}"))
		{
			return false;
		}
		String[] coordinates = position.split(":");
		return Integer.parseInt(coordinates[1]) <= 16383 && Integer.parseInt(coordinates[2]) <= 16383;
	}
}

package com.clueteleports;

import java.util.Locale;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

/**
 * Tracks positively identified own-house visits on the client thread.
 *
 * Entry-action classification follows the tested pattern in
 * elzerma/farm-run-autopilot PohDetector/PohDetectorTest at
 * 8fce4102559f9d2aa095dd7eb8fb87884f7cda51, with narrower action scopes and
 * confirmation against RuneLite Discord's POH regions after scene loading.
 * A POH region identifies a house, never its owner by itself.
 */
public final class HouseContext
{
	static final int ENTRY_WINDOW_TICKS = 30;
	// runelite/runelite DiscordGameEventType.REGION_POH at
	// 9fad2c588ca957ae47d883b09544725a796ed9fe.
	private static final Set<Integer> HOUSE_REGIONS = Set.of(7534, 7535, 7790, 7791, 8046, 8047, 8302, 8303);
	private boolean ownHouseConfirmed;
	private int entryTick = -1;
	private boolean entrySawLoading;
	private int outsideAfterLoadingTick = -1;

	public void onGameStateChanged(GameState gameState)
	{
		if (gameState == GameState.LOADING)
		{
			ownHouseConfirmed = false;
			if (entryTick >= 0)
			{
				entrySawLoading = true;
			}
		}
		else if (gameState != GameState.LOGGED_IN)
		{
			reset();
		}
	}

	/** Kept for existing callers; chat is not reliable ownership evidence. */
	public void onChatMessage(ChatMessage event)
	{
	}

	public void onMenuOptionClicked(MenuOptionClicked event, Client client)
	{
		if (event == null || client == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		MenuAction action = event.getMenuAction();
		String option = plain(event.getMenuOption());
		String target = plain(event.getMenuTarget());
		boolean objectAction = isObjectAction(action);
		boolean widgetAction = isWidgetAction(action);
		boolean spell = widgetAction && event.getParam1() == InterfaceID.MagicSpellbook.TELEPORT_TO_YOUR_HOUSE;
		String dialog = "";
		if (action == MenuAction.WIDGET_CONTINUE && (event.getParam1() >>> 16) == InterfaceID.CHATMENU)
		{
			Widget widget = event.getWidget();
			dialog = widget == null ? "" : plain(widget.getText());
		}

		if ((objectAction && ("friend's house".equals(option) || "house advertisement".equals(target)))
			|| (spell && option.startsWith("group:")) || dialog.contains("friend's house"))
		{
			reset();
			return;
		}

		boolean portal = objectAction && "portal".equals(target)
			&& ("home".equals(option) || "build mode".equals(option));
		boolean tablet = (isItemAction(action) || widgetAction) && "break".equals(option)
			&& (event.getItemId() == ItemID.POH_TABLET_TELEPORTTOHOUSE
				|| (isItemAction(action) && event.getId() == ItemID.POH_TABLET_TELEPORTTOHOUSE));
		boolean cape = (isItemAction(action) || widgetAction) && "tele to poh".equals(option)
			&& (event.getItemId() == ItemID.SKILLCAPE_CONSTRUCTION
				|| event.getItemId() == ItemID.SKILLCAPE_CONSTRUCTION_TRIMMED);
		boolean ownDialog = "go to your house.".equals(dialog) || "go to your house".equals(dialog)
			|| "go to your house (building mode).".equals(dialog);
		// RuneLite FairyRingPlugin maps the dials as A/D/C/B, I/L/K/J, P/S/R/Q.
		boolean fairyHouse = widgetAction && event.getParam1() == InterfaceID.Fairyrings.CONFIRM
			&& event.getId() == 1 && client.getVarbitValue(VarbitID.FAIRYRING_1) == 1
			&& client.getVarbitValue(VarbitID.FAIRYRING_2) == 0
			&& client.getVarbitValue(VarbitID.FAIRYRING_3) == 3;

		if (portal || (spell && "cast".equals(option)) || tablet || cape || ownDialog || fairyHouse)
		{
			ownHouseConfirmed = false;
			entryTick = client.getTickCount();
			entrySawLoading = false;
			outsideAfterLoadingTick = -1;
		}
		else if (entryTick >= 0 && (objectAction || action == MenuAction.WALK || action == MenuAction.WIDGET_CONTINUE))
		{
			// A player can open a house travel menu before the next game tick.
			// Settle the loaded arrival before consuming its entry evidence.
			if (entrySawLoading)
			{
				isOwnHouse(client);
			}
			// A failed teleport must not authorize a later unrelated entrance.
			clearEntry();
		}
	}

	public boolean isOwnHouse(Client client)
	{
		if (client == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return false;
		}
		int tick = client.getTickCount();
		if (entryTick >= 0 && (tick < entryTick || tick - entryTick > ENTRY_WINDOW_TICKS))
		{
			clearEntry();
		}
		if (!isHouse(client))
		{
			ownHouseConfirmed = false;
			if (entrySawLoading)
			{
				// Entry can briefly load the outside portal before the house rooms.
				// Allow that first tick, but discard a settled outside arrival.
				if (outsideAfterLoadingTick < 0)
				{
					outsideAfterLoadingTick = tick;
				}
				else if (tick != outsideAfterLoadingTick)
				{
					clearEntry();
				}
			}
			return false;
		}
		if (client.getVarbitValue(VarbitID.POH_BUILDING_MODE) == 1 || (entryTick >= 0 && entrySawLoading))
		{
			ownHouseConfirmed = true;
			// Keep the bounded entry evidence through chained house loads. A tick
			// can occur between the two LOADING/LOGGED_IN cycles on real entry.
		}
		return ownHouseConfirmed;
	}

	public void reset()
	{
		ownHouseConfirmed = false;
		clearEntry();
	}

	private void clearEntry()
	{
		entryTick = -1;
		entrySawLoading = false;
		outsideAfterLoadingTick = -1;
	}

	private static boolean isHouse(Client client)
	{
		Player player = client.getLocalPlayer();
		LocalPoint local = player == null ? null : player.getLocalLocation();
		if (local == null)
		{
			return false;
		}
		WorldView view = client.getWorldView(local.getWorldView());
		if (view == null)
		{
			return false;
		}
		if (view.isInstance())
		{
			int[][][] chunks = view.getInstanceTemplateChunks();
			int plane = view.getPlane();
			int x = local.getSceneX() / 8;
			int y = local.getSceneY() / 8;
			if (chunks == null || plane < 0 || plane >= chunks.length || chunks[plane] == null
				|| x < 0 || x >= chunks[plane].length || chunks[plane][x] == null
				|| y < 0 || y >= chunks[plane][x].length || chunks[plane][x][y] == -1)
			{
				return false;
			}
		}
		return HOUSE_REGIONS.contains(WorldPoint.fromLocalInstance(client, local).getRegionID());
	}

	private static boolean isObjectAction(MenuAction action)
	{
		return action == MenuAction.GAME_OBJECT_FIRST_OPTION || action == MenuAction.GAME_OBJECT_SECOND_OPTION
			|| action == MenuAction.GAME_OBJECT_THIRD_OPTION || action == MenuAction.GAME_OBJECT_FOURTH_OPTION
			|| action == MenuAction.GAME_OBJECT_FIFTH_OPTION;
	}

	private static boolean isWidgetAction(MenuAction action)
	{
		return action == MenuAction.CC_OP || action == MenuAction.CC_OP_LOW_PRIORITY
			|| action == MenuAction.WIDGET_TYPE_1;
	}

	private static boolean isItemAction(MenuAction action)
	{
		return action == MenuAction.ITEM_FIRST_OPTION || action == MenuAction.ITEM_SECOND_OPTION
			|| action == MenuAction.ITEM_THIRD_OPTION || action == MenuAction.ITEM_FOURTH_OPTION
			|| action == MenuAction.ITEM_FIFTH_OPTION;
	}

	private static String plain(String text)
	{
		return text == null ? "" : Text.removeTags(text).trim().toLowerCase(Locale.ROOT);
	}
}

package com.clueteleports;

import java.util.Collections;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.stream.Collectors;
import net.runelite.api.gameval.ObjectID;

/** Positive, per-position observations; unseen rooms never establish absence. */
final class HouseInventory
{
	private final Map<String, Set<TeleportSource>> fixtures = new TreeMap<>();
	private final Map<String, Set<Integer>> fixtureIds = new TreeMap<>();
	private boolean surveyed;

	void restore(String encoded)
	{
		fixtures.clear();
		fixtureIds.clear();
		surveyed = encoded != null;
		if (encoded == null || encoded.isEmpty())
		{
			return;
		}
		for (String entry : encoded.split(";"))
		{
			String[] parts = entry.split("=", 2);
			if (parts.length != 2 || !validPosition(parts[0]))
			{
				continue;
			}
			// Legacy entries contain sources only. Missing IDs mean unknown
			// version evidence, preserving previously learned menus on upgrade.
			String[] versioned = parts[1].split("#", 2);
			Set<TeleportSource> sources = EnumSet.noneOf(TeleportSource.class);
			for (String value : versioned[0].split(","))
			{
				try
				{
					sources.add(TeleportSource.valueOf(value.trim()));
				}
				catch (IllegalArgumentException ignored)
				{
					// Unknown future source.
				}
			}
			if (!sources.isEmpty())
			{
				fixtures.put(parts[0], sources);
				fixtureIds.remove(parts[0]);
				Set<Integer> ids = new TreeSet<>();
				if (versioned.length == 2)
				{
					for (String value : versioned[1].split(","))
					{
						try
						{
							int id = Integer.parseInt(value.trim());
							if (id > 0)
							{
								ids.add(id);
							}
						}
						catch (NumberFormatException ignored)
						{
							// Malformed version evidence cannot identify a fixture.
						}
					}
				}
				if (!ids.isEmpty())
				{
					fixtureIds.put(parts[0], ids);
				}
			}
		}
	}

	void observe(Set<String> coveredTiles, Map<String, Set<TeleportSource>> observed)
	{
		observe(coveredTiles, observed, Collections.emptyMap());
	}

	/** Only completely read, loaded positions replace earlier fixture versions. */
	void observe(Set<String> coveredTiles, Map<String, Set<TeleportSource>> observed,
		Map<String, Set<Integer>> observedIds)
	{
		coveredTiles.forEach(position ->
		{
			fixtures.remove(position);
			fixtureIds.remove(position);
		});
		observed.forEach((position, sources) ->
		{
			if (validPosition(position) && coveredTiles.contains(position) && !sources.isEmpty())
			{
				fixtures.put(position, EnumSet.copyOf(sources));
				Set<Integer> ids = observedIds.get(position);
				if (ids != null)
				{
					Set<Integer> validIds = ids.stream().filter(id -> id != null && id > 0)
						.collect(Collectors.toCollection(TreeSet::new));
					if (!validIds.isEmpty())
					{
						fixtureIds.put(position, validIds);
					}
				}
			}
		});
		surveyed = true;
	}

	boolean isSurveyed()
	{
		return surveyed;
	}

	Set<TeleportSource> installedSources()
	{
		Set<TeleportSource> sources = EnumSet.noneOf(TeleportSource.class);
		fixtures.values().forEach(sources::addAll);
		return Collections.unmodifiableSet(sources);
	}

	Set<TeleportSource> requiredMenus()
	{
		Set<TeleportSource> menus = EnumSet.noneOf(TeleportSource.class);
		menus.addAll(installedSources());
		menus.retainAll(TeleportSource.menuSources());
		return Collections.unmodifiableSet(menus);
	}

	/**
	 * Position-independent native capability evidence. An empty signature means
	 * no version is known, including inventories written before IDs were stored.
	 * Repeated identical fixtures and moves do not change the union. Default
	 * jewellery destinations normalize to their box tier; other exact native
	 * changes conservatively require the caller to learn the menu again.
	 */
	String capabilitySignature(TeleportSource source)
	{
		Set<Integer> ids = new TreeSet<>();
		fixtures.forEach((position, sources) ->
		{
			if (sources.contains(source))
			{
				for (int id : fixtureIds.getOrDefault(position, Collections.emptySet()))
				{
					// More than one wall/game fixture can occupy one tile. Only
					// this menu's native objects identify its capability version.
					if (!TeleportSource.menuSources().contains(source)
						|| HouseTransportReader.interfaceSources(id).contains(source))
					{
						ids.add(capabilityId(source, id));
					}
				}
			}
		});
		return ids.stream().map(String::valueOf).collect(Collectors.joining(","));
	}

	String encode()
	{
		return fixtures.entrySet().stream().map(entry ->
		{
			String sources = entry.getValue().stream().map(Enum::name).collect(Collectors.joining(","));
			Set<Integer> ids = fixtureIds.getOrDefault(entry.getKey(), Collections.emptySet());
			String version = ids.isEmpty() ? "" : "#" + ids.stream().map(String::valueOf).collect(Collectors.joining(","));
			return entry.getKey() + "=" + sources + version;
		}).collect(Collectors.joining(";"));
	}

	private static int capabilityId(TeleportSource source, int id)
	{
		if (source != TeleportSource.JEWELLERY_BOX)
		{
			return id;
		}
		// Verified RuneLite gameval ObjectID ranges contain only each tier's
		// built default-destination variants, plus its Colosseum variant.
		if (id == ObjectID.POH_JEWELLERY_BOX_1 || id == ObjectID.POH_JEWELLERY_BOX_1_COLOSSEUM
			|| id >= ObjectID.POH_JEWELLERY_BOX_1_BASE && id <= ObjectID.POH_JEWELLERY_BOX_1_WINTERTODT)
		{
			return ObjectID.POH_JEWELLERY_BOX_1;
		}
		if (id == ObjectID.POH_JEWELLERY_BOX_2 || id == ObjectID.POH_JEWELLERY_BOX_2_COLOSSEUM
			|| id >= ObjectID.POH_JEWELLERY_BOX_2_BASE && id <= ObjectID.POH_JEWELLERY_BOX_2_FARMING_GUILD)
		{
			return ObjectID.POH_JEWELLERY_BOX_2;
		}
		if (id == ObjectID.POH_JEWELLERY_BOX_3 || id == ObjectID.POH_JEWELLERY_BOX_3_COLOSSEUM
			|| id >= ObjectID.POH_JEWELLERY_BOX_3_BASE && id <= ObjectID.POH_JEWELLERY_BOX_3_KHARID)
		{
			return ObjectID.POH_JEWELLERY_BOX_3;
		}
		return id;
	}

	private static boolean validPosition(String position)
	{
		if (position == null || !position.matches("[0-3]:[0-9]{1,5}:[0-9]{1,5}"))
		{
			return false;
		}
		String[] coordinates = position.split(":");
		return Integer.parseInt(coordinates[1]) <= 16383 && Integer.parseInt(coordinates[2]) <= 16383;
	}
}

package com.clueteleports;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.function.Supplier;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.Text;

/**
 * Read-only visual guidance over native POH travel controls.
 *
 * Native geometry uses Widget.getBounds. Menu containers follow the same cs2
 * scripts as the availability readers:
 * menu_createentry, menu_new_createentry, poh_jewellery_box_addbutton, and
 * telenexus_teleport_init / script2675. Nexus text rows are TEXT1 and EXTRAS.
 * Fairy-ring guidance marks only an existing clickable travel-log entry.
 * Missing or hidden entries do not produce dial or teleport-control guidance.
 *
 * https://github.com/runelite/cs2-scripts/tree/1d418ffb6bce96c2d0712eb2652712d28e01b115/scripts
 */
public final class HouseLearningOverlay extends Overlay
{
	static final Color LEARNING = new Color(255, 196, 93);
	static final Color RECOMMENDED = new Color(70, 220, 235);
	private static final Color BACKGROUND = new Color(20, 24, 27, 235);
	private static final Pattern KEY_PREFIX = Pattern.compile("^[^:]+:\\s*");
	private static final Pattern COLORED_KEY_PREFIX = Pattern.compile(
		"^<col=[0-9a-fA-F]+>[^<]*(?::</col>|</col>\\s*:)\\s*");
	private static final int[][] DIAL_BUTTONS = {
		{InterfaceID.Fairyrings._1_CLOCKWISE, InterfaceID.Fairyrings._1_ANTICLOCKWISE},
		{InterfaceID.Fairyrings._2_CLOCKWISE, InterfaceID.Fairyrings._2_ANTICLOCKWISE},
		{InterfaceID.Fairyrings._3_CLOCKWISE, InterfaceID.Fairyrings._3_ANTICLOCKWISE}
	};
	private static final int[] BOX_SECTIONS = {InterfaceID.PohJewelleryBox.DUELING, InterfaceID.PohJewelleryBox.GAMING,
		InterfaceID.PohJewelleryBox.COMBAT, InterfaceID.PohJewelleryBox.SKILLS,
		InterfaceID.PohJewelleryBox.WEALTH, InterfaceID.PohJewelleryBox.GLORY};

	private final Client client;
	private final Supplier<Guidance> guidance;

	public HouseLearningOverlay(Client client, Supplier<Guidance> guidance)
	{
		this.client = Objects.requireNonNull(client);
		this.guidance = Objects.requireNonNull(guidance);
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		for (Mark mark : marks(guidance.get()))
		{
			Graphics2D copy = (Graphics2D) graphics.create();
			try
			{
				if (mark.clip != null)
				{
					copy.clip(mark.clip);
				}
				copy.setColor(new Color(mark.color.getRed(), mark.color.getGreen(), mark.color.getBlue(), 22));
				copy.fill(mark.shape);
				copy.setColor(mark.color);
				copy.setStroke(new BasicStroke(2));
				copy.draw(mark.shape);
			}
			finally
			{
				copy.dispose();
			}
			if (mark.label != null)
			{
				drawLabel(graphics, mark);
			}
		}
		return null;
	}

	/** Package-visible geometry permits regression tests without a live client. */
	List<Mark> marks(Guidance state)
	{
		if (state == null || !state.ownHouse)
		{
			return Collections.emptyList();
		}
		List<Mark> result = new ArrayList<>();
		Map<TeleportSource, Rectangle> open = new EnumMap<>(TeleportSource.class);
		Widget confirm = visible(InterfaceID.Fairyrings.CONFIRM);
		if (confirm != null)
		{
			open.put(TeleportSource.FAIRY_RING, fairySelector(confirm));
		}
		putOpen(open, TeleportSource.PORTAL_NEXUS, InterfaceID.TelenexusTeleport.UNIVERSE);
		putOpen(open, TeleportSource.JEWELLERY_BOX, InterfaceID.PohJewelleryBox.UNIVERSE);
		Widget generic = genericMenu();
		if (generic != null)
		{
			String first = firstLabel(generic);
			if ("tree gnome village".equals(first))
			{
				open.put(TeleportSource.SPIRIT_TREE, genericClip(generic));
			}
			else if ("digsite".equals(first))
			{
				open.put(TeleportSource.MOUNTED_DIGSITE_PENDANT, genericClip(generic));
			}
			else if ("xeric's lookout".equals(first))
			{
				open.put(TeleportSource.MOUNTED_XERICS_TALISMAN, genericClip(generic));
			}
		}
		for (TeleportSource pending : state.pendingSources)
		{
			Rectangle bounds = open.get(pending);
			if (bounds != null)
			{
				result.add(new Mark(bounds, null, LEARNING, "Learning destinations"));
			}
		}

		TeleportDestination selected = TeleportCatalog.byId(state.destinationId)
			.filter(destination -> destination.getSource() == state.source).orElse(null);
		if (selected != null)
		{
			if (selected.getSource() == TeleportSource.FAIRY_RING && confirm != null)
			{
				fairyMarks(result, selected);
			}
			else if (selected.getSource() == TeleportSource.PORTAL_NEXUS
				&& open.containsKey(TeleportSource.PORTAL_NEXUS))
			{
				Rectangle clip = bounds(visible(InterfaceID.TelenexusTeleport.SCROLLING1));
				addRows(result, client.getWidget(InterfaceID.TelenexusTeleport.TEXT1), clip, selected);
				addRows(result, client.getWidget(InterfaceID.TelenexusTeleport.EXTRAS), clip, selected);
			}
			else if (selected.getSource() == TeleportSource.JEWELLERY_BOX
				&& open.containsKey(TeleportSource.JEWELLERY_BOX))
			{
				for (int component : BOX_SECTIONS)
				{
					addRows(result, client.getWidget(component), open.get(TeleportSource.JEWELLERY_BOX), selected);
				}
			}
			else if (generic != null && (open.containsKey(selected.getSource())
				|| !TeleportSource.menuSources().contains(selected.getSource()) && open.isEmpty()))
			{
				// A shared destination name must not redirect a recommendation to
				// a different source. Other fixture menus have no learning interface.
				addRows(result, generic, genericClip(generic), selected);
			}
		}

		return Collections.unmodifiableList(result);
	}

	private void fairyMarks(List<Mark> marks, TeleportDestination selected)
	{
		Widget entry = FairyRingTravelLog.readableEntry(client, selected.getId());
		Rectangle logClip = bounds(visible(InterfaceID.FairyringsLog.CONTENTS));
		if (entry != null && logClip != null)
		{
			String code = selected.getId().substring("fairy-".length()).toUpperCase(Locale.ROOT);
			addRectangle(marks, entry.getBounds(), logClip, RECOMMENDED, "Use " + code);
		}
	}

	private Rectangle fairySelector(Widget confirm)
	{
		Rectangle selector = new Rectangle(confirm.getBounds());
		for (int[] controls : DIAL_BUTTONS)
		{
			for (int component : controls)
			{
				Rectangle control = bounds(visible(component));
				if (control != null)
				{
					selector = selector.union(control);
				}
			}
		}
		selector.grow(4, 4);
		return selector;
	}

	private void addRows(List<Mark> marks, Widget container, Rectangle clip, TeleportDestination selected)
	{
		if (container == null || container.isHidden())
		{
			return;
		}
		Widget[] rows = container.getDynamicChildren();
		if (rows == null)
		{
			return;
		}
		for (Widget row : rows)
		{
			if (matchesAvailableRow(selected, row))
			{
				addRectangle(marks, row.getBounds(), clip, RECOMMENDED, null);
			}
		}
	}

	/** Scrolling and highlighting must agree on the existing enabled menu entry. */
	static boolean matchesAvailableRow(TeleportDestination selected, Widget row)
	{
		if (selected == null || row == null || row.isHidden())
		{
			return false;
		}
		String label = stripKey(row.getText());
		String markup = label.toLowerCase(Locale.ROOT);
		return !markup.contains("<str") && !markup.contains("<col=")
			&& row.getTextColor() != 0x7f7f7f && row.getTextColor() != 0x808080
			&& matches(selected, label);
	}

	static boolean matches(TeleportDestination selected, String row)
	{
		String label = normalize(row);
		if (label.equals(normalize(selected.getName())))
		{
			return true;
		}
		if (selected.getSource() == TeleportSource.PORTAL_NEXUS)
		{
			return TeleportCatalog.nexusDestination(Text.removeTags(row).trim())
				.map(destination -> destination.getId().equals(selected.getId())).orElse(false);
		}
		if (selected.getSource() == TeleportSource.CAPE_HANGER)
		{
			String name = normalize(selected.getName());
			if (name.startsWith("poh portal - "))
			{
				return label.equals(name.substring("poh portal - ".length()));
			}
			if (selected.getId().startsWith("cape-diary-"))
			{
				return label.endsWith(" - " + name) || label.startsWith(name + " (");
			}
		}
		if (selected.getSource() == TeleportSource.WILDERNESS_OBELISK)
		{
			return label.equals("level " + selected.getId().substring("obelisk-".length()));
		}
		return "jewellery-chasm-of-tears".equals(selected.getId()) && "tears of guthix".equals(label)
			|| "tree-gnome-stronghold".equals(selected.getId()) && "tree gnome stronghold".equals(label);
	}

	private Widget genericMenu()
	{
		Widget modern = visible(InterfaceID.MenuNew.TEXT);
		return modern != null ? modern : visible(InterfaceID.Menu.LJ_LAYER1);
	}

	private Rectangle genericClip(Widget container)
	{
		int component = container.getId() == InterfaceID.MenuNew.TEXT
			? InterfaceID.MenuNew.CONTENT_SCROLL : InterfaceID.Menu.LJ_LAYER2;
		Rectangle clip = bounds(visible(component));
		return clip == null ? container.getBounds() : clip;
	}

	private String firstLabel(Widget container)
	{
		Widget[] rows = container.getDynamicChildren();
		if (rows != null)
		{
			for (Widget row : rows)
			{
				if (row != null && !row.isHidden() && row.getText() != null && !row.getText().isBlank())
				{
					return normalize(stripKey(row.getText()));
				}
			}
		}
		return "";
	}

	private void putOpen(Map<TeleportSource, Rectangle> open, TeleportSource source, int component)
	{
		Rectangle bounds = bounds(visible(component));
		if (bounds != null)
		{
			open.put(source, bounds);
		}
	}

	private Widget visible(int component)
	{
		Widget widget = client.getWidget(component);
		return widget == null || widget.isHidden() || bounds(widget) == null ? null : widget;
	}

	private static Rectangle bounds(Widget widget)
	{
		if (widget == null)
		{
			return null;
		}
		Rectangle bounds = widget.getBounds();
		return bounds == null || bounds.width <= 0 || bounds.height <= 0 ? null : bounds;
	}

	private static void addRectangle(List<Mark> marks, Rectangle rectangle, Rectangle clip, Color color, String label)
	{
		if (rectangle == null)
		{
			return;
		}
		Rectangle visible = clip == null ? new Rectangle(rectangle) : rectangle.intersection(clip);
		if (visible.width > 0 && visible.height > 0)
		{
			marks.add(new Mark(visible, clip, color, label));
		}
	}

	private static String stripKey(String text)
	{
		if (text == null)
		{
			return "";
		}
		return KEY_PREFIX.matcher(COLORED_KEY_PREFIX.matcher(text.trim()).replaceFirst("")).replaceFirst("");
	}

	private static String normalize(String text)
	{
		return Text.removeTags(text).trim().replace('\u2019', '\'').replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
	}

	private void drawLabel(Graphics2D graphics, Mark mark)
	{
		FontMetrics metrics = graphics.getFontMetrics();
		Rectangle bounds = mark.shape.getBounds();
		int width = metrics.stringWidth(mark.label) + 10;
		int height = metrics.getHeight() + 4;
		int x = Math.max(2, Math.min(bounds.x, client.getCanvasWidth() - width - 2));
		int y = Math.max(2, bounds.y - height - 4);
		graphics.setColor(BACKGROUND);
		graphics.fillRoundRect(x, y, width, height, 5, 5);
		graphics.setColor(mark.color);
		graphics.drawString(mark.label, x + 5, y + 2 + metrics.getAscent());
	}

	static final class Mark
	{
		final Shape shape;
		final Rectangle clip;
		final Color color;
		final String label;

		private Mark(Shape shape, Rectangle clip, Color color, String label)
		{
			this.shape = shape;
			this.clip = clip;
			this.color = color;
			this.label = label;
		}
	}

	/** Immutable state supplied by the plugin; null guidance hides all marks. */
	public static final class Guidance
	{
		private final boolean ownHouse;
		private final Set<TeleportSource> pendingSources;
		private final TeleportSource source;
		private final String destinationId;

		public Guidance(boolean ownHouse, Set<TeleportSource> pendingSources, TeleportSource source, String destinationId)
		{
			this.ownHouse = ownHouse;
			Set<TeleportSource> pending = EnumSet.noneOf(TeleportSource.class);
			pending.addAll(Objects.requireNonNull(pendingSources));
			this.pendingSources = Collections.unmodifiableSet(pending);
			this.source = source;
			this.destinationId = destinationId;
		}

		public boolean isOwnHouse()
		{
			return ownHouse;
		}

		public Set<TeleportSource> getPendingSources()
		{
			return pendingSources;
		}

		public TeleportSource getSource()
		{
			return source;
		}

		public String getDestinationId()
		{
			return destinationId;
		}
	}
}

package com.clueteleports;

import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Point;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

/** Observes loaded fixtures in a positively identified, player-owned house. */
public final class HouseTransportReader
{
	private static final Map<Integer, String> PORTALS = portalIds();
	private static final Pattern KEY_PREFIX = Pattern.compile("^[^:]+:\\s*");
	private static final Pattern COLORED_KEY_PREFIX = Pattern.compile(
		"^<col=[0-9a-fA-F]+>[^<]*(?::</col>|</col>\\s*:)\\s*");
	private static final Set<String> GLORY = Set.of("glory-edgeville", "glory-karamja",
		"glory-draynor-village", "glory-al-kharid");
	private static final Set<Integer> DIGSITE_OBJECTS = Set.of(ObjectID.POH_AMULET_DIGSITE,
		ObjectID.POH_AMULET_DIG_DIGSITE, ObjectID.POH_AMULET_DIG_FOSSIL, ObjectID.POH_AMULET_DIG_LITHKREN);
	private static final Set<Integer> XERIC_OBJECTS = Set.of(ObjectID.POH_AMULET_XERIC,
		ObjectID.POH_AMULET_XERIC_LOOKOUT, ObjectID.POH_AMULET_XERIC_GLADE,
		ObjectID.POH_AMULET_XERIC_INFERNO, ObjectID.POH_AMULET_XERIC_HEART, ObjectID.POH_AMULET_XERIC_HONOUR);
	private static final Map<String, String> DIGSITE_LABELS = Map.of(
		"digsite", "digsite-digsite", "fossil island", "digsite-fossil-island", "lithkren", "digsite-lithkren");
	private static final Map<String, String> XERIC_LABELS = Map.of(
		"xeric's lookout", "xeric-lookout", "xeric's glade", "xeric-glade",
		"xeric's inferno", "xeric-inferno", "xeric's heart", "xeric-heart", "xeric's honour", "xeric-honour");

	private HouseTransportReader()
	{
	}

	/** Invoke on the client thread, only after independently establishing house ownership. */
	public static Map<TeleportSource, Set<String>> read(Client client)
	{
		return readSnapshot(client).sources;
	}

	/**
	 * Unseen rooms do not prove absence. The caller reconciles portal and cape
	 * fixtures by position, replacing old entries only for covered, loaded tiles.
	 * POH scenes are not necessarily instances. WorldView base coordinates and
	 * tile indices provide stable keys without relying on instance conversion.
	 */
	public static Observation readSnapshot(Client client)
	{
		Map<TeleportSource, Set<String>> sources = new EnumMap<>(TeleportSource.class);
		Map<String, Set<String>> portals = new LinkedHashMap<>();
		Map<String, Set<String>> capes = new LinkedHashMap<>();
		Map<String, Set<TeleportSource>> installed = new LinkedHashMap<>();
		Map<String, Set<Integer>> installedIds = new LinkedHashMap<>();
		Map<TeleportSource, Set<Integer>> objectIds = new EnumMap<>(TeleportSource.class);
		Set<String> covered = new LinkedHashSet<>();
		WorldView world = client == null ? null : client.getTopLevelWorldView();
		Scene scene = world == null ? null : world.getScene();
		Tile[][][] tiles = scene == null ? null : scene.getTiles();
		if (tiles == null)
		{
			return new Observation(sources, portals, capes, covered, installed, objectIds, installedIds);
		}
		Set<TileObject> visited = Collections.newSetFromMap(new IdentityHashMap<>());
		Set<Integer> incomplete = new LinkedHashSet<>();
		Map<Integer, ObjectComposition> definitions = new HashMap<>();
		boolean digsiteSeen = false;
		boolean xericSeen = false;
		for (int plane = 0; plane < tiles.length; plane++)
		{
			Tile[][] level = tiles[plane];
			if (level == null)
			{
				continue;
			}
			for (int x = 0; x < level.length; x++)
			{
				Tile[] column = level[x];
				if (column == null)
				{
					continue;
				}
				for (int y = 0; y < column.length; y++)
				{
					Tile tile = column[y];
					if (tile == null)
					{
						continue;
					}
					String tileKey = key(world, plane, x, y);
					boolean complete = true;
					Set<TileObject> objects = Collections.newSetFromMap(new IdentityHashMap<>());
					Collections.addAll(objects, tile.getWallObject(), tile.getDecorativeObject());
					GameObject[] gameObjects = tile.getGameObjects();
					if (gameObjects != null)
					{
						Collections.addAll(objects, gameObjects);
					}
					for (TileObject object : objects)
					{
						if (object == null)
						{
							continue;
						}
						int rawId = object.getId();
						if (!definitions.containsKey(rawId) && !incomplete.contains(rawId))
						{
							ObjectComposition definition = client.getObjectDefinition(rawId);
							if (definition == null)
							{
								incomplete.add(rawId);
							}
							else
							{
								definitions.put(rawId, definition.getImpostorIds() == null
									? definition : definition.getImpostor());
							}
						}
						if (incomplete.contains(rawId))
						{
							complete = false;
							continue;
						}
						ObjectComposition live = definitions.get(rawId);
						if (live == null)
						{
							// A not-yet-resolved multiloc cannot prove removal.
							complete = false;
							continue;
						}
						if (!visited.add(object))
						{
							continue;
						}
						int id = live.getId();
						String fixtureKey = tileKey;
						if (object instanceof GameObject)
						{
							Point origin = ((GameObject) object).getSceneMinLocation();
							if (origin != null)
							{
								fixtureKey = key(world, plane, origin.getX(), origin.getY());
							}
						}
						Set<TeleportSource> facilities = EnumSet.noneOf(TeleportSource.class);
						facilities.addAll(interfaceSources(id));
						if (PORTALS.containsKey(id))
						{
							Set<String> available = portalDestinations(client, live);
							putFixture(portals, fixtureKey, available);
							add(sources, TeleportSource.PORTAL_CHAMBER, available);
							facilities.add(TeleportSource.PORTAL_CHAMBER);
						}
						Optional<Set<String>> cape = CapeReader.read(client, id);
						if (cape.isPresent())
						{
							putFixture(capes, fixtureKey, cape.get());
							add(sources, TeleportSource.CAPE_HANGER, cape.get());
							facilities.add(TeleportSource.CAPE_HANGER);
						}
						if (id == ObjectID.POH_WILDERNESS_OBELISK)
						{
							add(sources, TeleportSource.WILDERNESS_OBELISK, ObeliskReader.read(client, true));
							facilities.add(TeleportSource.WILDERNESS_OBELISK);
						}
						else if (id == ObjectID.POH_TROPHY_AMULETOFGLORY_4)
						{
							add(sources, TeleportSource.MOUNTED_GLORY, GLORY);
							facilities.add(TeleportSource.MOUNTED_GLORY);
						}
						else if (id == ObjectID.POH_TROPHY_MYTHICAL_CAPE)
						{
							add(sources, TeleportSource.MOUNTED_MYTHICAL_CAPE, Set.of("mythical-myths-guild"));
							facilities.add(TeleportSource.MOUNTED_MYTHICAL_CAPE);
						}
						else if (id == ObjectID.POH_EXIT_PORTAL || id == ObjectID.POH_EXIT_PORTAL_WILDERNESS)
						{
							houseExit(client).ifPresent(exit -> add(sources, TeleportSource.HOUSE_EXIT, Set.of(exit)));
							facilities.add(TeleportSource.HOUSE_EXIT);
						}
						if (!facilities.isEmpty())
						{
							installed.computeIfAbsent(fixtureKey, ignored -> EnumSet.noneOf(TeleportSource.class))
								.addAll(facilities);
							installedIds.computeIfAbsent(fixtureKey, ignored -> new LinkedHashSet<>()).add(id);
							for (TeleportSource facility : facilities)
							{
								objectIds.computeIfAbsent(facility, ignored -> new LinkedHashSet<>()).add(id);
							}
						}
						digsiteSeen |= DIGSITE_OBJECTS.contains(id);
						xericSeen |= XERIC_OBJECTS.contains(id);
					}
					if (complete)
					{
						covered.add(tileKey);
					}
				}
			}
		}
		// Fossil Island activation and the Ancient Tablet unlock are server-only
		// in the exposed native vars. A configured left click is not proof of an
		// unlock, and quest completion is not activation. Only complete native
		// destination menus may replace these sources; a closed menu leaves cache
		// intact. Generic menu scripts are [clientscript,menu],
		// [proc,menu_createentry], and [proc,menu_new_createentry] in runelite/cs2-scripts.
		if (digsiteSeen)
		{
			readMountedMenu(client, DIGSITE_LABELS).ifPresent(ids ->
				add(sources, TeleportSource.MOUNTED_DIGSITE_PENDANT, ids));
		}
		if (xericSeen)
		{
			readMountedMenu(client, XERIC_LABELS).ifPresent(ids ->
				add(sources, TeleportSource.MOUNTED_XERICS_TALISMAN, ids));
		}
		return new Observation(sources, portals, capes, covered, installed, objectIds, installedIds);
	}

	/**
	 * Built facilities with a destination interface, identified by the live
	 * native gameval ID. The combined spirit tree/fairy ring supplies both.
	 * Decorative skins retain the same interfaces; unbuilt hotspots do not.
	 * This shared classification also lets scene guidance identify the exact
	 * installed object without maintaining a separate overlay ID list.
	 */
	public static Set<TeleportSource> interfaceSources(int transformedObjectId)
	{
		switch (transformedObjectId)
		{
			case ObjectID.POH_FAIRY_RING:
				return Set.of(TeleportSource.FAIRY_RING);
			case ObjectID.POH_SPIRIT_TREE:
			case ObjectID.XMAS20_POH_SPIRIT_TREE:
			case ObjectID.LEAGUE_5_POH_SPIRIT_TREE:
				return Set.of(TeleportSource.SPIRIT_TREE);
			case ObjectID.POH_SPIRIT_RING:
			case ObjectID.XMAS20_POH_SPIRIT_RING:
			case ObjectID.LEAGUE_5_POH_SPIRIT_RING:
				return Set.of(TeleportSource.FAIRY_RING, TeleportSource.SPIRIT_TREE);
			case ObjectID.POH_TELENEXUS_1:
			case ObjectID.POH_TELENEXUS_2_MIDDLE:
			case ObjectID.POH_TELENEXUS_2_SIDE:
			case ObjectID.POH_TELENEXUS_2_CORNER:
			case ObjectID.POH_TELENEXUS_3:
			case ObjectID.POH_NEXUS_PORTAL_1:
			case ObjectID.POH_NEXUS_PORTAL_2:
			case ObjectID.POH_NEXUS_PORTAL_3:
			case ObjectID.POH_NEXUS_PORTAL_LEAGUE_5:
				return Set.of(TeleportSource.PORTAL_NEXUS);
			case ObjectID.POH_JEWELLERY_BOX_1:
			case ObjectID.POH_JEWELLERY_BOX_2:
			case ObjectID.POH_JEWELLERY_BOX_3:
			case ObjectID.POH_JEWELLERY_BOX_1_COLOSSEUM:
			case ObjectID.POH_JEWELLERY_BOX_2_COLOSSEUM:
			case ObjectID.POH_JEWELLERY_BOX_3_COLOSSEUM:
				return Set.of(TeleportSource.JEWELLERY_BOX);
			default:
				// Every native ID in this contiguous range is a built box with
				// its current left-click destination, across all three tiers.
				if (transformedObjectId >= ObjectID.POH_JEWELLERY_BOX_1_BASE
					&& transformedObjectId <= ObjectID.POH_JEWELLERY_BOX_3_KHARID)
				{
					return Set.of(TeleportSource.JEWELLERY_BOX);
				}
				if (DIGSITE_OBJECTS.contains(transformedObjectId))
				{
					return Set.of(TeleportSource.MOUNTED_DIGSITE_PENDANT);
				}
				if (XERIC_OBJECTS.contains(transformedObjectId))
				{
					return Set.of(TeleportSource.MOUNTED_XERICS_TALISMAN);
				}
				return Collections.emptySet();
		}
	}

	private static Optional<Set<String>> readMountedMenu(Client client, Map<String, String> labels)
	{
		Optional<Set<String>> current = readMountedMenu(client.getWidget(InterfaceID.MenuNew.TEXT), labels);
		return current.isPresent() ? current : readMountedMenu(client.getWidget(InterfaceID.Menu.LJ_LAYER1), labels);
	}

	private static Optional<Set<String>> readMountedMenu(Widget container, Map<String, String> labels)
	{
		if (container == null || container.isHidden())
		{
			return Optional.empty();
		}
		Widget[] rows = container.getDynamicChildren();
		if (rows == null || rows.length < labels.size())
		{
			return Optional.empty();
		}
		Set<String> listed = new LinkedHashSet<>();
		Set<String> available = new LinkedHashSet<>();
		for (Widget row : rows)
		{
			if (row == null)
			{
				return Optional.empty();
			}
			String raw = row.getText();
			if (raw == null || raw.trim().isEmpty())
			{
				if (row.isHidden())
				{
					continue;
				}
				return Optional.empty();
			}
			String markup = COLORED_KEY_PREFIX.matcher(raw.trim()).replaceFirst("");
			String label = KEY_PREFIX.matcher(Text.removeTags(markup).trim()).replaceFirst("")
				.toLowerCase(Locale.ROOT).replace('\u2019', '\'');
			// Mounted teleport menus use "Nowhere" for their non-teleport cancel option.
			if ("cancel".equals(label) || "close".equals(label) || "nowhere".equals(label))
			{
				continue;
			}
			String id = labels.get(label);
			if (id == null || !listed.add(id))
			{
				return Optional.empty();
			}
			markup = markup.toLowerCase(Locale.ROOT);
			if (!row.isHidden() && !markup.contains("<col=") && !markup.contains("<str"))
			{
				available.add(id);
			}
		}
		return listed.size() == labels.size()
			? Optional.of(Collections.unmodifiableSet(available)) : Optional.empty();
	}

	private static String key(WorldView world, int plane, int x, int y)
	{
		return plane + ":" + (world.getBaseX() + x) + ":" + (world.getBaseY() + y);
	}

	private static void add(Map<TeleportSource, Set<String>> sources, TeleportSource source, Set<String> ids)
	{
		sources.computeIfAbsent(source, ignored -> new LinkedHashSet<>()).addAll(ids);
	}

	private static void putFixture(Map<String, Set<String>> fixtures, String key, Set<String> ids)
	{
		fixtures.computeIfAbsent(key, ignored -> new LinkedHashSet<>()).addAll(ids);
	}

	private static Set<String> portalDestinations(Client client, ObjectComposition live)
	{
		String selected = PORTALS.get(live.getId());
		Set<String> available = new LinkedHashSet<>();
		if (selected.isEmpty())
		{
			return available;
		}
		if (portalUnlocked(client, selected))
		{
			available.add("portal-" + selected);
		}
		Set<String> alternatives;
		switch (selected)
		{
			case "varrock":
			case "grand-exchange":
				alternatives = Set.of("portal-varrock", "portal-grand-exchange");
				break;
			case "camelot":
			case "seers-village":
				alternatives = Set.of("portal-camelot", "portal-seers-village");
				break;
			case "watchtower":
			case "yanille":
				alternatives = Set.of("portal-watchtower", "portal-yanille");
				break;
			default:
				return available;
		}
		// A _1ST variant establishes the default arrival. Its live native
		// actions can additionally prove the other diary destination is usable.
		String[] actions = live.getActions();
		if (actions != null)
		{
			for (String action : actions)
			{
				TeleportCatalog.portalDestination(action)
					.filter(destination -> alternatives.contains(destination.getId()))
					.filter(destination -> portalUnlocked(client,
						destination.getId().substring("portal-".length())))
					.ifPresent(destination -> available.add(destination.getId()));
			}
		}
		return available;
	}

	private static boolean portalUnlocked(Client client, String destination)
	{
		switch (destination)
		{
			case "grand-exchange":
				return rewarded(client, VarbitID.VARROCK_MEDIUM_REWARD,
					VarbitID.VARROCK_HARD_REWARD, VarbitID.VARROCK_ELITE_REWARD);
			case "seers-village":
				return rewarded(client, VarbitID.KANDARIN_HARD_REWARD, VarbitID.KANDARIN_ELITE_REWARD);
			case "yanille":
				return rewarded(client, VarbitID.ARDOUGNE_HARD_REWARD, VarbitID.ARDOUGNE_ELITE_REWARD);
			default:
				return true;
		}
	}

	private static boolean rewarded(Client client, int... varbits)
	{
		for (int varbit : varbits)
		{
			if (client.getVarbitValue(varbit) == 1)
			{
				return true;
			}
		}
		return false;
	}

	private static Optional<String> houseExit(Client client)
	{
		// Native [clientscript,poh_board_explain_location] / [proc,poh_board_loc].
		// Values 7, 10, 11, and 12 are not fixed supported house arrivals.
		switch (client.getVarbitValue(VarbitID.POH_HOUSE_LOCATION))
		{
			case 1: return Optional.of("exit-rimmington");
			case 2: return Optional.of("exit-taverley");
			case 3: return Optional.of("exit-pollnivneach");
			case 4: return Optional.of("exit-rellekka");
			case 5: return Optional.of("exit-brimhaven");
			case 6: return Optional.of("exit-yanille");
			case 8: return Optional.of("exit-hosidius");
			case 9: return Optional.of("exit-prifddinas");
			case 13: return Optional.of("exit-aldarin");
			default: return Optional.empty();
		}
	}

