	{
		for (int id : objectIds)
		{
			ids.put(id, suffix);
		}
	}

	static final class Observation
	{
		final Map<TeleportSource, Set<String>> sources;
		final Map<String, Set<String>> portalFixtures;
		final Map<String, Set<String>> capeFixtures;
		final Set<String> coveredTiles;
		final Set<TeleportSource> installedSources;
		final Map<String, Set<TeleportSource>> installedFixtures;
		final Map<TeleportSource, Set<Integer>> fixtureObjectIds;
		final Map<String, Set<Integer>> installedFixtureIds;
		/**
		 * A nonblank loaded-scene observation, not proof of the entire layout.
		 * Never infer that an unlisted source is unbuilt. Persist positive
		 * positions and reconcile only covered tiles as rooms load or change.
		 */
		final boolean sceneReady;

		private Observation(Map<TeleportSource, Set<String>> sources,
			Map<String, Set<String>> portals, Map<String, Set<String>> capes, Set<String> covered,
			Map<String, Set<TeleportSource>> installed, Map<TeleportSource, Set<Integer>> objectIds,
			Map<String, Set<Integer>> installedIds)
		{
			this.sources = freeze(sources);
			portalFixtures = freeze(portals);
			capeFixtures = freeze(capes);
			coveredTiles = Collections.unmodifiableSet(new LinkedHashSet<>(covered));
			installedFixtures = freeze(installed);
			fixtureObjectIds = freeze(objectIds);
			installedFixtureIds = freeze(installedIds);
			Set<TeleportSource> facilities = EnumSet.noneOf(TeleportSource.class);
			installed.values().forEach(facilities::addAll);
			installedSources = Collections.unmodifiableSet(facilities);
			sceneReady = !coveredTiles.isEmpty() && !installedSources.isEmpty();
		}

		private static <K, V> Map<K, Set<V>> freeze(Map<K, Set<V>> source)
		{
			Map<K, Set<V>> frozen = new LinkedHashMap<>();
			source.forEach((key, values) -> frozen.put(key,
				Collections.unmodifiableSet(new LinkedHashSet<>(values))));
			return Collections.unmodifiableMap(frozen);
		}
	}
}

package com.clueteleports;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Optional;
import java.util.Set;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

/** Reads built box tiers and the game's individual destination locks. */
public final class JewelleryBoxReader
{
	private static final Pattern KEY_PREFIX = Pattern.compile("^[^:]+:\\s*");
	private static final Pattern COLORED_KEY_PREFIX = Pattern.compile(
		"^<col=[0-9a-fA-F]+>[^<]*(?::</col>|</col>\\s*:)\\s*");
	private static final Section[] SECTIONS = {
		new Section(InterfaceID.PohJewelleryBox.DUELING, "Ring of Dueling", "Emir's Arena", "Castle Wars", "Ferox Enclave", "Fortis Colosseum"),
		new Section(InterfaceID.PohJewelleryBox.GAMING, "Games Necklace", "Burthorpe", "Barbarian Outpost", "Corporeal Beast", "Tears of Guthix", "Wintertodt Camp"),
		new Section(InterfaceID.PohJewelleryBox.COMBAT, "Combat bracelet", "Warriors' Guild", "Champions' Guild", "Monastery", "Ranging Guild"),
		new Section(InterfaceID.PohJewelleryBox.SKILLS, "Skills necklace", "Fishing Guild", "Mining Guild", "Crafting Guild", "Cooking Guild", "Woodcutting Guild", "Farming Guild"),
		new Section(InterfaceID.PohJewelleryBox.WEALTH, "Ring of Wealth", "Miscellania", "Grand Exchange", "Falador Park", "Dondakan's Rock"),
		new Section(InterfaceID.PohJewelleryBox.GLORY, "Amulet of Glory", "Edgeville", "Karamja", "Draynor Village", "Al Kharid")
	};

	private JewelleryBoxReader()
	{
	}

	/**
	 * Invoke on the client thread. Only a completely initialized menu yields a
	 * replacement snapshot, including removals after downgrades or new locks.
	 *
	 * RuneLite cs2-scripts [clientscript,poh_jewellery_box_init] (1685) creates
	 * 27 universe placeholders, then six sections. [proc,poh_jewellery_box_prepbox]
	 * (1686) uses white/gray headers for built/unbuilt tiers, and
	 * [proc,poh_jewellery_box_addbutton] (1688) omits buttons above the built tier.
	 * Individual locks, including quest and league locks, are marked <str>.
	 * https://github.com/runelite/cs2-scripts/blob/1d418ffb6bce96c2d0712eb2652712d28e01b115/scripts/%5Bclientscript,poh_jewellery_box_init%5D.cs2
	 */
	public static Optional<Set<String>> readOpenMenu(Client client)
	{
		Widget universe = client.getWidget(InterfaceID.PohJewelleryBox.UNIVERSE);
		if (universe == null || universe.isHidden())
		{
			return Optional.empty();
		}
		Widget[] placeholders = universe.getDynamicChildren();
		if (placeholders == null || placeholders.length != 27 || Arrays.stream(placeholders).anyMatch(widget -> widget == null))
		{
			return Optional.empty();
		}
		Set<String> available = new LinkedHashSet<>();
		boolean[] built = new boolean[SECTIONS.length];
		for (int index = 0; index < SECTIONS.length; index++)
		{
			Section section = SECTIONS[index];
			Widget container = client.getWidget(section.component);
			if (container == null || container.isHidden())
			{
				return Optional.empty();
			}
			Widget[] children = container.getDynamicChildren();
			if (children == null || children.length == 0)
			{
				return Optional.empty();
			}
			boolean headerSeen = false;
			Set<String> listed = new LinkedHashSet<>();
			for (Widget child : children)
			{
				if (child == null || child.isHidden())
				{
					return Optional.empty();
				}
				String raw = child.getText();
				if (raw == null || raw.trim().isEmpty())
				{
					continue;
				}
				String plain = Text.removeTags(raw).trim();
				if (section.header.equals(plain))
				{
					if (headerSeen || (child.getTextColor() != 0xffffff && child.getTextColor() != 0x7f7f7f))
					{
						return Optional.empty();
					}
					headerSeen = true;
					built[index] = child.getTextColor() == 0xffffff;
					continue;
				}
				// Native keys put the colon inside the color tag; wrappers may
				// put it outside or replace the key with a chord. Remove only
				// key markup, preserving the destination's strike/color locks.
				String label = COLORED_KEY_PREFIX.matcher(raw.trim()).replaceFirst("");
				String name = KEY_PREFIX.matcher(Text.removeTags(label).trim()).replaceFirst("");
				if (!section.destinations.contains(name) || !listed.add(name))
				{
					return Optional.empty();
				}
				Optional<TeleportDestination> destination = TeleportCatalog.forSource(TeleportSource.JEWELLERY_BOX).stream()
					.filter(option -> option.getName().equals(name)
						|| ("Tears of Guthix".equals(name) && "jewellery-chasm-of-tears".equals(option.getId())))
					.findFirst();
				if (!destination.isPresent())
				{
					return Optional.empty();
				}
				String markup = label.toLowerCase(Locale.ROOT);
				if (!markup.contains("<str") && !markup.contains("<col="))
				{
					available.add(destination.get().getId());
				}
			}
			if (!headerSeen || (built[index] ? !listed.equals(section.destinations) : !listed.isEmpty()))
			{
				return Optional.empty();
			}
		}
		if (!built[0] || !built[1] || built[2] != built[3] || built[4] != built[5] || (built[4] && !built[2]))
		{
			return Optional.empty();
		}
		return Optional.of(Collections.unmodifiableSet(available));
	}

	private static final class Section
	{
		private final int component;
		private final String header;
		private final Set<String> destinations;

		private Section(int component, String header, String... destinations)
		{
			this.component = component;
			this.header = header;
			this.destinations = new LinkedHashSet<>(Arrays.asList(destinations));
		}
	}
}

package com.clueteleports;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.TreeSet;

/** Requires matching snapshots on two game ticks before committing menu state. */
public final class MenuObservations
{
	private final Map<TeleportSource, Set<String>> pending = new EnumMap<>(TeleportSource.class);

	public Optional<Set<String>> observe(TeleportSource source, Optional<Set<String>> reading)
	{
		if (!reading.isPresent())
		{
			pending.remove(source);
			return Optional.empty();
		}
		Set<String> snapshot = Collections.unmodifiableSet(new TreeSet<>(reading.get()));
		Set<String> previous = pending.put(source, snapshot);
		return snapshot.equals(previous) ? Optional.of(snapshot) : Optional.empty();
	}

	public void clear()
	{
		pending.clear();
	}
}

package com.clueteleports;

import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Optional;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

/** Reads installed destinations while the nexus teleport menu is open. */
public final class NexusImporter
{
	// Verified from runelite/cs2-scripts [proc,script2674],
	// [proc,telenexus_left_click], and [proc,script2664].
	private static final int NEXUS_DESTINATION_ENUM = 1377;
	private static final int DESTINATION_NAME_PARAM = 660;
	private static final int ALTERNATE_DESTINATION_PARAM = 679;
	private static final int BASE_DESTINATION_PARAM = 680;

	private NexusImporter()
	{
	}

	/**
	 * Returns empty when the teleport menu is closed or cache data is unavailable.
	 * A present empty set means the open nexus has no supported fixed destinations.
	 * The menu can belong to a guest house; callers must verify house ownership.
	 * Invoke on the client thread.
	 */
	public static Optional<Set<String>> readOpenMenu(Client client)
	{
		Widget menu = client.getWidget(InterfaceID.TelenexusTeleport.UNIVERSE);
		if (menu == null || menu.isHidden())
		{
			return Optional.empty();
		}
		EnumComposition destinations = client.getEnum(NEXUS_DESTINATION_ENUM);
		if (destinations == null)
		{
			return Optional.empty();
		}

		Set<String> imported = new LinkedHashSet<>();
		for (int slot : TeleportCatalog.nexusSlotVarbits())
		{
			int key = client.getVarbitValue(slot);
			if (key <= 0)
			{
				continue;
			}
			int structId = destinations.getIntValue(key);
			if (structId <= 0)
			{
				return Optional.empty();
			}
			StructComposition destination = client.getStructComposition(structId);
			if (destination == null)
			{
				return Optional.empty();
			}
			addDestination(client, imported, destination);
			int baseId = destination.getIntValue(BASE_DESTINATION_PARAM);
			if (baseId > 0)
			{
				StructComposition base = client.getStructComposition(baseId);
				if (base != null)
				{
					addDestination(client, imported, base);
					destination = base;
				}
				else
				{
					return Optional.empty();
				}
			}
			int alternateId = destination.getIntValue(ALTERNATE_DESTINATION_PARAM);
			if (alternateId > 0)
			{
				StructComposition alternate = client.getStructComposition(alternateId);
				if (alternate != null)
				{
					addDestination(client, imported, alternate);
				}
				else
				{
					return Optional.empty();
				}
			}
		}
		return Optional.of(Collections.unmodifiableSet(imported));
	}

	private static void addDestination(Client client, Set<String> imported, StructComposition struct)
	{
		TeleportCatalog.nexusDestination(struct.getStringValue(DESTINATION_NAME_PARAM))
			.filter(destination -> alternateUnlocked(client, destination.getId()))
			.ifPresent(destination -> imported.add(destination.getId()));
	}

	private static boolean alternateUnlocked(Client client, String destinationId)
	{
		switch (destinationId)
		{
			case "nexus-grand-exchange":
				return rewarded(client, VarbitID.VARROCK_MEDIUM_REWARD,
					VarbitID.VARROCK_HARD_REWARD, VarbitID.VARROCK_ELITE_REWARD);
			case "nexus-seers-village":
				return rewarded(client, VarbitID.KANDARIN_HARD_REWARD, VarbitID.KANDARIN_ELITE_REWARD);
			case "nexus-yanille":
				return rewarded(client, VarbitID.ARDOUGNE_HARD_REWARD, VarbitID.ARDOUGNE_ELITE_REWARD);
			default:
				return true;
		}
	}

	private static boolean rewarded(Client client, int... varbits)
	{
		for (int varbit : varbits)
		{
			if (client.getVarbitValue(varbit) == 1)
			{
				return true;
			}
		}
		return false;
	}
}

package com.clueteleports;

import java.awt.Rectangle;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

/**
 * One-time UI scrolling to an existing, available portal-nexus destination.
 *
 * Native telenexus_teleport_init (2672) calls script2674, which lays TEXT1 and
 * EXTRAS rows into one cumulative SCROLLING1 scroll space. Its scrollbar is
 * rebuilt from SCROLLING1.getScrollY(); unlike fairy rings, no separate saved
 * varc scroll position is used. scrollbar_vertical_setdragger (740) supplies
 * the existing native thumb/cap positions mirrored below.
 * See runelite/cs2-scripts at 1d418ffb6bce96c2d0712eb2652712d28e01b115,
 * scripts/[proc,script2674].cs2 and
 * scripts/[proc,scrollbar_vertical_setdragger].cs2.
 *
 * This class changes only local widget layout, without executing scripts,
 * changing game variables, or invoking any destination's action.
 */
public final class NexusMenuScroll
{
	private static final int[] ROW_CONTAINERS = {
		InterfaceID.TelenexusTeleport.TEXT1, InterfaceID.TelenexusTeleport.EXTRAS
	};
	private Widget openScroll;
	private String destination;
	private boolean positioned;

	/** Pass null when there is no applicable own-house nexus recommendation. */
	public void update(Client client, String destinationId)
	{
		if (!client.isClientThread())
		{
			throw new IllegalStateException("Nexus menu scrolling requires the client thread");
		}
		TeleportDestination selected = destinationId == null ? null
			: TeleportCatalog.byId(destinationId)
				.filter(value -> value.getSource() == TeleportSource.PORTAL_NEXUS).orElse(null);
		if (selected == null)
		{
			reset();
			return;
		}
		Widget scroll = client.getWidget(InterfaceID.TelenexusTeleport.SCROLLING1);
		Rectangle viewport = bounds(scroll);
		if (viewport == null || bounds(client.getWidget(InterfaceID.TelenexusTeleport.UNIVERSE)) == null)
		{
			reset();
			return;
		}
		if (scroll != openScroll || !selected.getId().equals(destination))
		{
			openScroll = scroll;
			destination = selected.getId();
			positioned = false;
		}
		if (positioned)
		{
			return;
		}
		Widget entry = findEntry(client, selected);
		Rectangle row = bounds(entry);
		if (row == null || row.x >= viewport.x + viewport.width || row.x + row.width <= viewport.x)
		{
			return;
		}
		int current = scroll.getScrollY();
		if (current < 0)
		{
			return;
		}
		if (row.y >= viewport.y && row.y + row.height <= viewport.y + viewport.height)
		{
			positioned = true;
			return;
		}
		int height = scroll.getScrollHeight();
		int top = row.y - viewport.y + current;
		if (top < 0 || height <= 0 || top + row.height > height)
		{
			// A missing row or partially hydrated extent may become ready later.
			return;
		}
		int desired = Math.max(0, Math.min(Math.max(0, height - viewport.height),
			top - Math.max(0, (viewport.height - row.height) / 2)));
		if (desired != current)
		{
			scroll.setScrollY(desired);
			scroll.revalidateScroll();
			syncNativeThumb(client.getWidget(InterfaceID.TelenexusTeleport.SCROLLBAR1), scroll);
		}
		positioned = true;
	}

	public void reset()
	{
		openScroll = null;
		destination = null;
		positioned = false;
	}

	private static Widget findEntry(Client client, TeleportDestination selected)
	{
		for (int component : ROW_CONTAINERS)
		{
			Widget container = client.getWidget(component);
			if (container == null || container.isHidden())
			{
				continue;
			}
			Widget[] rows = container.getDynamicChildren();
			if (rows != null)
			{
				for (Widget row : rows)
				{
					if (row != null && bounds(row) != null
						&& HouseLearningOverlay.matchesAvailableRow(selected, row))
					{
						return row;
					}
				}
			}
		}
		return null;
	}

	private static void syncNativeThumb(Widget bar, Widget scroll)
	{
		Rectangle track = bounds(bar);
		Rectangle viewport = bounds(scroll);
		if (track == null || viewport == null || track.height <= 32)
		{
			return;
		}
		Widget[] children = bar.getDynamicChildren();
		if (children == null || children.length != 6)
		{
			return;
		}
		// The native six-graphic bar has track, dragger, two caps, and two arrows.
		// Do not reposition a partially built or replaced/custom scrollbar.
		for (int index = 0; index < children.length; index++)
		{
			Widget child = children[index];
			if (child == null || child.getType() != WidgetType.GRAPHIC || bounds(child) == null
				|| child.getParentId() != InterfaceID.TelenexusTeleport.SCROLLBAR1 || child.getIndex() != index)
			{
				return;
			}
		}
		int thumbHeight = children[1].getBounds().height;
		int travel = track.height - 32 - thumbHeight;
		if (thumbHeight < 10 || travel < 0)
		{
			return;
		}
		int maximum = Math.max(1, scroll.getScrollHeight() - viewport.height);
		int actual = Math.max(0, Math.min(scroll.getScrollY(), maximum));
		int top = 16 + (int) ((long) travel * actual / maximum);
		children[1].setOriginalY(top);
		children[2].setOriginalY(top);
		children[3].setOriginalY(top + thumbHeight - 5);
		children[1].revalidate();
		children[2].revalidate();
		children[3].revalidate();
	}

	private static Rectangle bounds(Widget widget)
	{
		if (widget == null || widget.isHidden())
		{
			return null;
		}
		Rectangle bounds = widget.getBounds();
		return bounds != null && bounds.width > 0 && bounds.height > 0 ? bounds : null;
	}
}

package com.clueteleports;

import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;

/**
 * Reads deterministic access through an observed POH Wilderness obelisk.
 *
 * Call only after confirming ownership and obtaining a complete house fixture
 * observation. The presence argument must describe ObjectID.POH_WILDERNESS_OBELISK
 * (31554), not a Wilderness obelisk outside the house.
 *
 * Wilderness Obelisk destination selection requires collecting the Hard
 * Wilderness Diary reward. Without it, activation chooses randomly and none of
 * the six arrivals can be recommended as a guaranteed destination.
 *
 * Reward IDs are RuneLite gamevals; destination coordinates are documented by
 * RuneLite TeleportLocationData at 9fad2c588ca957ae47d883b09544725a796ed9fe.
 * Behaviour: https://oldschool.runescape.wiki/w/Wilderness_Obelisk .
 */
public final class ObeliskReader
{
	private static final Set<String> DESTINATIONS;

	static
	{
		Set<String> ids = new LinkedHashSet<>();
		for (int level : new int[]{13, 19, 27, 35, 44, 50})
		{
			ids.add("obelisk-" + level);
		}
		DESTINATIONS = Collections.unmodifiableSet(ids);
	}

	private ObeliskReader()
	{
	}

	/** A complete result; an absent fixture or random-only access is known empty. */
	public static Set<String> read(Client client, boolean obeliskPresent)
	{
		if (!obeliskPresent)
		{
			return Collections.emptySet();
		}
		return client.getVarbitValue(VarbitID.WILDERNESS_HARD_REWARD) == 1
			|| client.getVarbitValue(VarbitID.WILDERNESS_ELITE_REWARD) == 1
			? DESTINATIONS : Collections.emptySet();
	}
}

package com.clueteleports;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

/** Reads a complete spirit tree travel menu, on the client thread. */
public final class SpiritTreeReader
{
	private static final Pattern KEY_PREFIX = Pattern.compile("^[^:]+:\\s*");
	private static final Pattern COLORED_KEY_PREFIX = Pattern.compile(
		"^<col=[0-9a-fA-F]+>[^<]*(?::</col>|</col>\\s*:)\\s*");
	private static final Set<String> BASELINE = Set.of("tree-tree-gnome-village", "tree-gnome-stronghold",
		"tree-battlefield-of-khazard", "tree-grand-exchange");

	private SpiritTreeReader()
	{
	}

	/**
	 * Empty Optional means no complete observation; a present set replaces the
	 * cached network, so trees omitted or disabled by the game are removed.
	 *
	 * RuneLite cs2-scripts [clientscript,menu], [proc,menu_createentry], and
	 * [proc,menu_new_createentry] populate these dynamic text containers.
	 * Gray availability markup is also documented by Shortest Path's own parser:
	 * https://github.com/Skretzo/shortest-path/blob/master/src/main/java/shortestpath/spirittree/SpiritTreeService.java
	 * Exact option labels, including the four baseline trees, match:
	 * https://github.com/trs/runelite-teleport-maps/blob/e006270494500ab8e4826903b377bb945ca9fc96/src/main/resources/SpiritTreeMap/TreeDefinitions.json
	 * Unlike that service's partial-patch merge, this reader requires the full
	 * baseline and every visible row to parse before replacing a cached set.
	 */
	public static Optional<Set<String>> readOpenMenu(Client client)
	{
		Optional<Set<String>> current = read(client.getWidget(InterfaceID.MenuNew.TEXT));
		return current.isPresent() ? current : read(client.getWidget(InterfaceID.Menu.LJ_LAYER1));
	}

	private static Optional<Set<String>> read(Widget container)
	{
		if (container == null || container.isHidden())
		{
			return Optional.empty();
		}
		Widget[] rows = container.getDynamicChildren();
		if (rows == null || rows.length < BASELINE.size())
		{
			return Optional.empty();
		}
		Map<String, String> names = new LinkedHashMap<>();
		for (TeleportDestination destination : TeleportCatalog.forSource(TeleportSource.SPIRIT_TREE))
		{
			names.put(destination.getName().toLowerCase(Locale.ROOT), destination.getId());
		}
		names.put("tree gnome stronghold", "tree-gnome-stronghold");
		Set<String> listed = new LinkedHashSet<>();
		Set<String> available = new LinkedHashSet<>();
		boolean firstLabelSeen = false;
		for (Widget row : rows)
		{
			if (row == null)
			{
				return Optional.empty();
			}
			String raw = row.getText();
			if (raw == null || raw.trim().isEmpty())
			{
				// MENU_NEW creates hidden empty framework entries. A visible
				// blank row still indicates an incomplete menu.
				if (row.isHidden())
				{
					continue;
				}
				return Optional.empty();
			}
			// Better Teleport Menu can replace one-character keys with
			// chords, remove them, or keep the colon inside the color tag.
			String label = COLORED_KEY_PREFIX.matcher(raw.trim()).replaceFirst("");
			String name = KEY_PREFIX.matcher(Text.removeTags(label).trim()).replaceFirst("")
				.toLowerCase(Locale.ROOT);
			if (!firstLabelSeen && !"tree gnome village".equals(name))
			{
				return Optional.empty();
			}
			firstLabelSeen = true;
			// The game can append the house's location in parentheses.
			if ("your house".equals(name) || (name.startsWith("your house (") && name.endsWith(")"))
				|| "cancel".equals(name) || "close".equals(name))
			{
				continue;
			}
			String id = names.get(name);
			if (id == null || !listed.add(id))
			{
				return Optional.empty();
			}
			// Disabled options carry gray markup. Treat other explicit status
			// colors or strike markup conservatively as unavailable, too.
			String markup = label.toLowerCase(Locale.ROOT);
			if (!row.isHidden() && !markup.contains("<col=") && !markup.contains("<str"))
			{
				available.add(id);
			}
		}
		return listed.containsAll(BASELINE)
			? Optional.of(Collections.unmodifiableSet(available)) : Optional.empty();
	}
}

