	private TeleportCatalog()
	{
	}

	public static List<TeleportDestination> all()
	{
		return DESTINATIONS;
	}

	public static List<TeleportDestination> forSource(TeleportSource source)
	{
		List<TeleportDestination> result = new ArrayList<>();
		for (TeleportDestination destination : DESTINATIONS)
		{
			if (destination.getSource() == source)
			{
				result.add(destination);
			}
		}
		return Collections.unmodifiableList(result);
	}

	public static Optional<TeleportDestination> byId(String id)
	{
		return Optional.ofNullable(BY_ID.get(id));
	}

	public static Optional<TeleportDestination> nexusDestination(String name)
	{
		return Optional.ofNullable(NEXUS_NAMES.get(normalizeNexusName(name)));
	}

	public static Optional<TeleportDestination> portalDestination(String name)
	{
		String portalName = name == null ? "" : name.replaceAll("<[^>]*>", "").replaceAll("(?i)\\s+portal\\s*$", "");
		if ("yanillewatchtower".equals(normalizeNexusName(portalName)))
		{
			return byId("portal-watchtower");
		}
		return nexusDestination(portalName)
			.flatMap(destination -> byId("portal-" + destination.getId().substring("nexus-".length())));
	}

	public static int[] nexusSlotVarbits()
	{
		return NEXUS_SLOT_VARBITS.clone();
	}

	/** Minimum box tier: 1 basic, 2 fancy, 3 ornate, or 0 for another source. */
	public static int jewelleryTier(TeleportDestination destination)
	{
		return JEWELLERY_TIERS.getOrDefault(destination.getId(), 0);
	}

	private static void add(List<TeleportDestination> destinations, String id,
		TeleportSource source, String name, int x, int y, int plane)
	{
		destinations.add(new TeleportDestination(id, source, name, new WorldPoint(x, y, plane)));
	}

	private static void alias(Map<String, TeleportDestination> names, String id, String... aliases)
	{
		TeleportDestination destination = BY_ID.get(id);
		for (String alias : aliases)
		{
			names.put(normalizeNexusName(alias), destination);
		}
	}

	private static String normalizeNexusName(String name)
	{
		if (name == null)
		{
			return "";
		}
		return name.replaceAll("<[^>]*>", "")
			.replaceAll("^[A-Za-z0-9]\\s*:\\s*", "")
			.replaceAll("\\s*\\([^)]*\\)\\s*$", "")
			.toLowerCase(Locale.ROOT)
			.replaceAll("[^a-z0-9]", "");
	}
}

package com.clueteleports;

import java.util.Objects;
import net.runelite.api.coords.WorldPoint;

public final class TeleportDestination
{
	private final String id;
	private final TeleportSource source;
	private final String name;
	private final WorldPoint location;

	public TeleportDestination(String id, TeleportSource source, String name, WorldPoint location)
	{
		this.id = Objects.requireNonNull(id, "id");
		this.source = Objects.requireNonNull(source, "source");
		this.name = Objects.requireNonNull(name, "name");
		this.location = Objects.requireNonNull(location, "location");
	}

	public String getId()
	{
		return id;
	}

	public TeleportSource getSource()
	{
		return source;
	}

	public String getName()
	{
		return name;
	}

	public WorldPoint getLocation()
	{
		return location;
	}
}

package com.clueteleports;

import com.clueteleports.routing.WalkingRouteResult;
import java.util.Collection;
import java.util.List;
import java.util.Objects;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;

/** Client-thread requests; production implementations compute on a worker. */
interface TeleportRouting extends AutoCloseable
{
	Plan update(Client client, String profile, List<WorldPoint> targets,
		Collection<TeleportDestination> arrivals, int interactionRadius);
	default void invalidate() { }
	@Override default void close() { }

	final class Plan
	{
		enum Status { PREPARING, SEARCHING, FOUND, NO_ROUTE, LIMIT, UNAVAILABLE }
		final Status status;
		final TeleportDestination destination;
		final WorldPoint target;
		final long costHalfTicks;
		final int walkingTiles;
		final int transitions;

		private Plan(Status status, TeleportDestination destination, WorldPoint target,
			long costHalfTicks, int walkingTiles, int transitions)
		{
			this.status = status;
			this.destination = destination;
			this.target = target;
			this.costHalfTicks = costHalfTicks;
			this.walkingTiles = walkingTiles;
			this.transitions = transitions;
		}

		static Plan status(Status status) { return new Plan(status, null, null, 0, 0, 0); }

		static Plan found(TeleportDestination destination, WorldPoint target, long cost, int tiles, int transitions)
		{
			return new Plan(Status.FOUND, Objects.requireNonNull(destination), Objects.requireNonNull(target), cost, tiles, transitions);
		}

		static Plan from(WalkingRouteResult result)
		{
			switch (result.getStatus())
			{
				case FOUND: return found(result.getDestination(), result.getTarget(), result.getCostHalfTicks(), result.getWalkingTiles(), result.getTransitionCount());
				case LIMIT: return status(Status.LIMIT);
				case CANCELLED: return status(Status.SEARCHING);
				default: return status(Status.NO_ROUTE);
			}
		}
	}
}

