package com.clueteleports.routing;

import java.util.Collection;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;

/** Immutable account evidence captured on the client thread for worker searches. */
public final class AccountRouteState
{
	private final Map<Skill, Integer> realSkills;
	private final Map<Skill, Integer> boostedSkills;
	private final Map<Quest, QuestState> quests;
	private final Map<Integer, Integer> varbits;
	private final Map<Integer, Integer> varps;
	private final Map<Integer, Integer> items;
	private final Map<Integer, Integer> equipped;
	private final boolean itemsKnown;

	AccountRouteState(Map<Skill, Integer> realSkills, Map<Skill, Integer> boostedSkills,
		Map<Quest, QuestState> quests, Map<Integer, Integer> varbits, Map<Integer, Integer> varps,
		Map<Integer, Integer> items, Map<Integer, Integer> equipped, boolean itemsKnown)
	{
		this.realSkills = Map.copyOf(realSkills);
		this.boostedSkills = Map.copyOf(boostedSkills);
		this.quests = Map.copyOf(quests);
		this.varbits = Map.copyOf(varbits);
		this.varps = Map.copyOf(varps);
		this.items = Map.copyOf(items);
		this.equipped = Map.copyOf(equipped);
		this.itemsKnown = itemsKnown;
	}

	/**
	 * Captures only the quest/variable IDs requested by the physical graph,
	 * plus both skill arrays and carried inventory/equipment. Bank items are
	 * intentionally excluded. No Client reference escapes into the snapshot.
	 */
	public static AccountRouteState capture(Client client, Collection<RouteRequirements> requirements)
	{
		if (client == null || !client.isClientThread())
		{
			throw new IllegalStateException("Route state must be captured on the client thread");
		}
		Map<Skill, Integer> real = new EnumMap<>(Skill.class);
		Map<Skill, Integer> boosted = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values())
		{
			int level = client.getRealSkillLevel(skill);
			if (level >= 0) real.put(skill, level);
			level = client.getBoostedSkillLevel(skill);
			if (level >= 0) boosted.put(skill, level);
		}
		Set<Quest> requestedQuests = EnumSet.noneOf(Quest.class);
		Set<Integer> requestedBits = new LinkedHashSet<>();
		Set<Integer> requestedPlayers = new LinkedHashSet<>();
		for (RouteRequirements requirement : requirements)
		{
			requestedQuests.addAll(requirement.getRequiredQuests());
			requestedBits.addAll(requirement.getRequiredVarbits());
			requestedPlayers.addAll(requirement.getRequiredVarps());
		}
		Map<Quest, QuestState> quests = new EnumMap<>(Quest.class);
		for (Quest quest : requestedQuests)
		{
			try
			{
				QuestState state = quest.getState(client);
				if (state != null) quests.put(quest, state);
			}
			catch (NullPointerException exception)
			{
				// An unavailable native quest state remains unknown, failing closed.
			}
		}
		Map<Integer, Integer> bits = new HashMap<>();
		for (int id : requestedBits)
		{
			if (client.getVarbit(id) != null) bits.put(id, client.getVarbitValue(id));
		}
		Map<Integer, Integer> players = new HashMap<>();
		int[] nativePlayers = client.getVarps();
		for (int id : requestedPlayers)
		{
			if (nativePlayers != null && id >= 0 && id < nativePlayers.length) players.put(id, nativePlayers[id]);
		}
		Map<Integer, Integer> carried = new HashMap<>();
		Map<Integer, Integer> worn = new HashMap<>();
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		boolean known = addItems(inventory, carried) & addItems(equipment, worn);
		worn.forEach((id, quantity) -> carried.merge(id, quantity, AccountRouteState::sum));
		return new AccountRouteState(real, boosted, quests, bits, players, carried, worn, known);
	}

	int realLevel(Skill skill)
	{
		return realSkills.getOrDefault(skill, -1);
	}

	int boostedLevel(Skill skill)
	{
		return boostedSkills.getOrDefault(skill, -1);
	}

	QuestState questState(Quest quest)
	{
		return quests.get(quest);
	}

	Integer varbit(int id)
	{
		return varbits.get(id);
	}

	Integer varp(int id)
	{
		return varps.get(id);
	}

	boolean hasItems(Set<Integer> ids, int quantity, boolean equippedOnly)
	{
		if (!itemsKnown) return false;
		Map<Integer, Integer> owned = equippedOnly ? equipped : items;
		long count = 0;
		for (int id : ids) count += owned.getOrDefault(id, 0);
		return quantity == 0 ? count == 0 : count >= quantity;
	}

	private static boolean addItems(ItemContainer container, Map<Integer, Integer> items)
	{
		if (container == null || container.getItems() == null) return false;
		for (Item item : container.getItems())
		{
			if (item != null && item.getId() > 0 && item.getQuantity() > 0)
			{
				items.merge(item.getId(), item.getQuantity(), AccountRouteState::sum);
			}
		}
		return true;
	}

	private static int sum(int first, int second)
	{
		return (int) Math.min(Integer.MAX_VALUE, (long) first + second);
	}

	@Override
	public boolean equals(Object object)
	{
		if (this == object) return true;
		if (!(object instanceof AccountRouteState)) return false;
		AccountRouteState other = (AccountRouteState) object;
		return itemsKnown == other.itemsKnown && realSkills.equals(other.realSkills)
			&& boostedSkills.equals(other.boostedSkills) && quests.equals(other.quests)
			&& varbits.equals(other.varbits) && varps.equals(other.varps)
			&& items.equals(other.items) && equipped.equals(other.equipped);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(realSkills, boostedSkills, quests, varbits, varps, items, equipped, itemsKnown);
	}
}

package com.clueteleports.routing;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;

/** Exact dig/coordinate tiles remain exact; known interactions may use a nearby face. */
public final class RouteGoals
{
	private RouteGoals() { }

	static int pack(WorldPoint point) { return point.getPlane() << 28 | point.getX() << 14 | point.getY(); }

	public static List<WorldPoint> qualify(WalkingCollisionMap collision, List<WorldPoint> targets, int interactionRadius)
	{
		Set<WorldPoint> goals = new LinkedHashSet<>();
		for (WorldPoint target : targets)
		{
			if (target == null || target.getPlane() < 0 || target.getPlane() > 3
				|| target.getX() < 0 || target.getX() > 16383 || target.getY() < 0 || target.getY() > 16383) continue;
			boolean walkable = collision.isWalkable(pack(target));
			if (walkable) goals.add(target);
			if (interactionRadius < 1) continue;
			// For a walkable NPC tile, require the real edge to that tile. This
			// prevents ending outside a room through its wall. For a known solid
			// interaction object, inspect its nearest mapped cardinal faces.
			for (int radius = 1; radius <= Math.min(2, interactionRadius); radius++)
			{
				boolean foundFace = false;
				for (int[] direction : new int[][]{{0, 1}, {1, 0}, {0, -1}, {-1, 0}})
				{
					int x = target.getX() + direction[0] * radius;
					int y = target.getY() + direction[1] * radius;
					if (x < 0 || x > 16383 || y < 0 || y > 16383) continue;
					WorldPoint face = new WorldPoint(x, y, target.getPlane());
					if (collision.canInteractFrom(pack(face), pack(target)))
					{
						goals.add(face);
						foundFace = true;
					}
				}
				if (walkable || foundFace) break;
			}
		}
		return Collections.unmodifiableList(new ArrayList<>(goals));
	}
}

package com.clueteleports.routing;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarbitID;

/** Fail-closed account requirements for physical actions in the pinned route data. */
public final class RouteRequirements
{
	private static final Pattern SKILL = Pattern.compile("([0-9]+)\\s+(.+)");
	private static final Pattern VARIABLE = Pattern.compile("([0-9]+)\\s*([=><&])\\s*(-?[0-9]+)");
	private static final Pattern ITEM = Pattern.compile("([A-Z_0-9]+)=([0-9]+)");
	private static final Map<String, Set<Integer>> ITEM_ALIASES = loadAliases();
	private static final RouteRequirements NONE = new RouteRequirements(Collections.emptyMap(),
		Collections.emptySet(), Collections.emptyList(), Collections.emptyList(), Collections.emptyList());
	private final Map<Skill, Integer> skills;
	private final Set<Quest> quests;
	private final List<Variable> varbits;
	private final List<Variable> varps;
	private final List<List<ItemChoice>> items;
	private final Set<Integer> requiredVarbits;
	private final Set<Integer> requiredVarps;

	private RouteRequirements(Map<Skill, Integer> skills, Set<Quest> quests,
		List<Variable> varbits, List<Variable> varps, List<List<ItemChoice>> items)
	{
		this.skills = Map.copyOf(skills);
		this.quests = Set.copyOf(quests);
		this.varbits = List.copyOf(varbits);
		this.varps = List.copyOf(varps);
		this.items = List.copyOf(items);
		Set<Integer> bits = new LinkedHashSet<>();
		varbits.forEach(variable -> bits.add(variable.id));
		for (List<ItemChoice> alternatives : items)
		{
			if (alternatives.stream().anyMatch(item -> "UNLOCK_KARAMJA_ELITE".equals(item.unlock)))
			{
				bits.add(VarbitID.KARAMJA_ELITE_REWARD);
			}
		}
		requiredVarbits = Collections.unmodifiableSet(bits);
		Set<Integer> players = new LinkedHashSet<>();
		varps.forEach(variable -> players.add(variable.id));
		requiredVarps = Collections.unmodifiableSet(players);
	}

	public static RouteRequirements none()
	{
		return NONE;
	}

	/**
	 * Grammar follows the pinned Shortest Path physical TSV columns. Unknown
	 * quests, aliases, operators, and malformed terms reject the complete row;
	 * they never silently remove its account requirement.
	 */
	public static Optional<RouteRequirements> parse(String skillText, String itemText,
		String questText, String varbitText, String varpText)
	{
		try
		{
			Map<Skill, Integer> skills = new EnumMap<>(Skill.class);
			for (String term : terms(skillText))
			{
				Matcher matcher = SKILL.matcher(term);
				if (!matcher.matches()) return Optional.empty();
				Skill matched = null;
				for (Skill skill : Skill.values())
				{
					if (skill.getName().equalsIgnoreCase(matcher.group(2))) matched = skill;
				}
				if (matched == null) return Optional.empty();
				skills.merge(matched, Integer.parseInt(matcher.group(1)), Math::max);
			}
			Set<Quest> quests = EnumSet.noneOf(Quest.class);
			for (String term : terms(questText))
			{
				Quest matched = null;
				for (Quest quest : Quest.values())
				{
					if (quest.getName().equalsIgnoreCase(term)) matched = quest;
				}
				if (matched == null) return Optional.empty();
				quests.add(matched);
			}
			List<Variable> bits = parseVariables(varbitText);
			List<Variable> players = parseVariables(varpText);
			List<List<ItemChoice>> items = parseItems(itemText);
			if (skills.isEmpty() && quests.isEmpty() && bits.isEmpty() && players.isEmpty() && items.isEmpty())
			{
				return Optional.of(NONE);
			}
			return Optional.of(new RouteRequirements(skills, quests, bits, players, items));
		}
		catch (IllegalArgumentException exception)
		{
			return Optional.empty();
		}
	}

	public Set<Quest> getRequiredQuests()
	{
		return quests;
	}

	public Set<Integer> getRequiredVarbits()
	{
		return requiredVarbits;
	}

	public Set<Integer> getRequiredVarps()
	{
		return requiredVarps;
	}

	public boolean isSatisfied(AccountRouteState state)
	{
		if (state == null) return false;
		for (Map.Entry<Skill, Integer> skill : skills.entrySet())
		{
			// The Prayer Guild checks the level, not remaining prayer points.
			// Other physical skill gates use the currently effective level.
			int level = skill.getKey() == Skill.PRAYER
				? state.realLevel(skill.getKey()) : state.boostedLevel(skill.getKey());
			if (level < skill.getValue()) return false;
		}
		for (Quest quest : quests)
		{
			if (state.questState(quest) != QuestState.FINISHED) return false;
		}
		for (Variable variable : varbits)
		{
			if (!variable.satisfied(state.varbit(variable.id))) return false;
		}
		for (Variable variable : varps)
		{
			if (!variable.satisfied(state.varp(variable.id))) return false;
		}
		for (List<ItemChoice> alternatives : items)
		{
			boolean matched = false;
			for (ItemChoice alternative : alternatives)
			{
				if (alternative.satisfied(state))
				{
					matched = true;
					break;
				}
			}
			if (!matched) return false;
		}
		return true;
	}

	private static String[] terms(String text)
	{
		if (text == null || text.trim().isEmpty()) return new String[0];
		String[] terms = text.trim().split(";");
		if (terms.length == 0) throw new IllegalArgumentException("Empty requirement");
		for (int i = 0; i < terms.length; i++)
		{
			terms[i] = terms[i].trim();
			if (terms[i].isEmpty()) throw new IllegalArgumentException("Empty requirement term");
		}
		return terms;
	}

	private static List<Variable> parseVariables(String text)
	{
		List<Variable> variables = new ArrayList<>();
		for (String term : terms(text))
		{
			Matcher matcher = VARIABLE.matcher(term);
			if (!matcher.matches()) throw new IllegalArgumentException("Unknown variable requirement");
			variables.add(new Variable(Integer.parseInt(matcher.group(1)), matcher.group(2).charAt(0),
				Integer.parseInt(matcher.group(3))));
		}
		return variables;
	}

	private static List<List<ItemChoice>> parseItems(String text)
	{
		if (text == null || text.trim().isEmpty()) return Collections.emptyList();
		String normalized = text.replaceAll("\\s+", "").toUpperCase(Locale.ROOT)
			.replace("&&", "&").replace("||", "|");
		List<List<ItemChoice>> groups = new ArrayList<>();
		for (String conjunction : normalized.split("&", -1))
		{
			List<ItemChoice> choices = new ArrayList<>();
			for (String choice : conjunction.split("\\|", -1))
			{
				Matcher matcher = ITEM.matcher(choice);
				if (!matcher.matches()) throw new IllegalArgumentException("Unknown item requirement");
				String name = matcher.group(1);
				int quantity = Integer.parseInt(matcher.group(2));
				if (name.startsWith("UNLOCK_"))
				{
					if (quantity < 1 || !("UNLOCK_KARAMJA_ELITE".equals(name) || "UNLOCK_MOR_UL_REK".equals(name)))
					{
						throw new IllegalArgumentException("Unknown unlock");
					}
					choices.add(new ItemChoice(Collections.emptySet(), quantity, name, false));
					continue;
				}
				Set<Integer> ids = ITEM_ALIASES.get(name);
				if (ids == null)
				{
					int id = Integer.parseInt(name);
					if (id <= 0) throw new IllegalArgumentException("Invalid item ID");
					ids = Set.of(id);
				}
				// Having a high-tier crossbow in a backpack does not establish
				// that this account can equip it. Require ready grapple gear.
				choices.add(new ItemChoice(ids, quantity, null, quantity > 0 && "CROSSBOW".equals(name)));
			}
			groups.add(List.copyOf(choices));
		}
		return groups;
	}

	private static Map<String, Set<Integer>> loadAliases()
	{
		Map<String, Set<Integer>> aliases = new HashMap<>();
		try (InputStream stream = RouteRequirements.class.getResourceAsStream("/routes/item-variations.tsv"))
		{
			if (stream == null) return Collections.emptyMap();
			try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8)))
			{
				String line;
				while ((line = reader.readLine()) != null)
				{
					if (line.isBlank() || line.startsWith("#")) continue;
					String[] columns = line.split("\\t", -1);
					if (columns.length < 2) continue;
					Set<Integer> ids = new LinkedHashSet<>();
					for (String id : columns[1].split(",")) ids.add(Integer.parseInt(id));
					aliases.put(columns[0], Set.copyOf(ids));
				}
			}
		}
		catch (IOException | NumberFormatException exception)
		{
			// Missing or malformed aliases never turn into no-requirement rows.
			return Collections.emptyMap();
		}
		return Collections.unmodifiableMap(aliases);
	}

	private static final class ItemChoice
	{
		private final Set<Integer> ids;
		private final int quantity;
		private final String unlock;
		private final boolean equippedOnly;

		private ItemChoice(Set<Integer> ids, int quantity, String unlock, boolean equippedOnly)
		{
			this.ids = ids;
			this.quantity = quantity;
			this.unlock = unlock;
			this.equippedOnly = equippedOnly;
		}

		private boolean satisfied(AccountRouteState state)
		{
			if (unlock != null)
			{
				return "UNLOCK_KARAMJA_ELITE".equals(unlock)
					&& Integer.valueOf(1).equals(state.varbit(VarbitID.KARAMJA_ELITE_REWARD));
			}
			return state.hasItems(ids, quantity, equippedOnly);
		}
	}

	private static final class Variable
	{
		private final int id;
		private final char operator;
		private final int value;

		private Variable(int id, char operator, int value)
		{
			this.id = id;
			this.operator = operator;
			this.value = value;
		}

		private boolean satisfied(Integer current)
		{
			if (current == null) return false;
			switch (operator)
			{
				case '=': return current == value;
				case '>': return current > value;
				case '<': return current < value;
				case '&': return (current & value) != 0;
				default: return false;
			}
		}
	}
}

package com.clueteleports.routing;

import java.util.Objects;

/** A directed physical passage with immutable requirements and tick duration. */
public final class RouteTransport
{
	private final int from;
	private final int to;
	private final int durationTicks;
	private final String action;
	private final RouteRequirements requirements;

	public RouteTransport(int from, int to, int durationTicks, String action, RouteRequirements requirements)
	{
		if (durationTicks < 1)
		{
			throw new IllegalArgumentException("A passage must cost at least one tick");
		}
		this.from = from;
		this.to = to;
		this.durationTicks = durationTicks;
		this.action = Objects.requireNonNull(action);
		this.requirements = Objects.requireNonNull(requirements);
	}

	public int getFrom() { return from; }
	public int getTo() { return to; }
	public int getDurationTicks() { return durationTicks; }
	public String getAction() { return action; }
	public RouteRequirements getRequirements() { return requirements; }
}

package com.clueteleports.routing;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

/** Offline, version-pinned collision and physical-passage data; no global teleports. */
public final class RoutingData
{
	private final WalkingCollisionMap collisionMap;
	private final List<RouteTransport> transports;

	private RoutingData(WalkingCollisionMap collisionMap, List<RouteTransport> transports)
	{
		this.collisionMap = collisionMap;
		this.transports = Collections.unmodifiableList(new ArrayList<>(transports));
	}

	public static RoutingData load() throws IOException
	{
		try (InputStream collision = resource("collision-map.zip");
			InputStream passages = resource("transports.tsv");
			InputStream shortcuts = resource("agility_shortcuts.tsv"))
		{
			return load(collision, passages, shortcuts);
		}
	}

	/** Alternate streams make format, lock, and graph regressions independent of live game state. */
	public static RoutingData load(InputStream collision, InputStream passages, InputStream shortcuts) throws IOException
	{
		try (InputStream collisionStream = collision; InputStream passageStream = passages; InputStream shortcutStream = shortcuts)
		{
			WalkingCollisionMap map = WalkingCollisionMap.load(collisionStream);
			List<RouteTransport> transports = new ArrayList<>();
			Set<Long> barriers = new HashSet<>();
			read(passageStream, transports, barriers);
			read(shortcutStream, transports, barriers);
			return new RoutingData(map.withTransportBarriers(barriers), transports);
		}
	}

	public WalkingCollisionMap getCollisionMap() { return collisionMap; }
	public List<RouteTransport> getTransports() { return transports; }

	private static InputStream resource(String file) throws IOException
	{
		InputStream stream = RoutingData.class.getResourceAsStream("/routes/" + file);
		if (stream == null)
		{
			throw new IOException("Missing bundled routing resource: " + file);
		}
		return stream;
	}

	private static void read(InputStream stream, List<RouteTransport> transports, Set<Long> barriers) throws IOException
	{
		if (stream == null)
		{
			throw new IOException("Missing physical passage table");
		}
		Map<String, Integer> header = null;
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.trim().isEmpty()) continue;
				if (header == null)
				{
					String candidate = line.startsWith("#") ? line.substring(1).trim() : line;
					List<String> names = Arrays.asList(candidate.split("\\t", -1));
					if (!names.contains("Origin") || !names.contains("Destination")) continue;
					header = new HashMap<>();
					for (int i = 0; i < names.size(); i++) header.put(names.get(i), i);
					continue;
				}
				if (line.startsWith("#")) continue;
				String[] fields = line.split("\\t", -1);
				try
				{
					int from = point(field(header, fields, "Origin"));
					int to = point(field(header, fields, "Destination"));
					if (from == to) continue;
					// Collision dumps open ordinary doors. Explicit passage edges,
					// including ones with unsupported requirements, must never gain
					// an unrestricted ordinary-walking bypass in either direction.
					if (WalkingCollisionMap.adjacent(from, to)) barriers.add(WalkingCollisionMap.edgeKey(from, to));
					Optional<RouteRequirements> requirements = RouteRequirements.parse(
						field(header, fields, "Skills"), field(header, fields, "Items"),
						field(header, fields, "Quests"), field(header, fields, "Varbits"),
						field(header, fields, "VarPlayers"));
					if (!requirements.isPresent()) continue;
					String duration = field(header, fields, "Duration");
					int ticks = duration.isEmpty() ? 1 : Integer.parseInt(duration);
					if (ticks < 0) continue;
					transports.add(new RouteTransport(from, to, Math.max(1, ticks),
						field(header, fields, "menuOption menuTarget objectID"), requirements.get()));
				}
				catch (IllegalArgumentException ignored)
				{
					// Invalid coordinates or unsupported row syntax grant no edge.
				}
			}
		}
		if (header == null) throw new IOException("Physical passage table has no coordinate header");
	}

	private static String field(Map<String, Integer> header, String[] fields, String name)
	{
		Integer index = header.get(name);
		return index == null || index >= fields.length ? "" : fields[index].trim();
	}

	private static int point(String text)
	{
		String[] xyz = text.split("\\s+");
		if (xyz.length != 3) throw new IllegalArgumentException("Invalid passage point");
		int x = Integer.parseInt(xyz[0]);
		int y = Integer.parseInt(xyz[1]);
		int plane = Integer.parseInt(xyz[2]);
		if (x < 0 || x > 16383 || y < 0 || y > 16383 || plane < 0 || plane > 3)
		{
			throw new IllegalArgumentException("Passage point outside world");
		}
		return plane << 28 | x << 14 | y;
	}
}

package com.clueteleports.routing;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

/**
 * Offline collision data pinned with the resources/routes upstream manifest.
 * The four-flag format follows Shortest Path's SplitFlagMap at
 * 31c2e313a348a00fb49dfbee53461610681f94d6; its license is bundled beside the data.
 * Points use RuneLite's 14-bit x/y packing, with the plane in bits 28 and 29.
 */
public class WalkingCollisionMap
{
	private final Map<Integer, byte[]> regions;
	private final Set<Long> transportBarriers;

	/** Empty map for small synthetic graphs that override the public queries. */
	protected WalkingCollisionMap()
	{
		this(Collections.emptyMap(), Collections.emptySet());
	}

	private WalkingCollisionMap(Map<Integer, byte[]> regions, Set<Long> transportBarriers)
	{
		this.regions = regions;
		this.transportBarriers = transportBarriers;
	}

	/** Loads and closes a region ZIP; missing regions and planes remain blocked. */
	public static WalkingCollisionMap load(InputStream stream) throws IOException
	{
		if (stream == null)
		{
			throw new IOException("Missing collision data");
		}
		Map<Integer, byte[]> regions = new HashMap<>();
		try (ZipInputStream zip = new ZipInputStream(stream))
		{
			ZipEntry entry;
			while ((entry = zip.getNextEntry()) != null)
			{
				if (entry.isDirectory())
				{
					continue;
				}
				if (!entry.getName().matches("[0-9]{1,3}_[0-9]{1,3}"))
				{
					throw new IOException("Invalid collision region: " + entry.getName());
				}
				String[] coordinates = entry.getName().split("_");
				int x = Integer.parseInt(coordinates[0]);
				int y = Integer.parseInt(coordinates[1]);
				if (x > 255 || y > 255)
				{
					throw new IOException("Collision region outside world");
				}
				ByteArrayOutputStream bytes = new ByteArrayOutputStream();
				byte[] buffer = new byte[4096];
				int count;
				while ((count = zip.read(buffer)) != -1)
				{
					if (bytes.size() + count > 8192)
					{
						throw new IOException("Collision region exceeds four planes");
					}
					bytes.write(buffer, 0, count);
				}
				if (regions.put((x << 8) | y, bytes.toByteArray()) != null)
				{
					throw new IOException("Duplicate collision region");
				}
			}
		}
		if (regions.isEmpty())
		{
			throw new IOException("Empty collision data");
		}
		return new WalkingCollisionMap(Collections.unmodifiableMap(regions), Collections.emptySet());
	}

	/** Passage eligibility must control these links, including their ordinary-walk bypass. */
	public WalkingCollisionMap withTransportEdges(Collection<RouteTransport> edges)
	{
		Set<Long> barriers = new HashSet<>(transportBarriers);
		for (RouteTransport edge : edges)
		{
			if (adjacent(edge.getFrom(), edge.getTo())) barriers.add(edgeKey(edge.getFrom(), edge.getTo()));
		}
		return withTransportBarriers(barriers);
	}

	WalkingCollisionMap withTransportBarriers(Set<Long> barriers)
	{
		return new WalkingCollisionMap(regions, Collections.unmodifiableSet(new HashSet<>(barriers)));
	}

	public boolean hasRegion(int packed)
	{
		if (!valid(packed))
		{
			return false;
		}
		byte[] bytes = regions.get(regionKey(x(packed), y(packed)));
		return bytes != null && plane(packed) * 2048 < bytes.length;
	}

	public boolean isWalkable(int packed)
	{
		if (!hasRegion(packed))
		{
			return false;
		}
		int x = x(packed);
		int y = y(packed);
		int plane = plane(packed);
		return flag(x, y, plane, 0) || flag(x, y - 1, plane, 0)
			|| flag(x, y, plane, 1) || flag(x - 1, y, plane, 1);
	}

	public boolean canWalk(int from, int to)
	{
		if (!isWalkable(from) || !isWalkable(to) || plane(from) != plane(to))
		{
			return false;
		}
		int dx = x(to) - x(from);
		int dy = y(to) - y(from);
		if (Math.abs(dx) > 1 || Math.abs(dy) > 1 || dx == 0 && dy == 0
			|| transportBarriers.contains(edgeKey(from, to)))
		{
			return false;
		}
		if (dx == 0 || dy == 0)
		{
			return cardinal(from, to);
		}
		// Each of the two paths around the corner must be clear. This also
		// prevents diagonal bypasses of a requirement-gated door edge.
		int horizontal = pack(x(to), y(from), plane(from));
		int vertical = pack(x(from), y(to), plane(from));
		return cardinal(from, horizontal) && cardinal(horizontal, to)
			&& cardinal(from, vertical) && cardinal(vertical, to);
	}

	/**
	 * Only the search's explicit catalog arrival may use this escape rule.
	 * Object footprints can block the forced landing tile; walls and passage
	 * locks still apply. Arbitrary blocked graph nodes must use canWalk.
	 */
	public boolean canLeaveArrival(int from, int to)
	{
		return canWalk(from, to) || (!isWalkable(from) && hasRegion(from) && isWalkable(to)
			&& unwalledCardinal(from, to));
	}

	/**
	 * Tests the usable face of a solid task object without crossing a wall.
	 * A two-tile solid footprint may be interacted with from its outside face;
	 * this does not grant a walking edge through the intervening footprint.
	 */
	public boolean canInteractFrom(int face, int solidTarget)
	{
		if (isWalkable(solidTarget))
		{
			return canWalk(face, solidTarget);
		}
		if (!isWalkable(face) || !hasRegion(solidTarget) || plane(face) != plane(solidTarget))
		{
			return false;
		}
		int dx = x(solidTarget) - x(face);
		int dy = y(solidTarget) - y(face);
		int distance = Math.abs(dx) + Math.abs(dy);
		if (distance < 1 || distance > 2 || dx != 0 && dy != 0)
		{
			return false;
		}
		int current = face;
		for (int step = 0; step < distance; step++)
		{
			int next = pack(x(current) + Integer.signum(dx), y(current) + Integer.signum(dy), plane(face));
			if (!unwalledCardinal(current, next))
			{
				return false;
			}
			current = next;
		}
		return true;
	}

	private boolean unwalledCardinal(int from, int to)
	{
		if (!hasRegion(from) || !hasRegion(to) || plane(from) != plane(to)
			|| Math.abs(x(from) - x(to)) + Math.abs(y(from) - y(to)) != 1
			|| transportBarriers.contains(edgeKey(from, to)))
		{
			return false;
		}
		int x = x(from);
		int y = y(from);
		int plane = plane(from);
		if (x(to) == x + 1) return !flag(x, y, plane, 3);
		if (x(to) == x - 1) return !flag(x - 1, y, plane, 3);
		if (y(to) == y + 1) return !flag(x, y, plane, 2);
		return !flag(x, y - 1, plane, 2);
	}

	private boolean cardinal(int from, int to)
	{
		if (!hasRegion(from) || !hasRegion(to) || transportBarriers.contains(edgeKey(from, to)))
		{
			return false;
		}
		int x = x(from);
		int y = y(from);
		int plane = plane(from);
		if (x(to) == x + 1) return flag(x, y, plane, 1);
		if (x(to) == x - 1) return flag(x - 1, y, plane, 1);
		if (y(to) == y + 1) return flag(x, y, plane, 0);
		if (y(to) == y - 1) return flag(x, y - 1, plane, 0);
		return false;
	}

	private boolean flag(int x, int y, int plane, int flag)
	{
		if (x < 0 || y < 0 || x > 16383 || y > 16383 || plane < 0 || plane > 3)
		{
			return false;
		}
		byte[] bytes = regions.get(regionKey(x, y));
		int bit = (plane * 4096 + (y & 63) * 64 + (x & 63)) * 4 + flag;
		return bytes != null && (bit >>> 3) < bytes.length && (bytes[bit >>> 3] & (1 << (bit & 7))) != 0;
	}

	static long edgeKey(int from, int to)
	{
		return ((long) Math.min(from, to) << 32) | (Math.max(from, to) & 0xffffffffL);
	}

	static boolean adjacent(int from, int to)
	{
		return plane(from) == plane(to) && from != to
			&& Math.abs(x(from) - x(to)) <= 1 && Math.abs(y(from) - y(to)) <= 1;
	}

	private static int regionKey(int x, int y) { return ((x >>> 6) << 8) | (y >>> 6); }
	private static boolean valid(int packed) { return (packed & 0xc0000000) == 0; }
	private static int x(int packed) { return packed >>> 14 & 16383; }
	private static int y(int packed) { return packed & 16383; }
	private static int plane(int packed) { return packed >>> 28 & 3; }
	private static int pack(int x, int y, int plane) { return plane << 28 | x << 14 | y; }
}

package com.clueteleports.routing;

import com.clueteleports.TeleportDestination;
import java.util.Objects;
import net.runelite.api.coords.WorldPoint;

/** A completed search, or an explicit reason no minimum route was established. */
public final class WalkingRouteResult
{
	public enum Status
	{
		FOUND, NO_ROUTE, LIMIT, CANCELLED
	}

	private final Status status;
	private final TeleportDestination destination;
	private final WorldPoint target;
	private final long costHalfTicks;
	private final int walkingTiles;
	private final int transitionCount;

	private WalkingRouteResult(Status status, TeleportDestination destination, WorldPoint target,
		long costHalfTicks, int walkingTiles, int transitionCount)
	{
		this.status = status;
		this.destination = destination;
		this.target = target;
		this.costHalfTicks = costHalfTicks;
		this.walkingTiles = walkingTiles;
		this.transitionCount = transitionCount;
	}

	static WalkingRouteResult found(TeleportDestination destination, WorldPoint target,
		long costHalfTicks, int walkingTiles, int transitionCount)
	{
		return new WalkingRouteResult(Status.FOUND, Objects.requireNonNull(destination),
			Objects.requireNonNull(target), costHalfTicks, walkingTiles, transitionCount);
	}

	public static WalkingRouteResult withoutRoute(Status status)
	{
		if (status == Status.FOUND)
		{
			throw new IllegalArgumentException("A found route requires a destination and target");
		}
		return new WalkingRouteResult(Objects.requireNonNull(status), null, null, -1, 0, 0);
	}

	public Status getStatus()
	{
		return status;
	}

	public boolean isFound()
	{
		return status == Status.FOUND;
	}

	/** Null unless a minimum route was found. */
	public TeleportDestination getDestination()
	{
		return destination;
	}

	/** The qualified clue goal reached by this route; null unless found. */
	public WorldPoint getTarget()
	{
		return target;
	}

	/**
	 * One unit per ordinary walking tile, plus twice each physical action's
	 * duration in ticks. This estimates continuous running, not elapsed time.
	 */
	public long getCostHalfTicks()
	{
		return costHalfTicks;
	}

	public int getWalkingTiles()
	{
		return walkingTiles;
	}

	public int getTransitionCount()
	{
		return transitionCount;
	}

	public double getEstimatedRunTicks()
	{
		return isFound() ? costHalfTicks / 2.0 : -1.0;
	}
}

package com.clueteleports.routing;

import com.clueteleports.TeleportDestination;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.TimeUnit;
import java.util.function.BooleanSupplier;
import java.util.function.LongSupplier;
import net.runelite.api.coords.WorldPoint;

/**
 * Reverse Dijkstra from qualified clue goals to available POH arrivals.
 *
 * The collision map and account-filtered physical transports are immutable input;
 * no RuneLite Client calls, portable teleports, or user settings are consulted.
 * Known catalog arrivals may leave a blocked fixture footprint only through
 * the collision map's strict, wall-aware arrival exit check.
 * Reverse walking checks canWalk(neighbour, current), and physical edges are
 * indexed destination-to-origin, preserving directed doors, stairs, and ladders.
 *
 * A found route is returned only after its arrival leaves the minimum-cost
 * queue. Equal-cost arrivals are exhausted to resolve source/id ties. Hitting
 * the work/time budget never promotes a provisional route to a minimum.
 */
public final class WalkingRouteSearch
{
	private static final int DEFAULT_NODE_LIMIT = 1_000_000;
	private static final long DEFAULT_TIME_LIMIT_MILLIS = 5_000;
	private static final int[] DX = {0, 1, 0, -1, 1, 1, -1, -1};
	private static final int[] DY = {1, 0, -1, 0, 1, -1, -1, 1};
	private static final Comparator<TeleportDestination> DESTINATIONS =
		Comparator.comparingInt((TeleportDestination destination) -> destination.getSource().ordinal())
			.thenComparing(TeleportDestination::getId);
	private static final Comparator<WorldPoint> GOALS = Comparator.comparingInt(WorldPoint::getPlane)
		.thenComparingInt(WorldPoint::getX).thenComparingInt(WorldPoint::getY);
	private final int maxNodes;
	private final long maxNanos;
	private final LongSupplier nanoTime;

	public WalkingRouteSearch()
	{
		this(DEFAULT_NODE_LIMIT, DEFAULT_TIME_LIMIT_MILLIS);
	}

	public WalkingRouteSearch(int maxNodes, long maxMillis)
	{
		this(maxNodes, maxMillis, System::nanoTime);
	}

	WalkingRouteSearch(int maxNodes, long maxMillis, LongSupplier nanoTime)
	{
		if (maxNodes < 1 || maxMillis < 1)
		{
			throw new IllegalArgumentException("Search limits must be positive");
		}
		this.maxNodes = maxNodes;
		this.maxNanos = TimeUnit.MILLISECONDS.toNanos(maxMillis);
		this.nanoTime = Objects.requireNonNull(nanoTime);
	}

	/**
	 * Goals must already represent valid standing/interaction tiles. The engine
	 * never invents nearby goals or escapes blocked teleport tiles through walls.
	 * Input transports must already satisfy the current account's requirements.
	 */
	public WalkingRouteResult search(WalkingCollisionMap collision, Collection<RouteTransport> eligible,
		List<WorldPoint> goals, Collection<TeleportDestination> arrivals, BooleanSupplier cancel)
	{
		Objects.requireNonNull(collision);
		Objects.requireNonNull(eligible);
		Objects.requireNonNull(goals);
		Objects.requireNonNull(arrivals);
		Objects.requireNonNull(cancel);
		if (cancelled(cancel))
		{
			return WalkingRouteResult.withoutRoute(WalkingRouteResult.Status.CANCELLED);
		}
		long started = nanoTime.getAsLong();
		Map<Integer, TeleportDestination> destinations = new HashMap<>();
		for (TeleportDestination arrival : arrivals)
		{
			if (arrival != null && valid(arrival.getLocation()))
			{
				destinations.merge(pack(arrival.getLocation()), arrival,
					(first, second) -> DESTINATIONS.compare(first, second) <= 0 ? first : second);
			}
		}
		List<WorldPoint> targets = new ArrayList<>();
		Map<Integer, WorldPoint> distinctGoals = new LinkedHashMap<>();
		goals.stream().filter(Objects::nonNull).filter(WalkingRouteSearch::valid).sorted(GOALS)
			.forEach(goal -> distinctGoals.putIfAbsent(pack(goal), goal));
		targets.addAll(distinctGoals.values());
		if (destinations.isEmpty() || targets.isEmpty())
		{
			return WalkingRouteResult.withoutRoute(WalkingRouteResult.Status.NO_ROUTE);
		}
		Map<Integer, List<RouteTransport>> reversed = new HashMap<>();
		for (RouteTransport edge : eligible)
		{
			if (edge != null && validPacked(edge.getFrom()) && validPacked(edge.getTo()))
			{
				reversed.computeIfAbsent(edge.getTo(), ignored -> new ArrayList<>()).add(edge);
			}
		}

		Nodes nodes = new Nodes(maxNodes);
		for (int index = 0; index < targets.size(); index++)
		{
			if (!nodes.relax(pack(targets.get(index)), 0, index, 0, 0))
			{
				return WalkingRouteResult.withoutRoute(WalkingRouteResult.Status.LIMIT);
			}
		}
		WalkingRouteResult best = null;
		int settled = 0;
		while (!nodes.isEmpty())
		{
			if ((settled & 255) == 0)
			{
				if (cancelled(cancel))
				{
					return WalkingRouteResult.withoutRoute(WalkingRouteResult.Status.CANCELLED);
				}
				// Cancellation still wins, but a completed minimum needs no more
				// budget once every remaining label is strictly more expensive.
				if (best != null && nodes.minimumCost() > best.getCostHalfTicks())
				{
					return best;
				}
				if (nanoTime.getAsLong() - started >= maxNanos)
				{
					return WalkingRouteResult.withoutRoute(WalkingRouteResult.Status.LIMIT);
				}
			}
			int node = nodes.pop();
			long cost = nodes.costs[node];
			if (best != null && cost > best.getCostHalfTicks())
			{
				return best;
			}
			settled++;
			int point = nodes.points[node];
			TeleportDestination arrival = destinations.get(point);
			if (arrival != null)
			{
				WalkingRouteResult candidate = WalkingRouteResult.found(arrival,
					targets.get(nodes.goals[node]), cost, nodes.walking[node], nodes.transitions[node]);
				if (best == null || compare(candidate, best) < 0)
				{
					best = candidate;
				}
			}
			if (best != null)
			{
				// Every edge has positive cost, so expanding an equal-cost tile
				// cannot discover another equal-cost arrival.
				continue;
			}
			int x = (point >>> 14) & 0x3fff;
			int y = point & 0x3fff;
			int plane = point >>> 28;
			for (int direction = 0; direction < DX.length; direction++)
			{
				int nx = x + DX[direction];
				int ny = y + DY[direction];
				if (nx < 0 || nx > 0x3fff || ny < 0 || ny > 0x3fff)
				{
					continue;
				}
				int neighbour = (plane << 28) | (nx << 14) | ny;
				if ((collision.canWalk(neighbour, point)
					|| destinations.containsKey(neighbour) && collision.canLeaveArrival(neighbour, point))
					&& !nodes.relax(neighbour, cost + 1, nodes.goals[node],
						nodes.walking[node] + 1, nodes.transitions[node]))
				{
					return WalkingRouteResult.withoutRoute(WalkingRouteResult.Status.LIMIT);
				}
			}
			List<RouteTransport> incoming = reversed.get(point);
			if (incoming != null)
			{
				for (RouteTransport edge : incoming)
				{
					long duration = 2L * Math.max(1, edge.getDurationTicks());
					if (!nodes.relax(edge.getFrom(), cost + duration, nodes.goals[node],
						nodes.walking[node], nodes.transitions[node] + 1))
					{
						return WalkingRouteResult.withoutRoute(WalkingRouteResult.Status.LIMIT);
					}
				}
			}
		}
		if (cancelled(cancel))
		{
			return WalkingRouteResult.withoutRoute(WalkingRouteResult.Status.CANCELLED);
		}
		return best == null ? WalkingRouteResult.withoutRoute(WalkingRouteResult.Status.NO_ROUTE) : best;
	}

	private static int compare(WalkingRouteResult first, WalkingRouteResult second)
	{
		int compared = Long.compare(first.getCostHalfTicks(), second.getCostHalfTicks());
		if (compared == 0)
		{
			compared = DESTINATIONS.compare(first.getDestination(), second.getDestination());
		}
		if (compared == 0)
		{
			compared = GOALS.compare(first.getTarget(), second.getTarget());
		}
		if (compared == 0)
		{
			compared = Integer.compare(first.getWalkingTiles(), second.getWalkingTiles());
		}
		return compared == 0 ? Integer.compare(first.getTransitionCount(), second.getTransitionCount()) : compared;
	}

	private static boolean cancelled(BooleanSupplier cancel)
	{
		return Thread.currentThread().isInterrupted() || cancel.getAsBoolean();
	}

	private static boolean valid(WorldPoint point)
	{
		return point != null && point.getX() >= 0 && point.getX() <= 0x3fff
			&& point.getY() >= 0 && point.getY() <= 0x3fff && point.getPlane() >= 0 && point.getPlane() <= 3;
	}

	private static boolean validPacked(int point)
	{
		return point >= 0 && (point & 0xc0000000) == 0;
	}

	private static int pack(WorldPoint point)
	{
		return (point.getPlane() << 28) | (point.getX() << 14) | point.getY();
	}

	/**
	 * Primitive tile labels and decrease-key heap avoid allocating an object for
	 * every explored tile. The hash table stores nodeIndex+1 (zero means empty),
	 * so even packed tile zero is a valid key. All storage belongs to one search.
	 */
	private static final class Nodes
	{
		private final int limit;
		private int size;
		private int[] points;
		private long[] costs;
		private int[] goals;
		private int[] walking;
		private int[] transitions;
		private int[] heapPositions;
		private int[] table;
		private int[] heap;
		private int heapSize;

		private Nodes(int limit)
		{
			this.limit = limit;
			int capacity = Math.min(limit, 4096);
			points = new int[capacity];
			costs = new long[capacity];
			goals = new int[capacity];
			walking = new int[capacity];
			transitions = new int[capacity];
			heapPositions = new int[capacity];
			table = new int[8192];
			heap = new int[capacity];
		}

		private boolean isEmpty()
		{
			return heapSize == 0;
		}

		private long minimumCost()
		{
			return costs[heap[0]];
		}

		private boolean relax(int point, long cost, int goal, int walked, int actions)
		{
			int slot = slot(point);
			int index = table[slot] - 1;
			if (index >= 0)
			{
				if (heapPositions[index] == -2 || !better(cost, goal, walked, actions, index))
				{
					return true;
				}
			}
			else
			{
				if (size == limit)
				{
					return false;
				}
				if (size == points.length)
				{
					grow();
				}
				if ((size + 1) * 10L >= table.length * 7L)
				{
					rehash();
					slot = slot(point);
				}
				index = size++;
				points[index] = point;
				heapPositions[index] = -1;
				table[slot] = index + 1;
			}
			costs[index] = cost;
			goals[index] = goal;
			walking[index] = walked;
			transitions[index] = actions;
			int position = heapPositions[index];
			if (position == -1)
			{
				position = heapSize++;
				heap[position] = index;
				heapPositions[index] = position;
			}
			up(position);
			return true;
		}

		private boolean better(long cost, int goal, int walked, int actions, int existing)
		{
			if (cost != costs[existing]) return cost < costs[existing];
			if (goal != goals[existing]) return goal < goals[existing];
			if (walked != walking[existing]) return walked < walking[existing];
			return actions < transitions[existing];
		}

		private int pop()
		{
			int result = heap[0];
			heapPositions[result] = -2;
			heapSize--;
			if (heapSize > 0)
			{
				heap[0] = heap[heapSize];
				heapPositions[heap[0]] = 0;
				down(0);
			}
			return result;
		}

		private void up(int position)
		{
			while (position > 0)
			{
				int parent = (position - 1) >>> 1;
				if (compareNodes(heap[parent], heap[position]) <= 0)
				{
					break;
				}
				swap(parent, position);
				position = parent;
			}
		}

		private void down(int position)
		{
			while (position * 2 + 1 < heapSize)
			{
				int child = position * 2 + 1;
				if (child + 1 < heapSize && compareNodes(heap[child + 1], heap[child]) < 0)
				{
					child++;
				}
				if (compareNodes(heap[position], heap[child]) <= 0)
				{
					break;
				}
				swap(position, child);
				position = child;
			}
		}

		private int compareNodes(int first, int second)
		{
			int compared = Long.compare(costs[first], costs[second]);
			if (compared == 0) compared = Integer.compare(goals[first], goals[second]);
			if (compared == 0) compared = Integer.compare(walking[first], walking[second]);
			if (compared == 0) compared = Integer.compare(transitions[first], transitions[second]);
			return compared == 0 ? Integer.compareUnsigned(points[first], points[second]) : compared;
		}

		private void swap(int first, int second)
		{
			int value = heap[first];
			heap[first] = heap[second];
			heap[second] = value;
			heapPositions[heap[first]] = first;
			heapPositions[heap[second]] = second;
		}

		private int slot(int point)
		{
			int hashed = point;
			hashed ^= hashed >>> 16;
			hashed *= 0x7feb352d;
			hashed ^= hashed >>> 15;
			hashed *= 0x846ca68b;
			hashed ^= hashed >>> 16;
			int slot = hashed & (table.length - 1);
			while (table[slot] != 0 && points[table[slot] - 1] != point)
			{
				slot = (slot + 1) & (table.length - 1);
			}
			return slot;
		}

		private void rehash()
		{
			table = new int[table.length * 2];
			for (int index = 0; index < size; index++)
			{
				table[slot(points[index])] = index + 1;
			}
		}

		private void grow()
		{
			int capacity = (int) Math.min(limit, Math.max((long) points.length + 1, points.length * 2L));
			points = Arrays.copyOf(points, capacity);
			costs = Arrays.copyOf(costs, capacity);
			goals = Arrays.copyOf(goals, capacity);
			walking = Arrays.copyOf(walking, capacity);
			transitions = Arrays.copyOf(transitions, capacity);
			heapPositions = Arrays.copyOf(heapPositions, capacity);
			heap = Arrays.copyOf(heap, capacity);
		}
	}
}

