		assertTrue(read(29166).isEmpty());
		assertTrue(read(29180).isEmpty());
		assertTrue(read(29225).isEmpty());
	}

	@Test
	public void chinchompaCounterCountsUsedTeleportsAndRefreshesOutsideHouse()
	{
