		varps.put(VarPlayerID.QP, 342);
		assertFalse(CapeReader.availableNow(client, "cape-legends-guild"));
		varps.put(VarPlayerID.QP, 343);
		assertTrue(CapeReader.availableNow(client, "cape-legends-guild"));
