package com.clueteleports.routing;

import java.lang.reflect.Proxy;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import net.runelite.api.VarbitComposition;
import net.runelite.api.gameval.InventoryID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

public class AccountRouteStateTest
{
	private final Fixture fixture = new Fixture();

	@Test(expected = IllegalStateException.class)
	public void captureMustRunOnClientThread()
	{
		fixture.clientThread = false;
		AccountRouteState.capture(fixture.client, List.of(RouteRequirements.none()));
	}

	@Test
	public void capturesNativeRequirementsAndReadyInventoryEquipment()
	{
		RouteRequirements required = required("70 Agility", "CROSSBOW=1&MITH_GRAPPLE=1", "Tree Gnome Village", "10=1", "20>3");
		fixture.real.put(Skill.AGILITY, 65);
		fixture.boosted.put(Skill.AGILITY, 70);
		fixture.bits.put(10, 1);
		fixture.nativeVarps[20] = 4;
		fixture.finishedQuests.add(Quest.TREE_GNOME_VILLAGE.getId());
		fixture.inventory = items(new Item(9419, 1));
		fixture.equipment = items(new Item(837, 1));

		AccountRouteState state = AccountRouteState.capture(fixture.client, List.of(required));

		assertTrue(required.isSatisfied(state));
		assertEquals(Set.of(10), fixture.readVarbits);
		assertEquals(Set.of(Quest.TREE_GNOME_VILLAGE.getId()), fixture.readQuests);
		assertEquals(Set.of(InventoryID.INV, InventoryID.WORN), fixture.readContainers);
	}

	@Test
	public void snapshotRemainsIndependentOfLaterClientChangesAndNoClientCallsEscape()
	{
		RouteRequirements required = required("70 Agility", "995=5", "", "10=1", "20=4");
		fixture.boosted.put(Skill.AGILITY, 70);
		fixture.bits.put(10, 1);
		fixture.nativeVarps[20] = 4;
		fixture.inventory = items(new Item(995, 5));
		AccountRouteState state = AccountRouteState.capture(fixture.client, List.of(required));
		fixture.boosted.clear();
		fixture.bits.clear();
		fixture.nativeVarps[20] = 0;
		fixture.inventory = items();
		fixture.allowClientCalls = false;

		assertTrue(required.isSatisfied(state));
		assertEquals(state, state);
		state.hashCode();
	}

	@Test
	public void missingVarbitDefinitionNeverLooksLikeKnownZero()
	{
		RouteRequirements required = required("", "", "", "10=0", "");
		assertFalse(required.isSatisfied(AccountRouteState.capture(fixture.client, List.of(required))));
		fixture.bits.put(10, 0);
		assertTrue(required.isSatisfied(AccountRouteState.capture(fixture.client, List.of(required))));
	}

	@Test
	public void outOfRangeOrMissingVarpsFailClosed()
	{
		RouteRequirements required = required("", "", "", "", "9000=0");
		assertFalse(required.isSatisfied(AccountRouteState.capture(fixture.client, List.of(required))));
		fixture.nativeVarps = null;
		assertFalse(required.isSatisfied(AccountRouteState.capture(fixture.client, List.of(required))));
	}

	@Test
	public void unknownItemContainersCannotProveAnItemAbsent()
	{
		RouteRequirements absence = required("", "2376=0", "", "", "");
		fixture.inventory = null;
		assertFalse(absence.isSatisfied(AccountRouteState.capture(fixture.client, List.of(absence))));
		fixture.inventory = items();
		fixture.equipment = null;
		assertFalse(absence.isSatisfied(AccountRouteState.capture(fixture.client, List.of(absence))));
	}

	@Test
	public void quantitiesCombineInventoryAndEquipmentAndIgnoreEmptySlots()
	{
		RouteRequirements required = required("", "995=5", "", "", "");
		fixture.inventory = items(null, new Item(-1, 0), new Item(995, 3));
		fixture.equipment = items(new Item(995, 2));
		assertTrue(required.isSatisfied(AccountRouteState.capture(fixture.client, List.of(required))));
	}

	@Test
	public void unavailableQuestStateFailsClosed()
	{
		RouteRequirements required = required("", "", "Tree Gnome Village", "", "");
		fixture.missingQuestStack = true;
		assertFalse(required.isSatisfied(AccountRouteState.capture(fixture.client, List.of(required))));
	}

	@Test
	public void equalCapturedStatesHaveEqualHashCodesAndChangesInvalidateCacheKey()
	{
		RouteRequirements required = required("70 Agility", "995=5", "", "10=1", "");
		fixture.boosted.put(Skill.AGILITY, 70);
		fixture.bits.put(10, 1);
		fixture.inventory = items(new Item(995, 5));
		AccountRouteState first = AccountRouteState.capture(fixture.client, List.of(required));
		AccountRouteState same = AccountRouteState.capture(fixture.client, List.of(required));
		assertEquals(first, same);
		assertEquals(first.hashCode(), same.hashCode());
		fixture.boosted.put(Skill.AGILITY, 69);
		assertNotEquals(first, AccountRouteState.capture(fixture.client, List.of(required)));
		fixture.boosted.put(Skill.AGILITY, 70);
		fixture.bits.put(10, 0);
		assertNotEquals(first, AccountRouteState.capture(fixture.client, List.of(required)));
	}

	@Test
	public void equipmentReadinessParticipatesInEqualityEvenWithSameTotalItems()
	{
		RouteRequirements required = required("", "CROSSBOW=1", "", "", "");
		fixture.inventory = items(new Item(837, 1));
		AccountRouteState carried = AccountRouteState.capture(fixture.client, List.of(required));
		fixture.inventory = items();
		fixture.equipment = items(new Item(837, 1));
		AccountRouteState worn = AccountRouteState.capture(fixture.client, List.of(required));

		assertNotEquals(carried, worn);
		assertFalse(required.isSatisfied(carried));
		assertTrue(required.isSatisfied(worn));
	}

	@Test
	public void emptyGraphsDoNotCaptureUnrelatedQuestOrNativeVars()
	{
		AccountRouteState.capture(fixture.client, List.of(RouteRequirements.none()));
		assertTrue(fixture.readQuests.isEmpty());
		assertTrue(fixture.readVarbits.isEmpty());
	}

	private static RouteRequirements required(String skills, String items, String quests, String bits, String players)
	{
		return RouteRequirements.parse(skills, items, quests, bits, players).orElseThrow();
	}

	private static ItemContainer items(Item... contents)
	{
		return proxy(ItemContainer.class, (name, args) ->
		{
			if ("getItems".equals(name)) return contents;
			throw new UnsupportedOperationException(name);
		});
	}

	private static <T> T proxy(Class<T> type, Calls calls)
	{
		return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type},
			(instance, method, args) -> calls.call(method.getName(), args)));
	}

	private interface Calls
	{
		Object call(String name, Object[] args);
	}

	private static final class Fixture
	{
		private boolean clientThread = true;
		private boolean allowClientCalls = true;
		private boolean missingQuestStack;
		private final Map<Skill, Integer> real = new EnumMap<>(Skill.class);
		private final Map<Skill, Integer> boosted = new EnumMap<>(Skill.class);
		private final Map<Integer, Integer> bits = new HashMap<>();
		private int[] nativeVarps = new int[100];
		private final Set<Integer> finishedQuests = new HashSet<>();
		private final Set<Integer> readQuests = new HashSet<>();
		private final Set<Integer> readVarbits = new HashSet<>();
		private final Set<Integer> readContainers = new HashSet<>();
		private final int[] intStack = new int[1];
		private ItemContainer inventory = items();
		private ItemContainer equipment = items();
		private final Client client = proxy(Client.class, (name, args) ->
		{
			if (!allowClientCalls) throw new AssertionError("Client call after capture: " + name);
			switch (name)
			{
				case "isClientThread": return clientThread;
				case "getRealSkillLevel": return real.getOrDefault(args[0], 1);
				case "getBoostedSkillLevel": return boosted.getOrDefault(args[0], 1);
				case "getVarbit":
					readVarbits.add((Integer) args[0]);
					return bits.containsKey(args[0]) ? proxy(VarbitComposition.class,
						(method, arguments) -> { throw new UnsupportedOperationException(method); }) : null;
				case "getVarbitValue": return bits.get(args[0]);
				case "getVarps": return nativeVarps;
				case "runScript":
					Object[] script = (Object[]) args[0];
					int questId = (Integer) script[1];
					readQuests.add(questId);
					intStack[0] = finishedQuests.contains(questId) ? 2 : 1;
					return null;
				case "getIntStack": return missingQuestStack ? null : intStack;
				case "getItemContainer":
					readContainers.add((Integer) args[0]);
					if ((Integer) args[0] == InventoryID.INV) return inventory;
					if ((Integer) args[0] == InventoryID.WORN) return equipment;
					throw new AssertionError("Unexpected bank/container read: " + args[0]);
				default: throw new UnsupportedOperationException(name);
			}
		});
	}
}

package com.clueteleports.routing;

import com.clueteleports.TeleportCatalog;
import com.clueteleports.TeleportDestination;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.BeforeClass;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Pinned-data connectivity checks. All bundled physical edges are supplied here
 * deliberately; account eligibility and unknown-state gates have separate tests.
 * No portable teleport edges are present in the bundled physical tables.
 */
public class BundledRoutingTest
{
	private static RoutingData data;

	@BeforeClass
	public static void loadPinnedData() throws Exception
	{
		data = RoutingData.load();
	}

	@Test
	public void surfaceClueChoosesTheNearbyMusicCapeArrival()
	{
		TeleportDestination music = TeleportCatalog.byId("cape-falo-the-bard").get();
		WalkingRouteResult result = route(new WorldPoint(2689, 3550, 0),
			List.of(music, TeleportCatalog.byId("fairy-blr").get()), 1);

		assertEquals(WalkingRouteResult.Status.FOUND, result.getStatus());
		assertEquals(music.getId(), result.getDestination().getId());
		assertTrue(result.getWalkingTiles() > 0);
		assertTrue(result.getCostHalfTicks() < 30);
	}

	@Test
	public void kourendBloodAltarIsReachedThroughTheMappedTerrain()
	{
		TeleportDestination ring = TeleportCatalog.byId("fairy-cis").get();
		// Core RuneLite RunecraftingAltarLocation/ChallengeLocations marker.
		WalkingRouteResult result = route(new WorldPoint(1716, 3827, 0), List.of(ring), 2);

		assertEquals(WalkingRouteResult.Status.FOUND, result.getStatus());
		assertEquals(ring.getId(), result.getDestination().getId());
		assertTrue(result.getWalkingTiles() > 0);
		assertTrue(result.getCostHalfTicks() < 1500);
	}

	@Test
	public void varrockStairsConnectTheSurfaceArrivalToTheUpperFloor()
	{
		TeleportDestination varrock = TeleportCatalog.byId("nexus-varrock").get();
		// Exact native destination of Staircase 11807, in the pinned physical TSV.
		WorldPoint upstairs = new WorldPoint(3212, 3476, 1);
		WalkingRouteResult result = new WalkingRouteSearch().search(data.getCollisionMap(),
			data.getTransports(), List.of(upstairs), List.of(varrock), () -> false);

		assertEquals(WalkingRouteResult.Status.FOUND, result.getStatus());
		assertEquals(1, result.getTarget().getPlane());
		assertTrue(result.getTransitionCount() >= 1);
		assertTrue(result.getWalkingTiles() > 0);
		assertTrue(result.getCostHalfTicks() < 250);
	}

	@Test
	public void dungeonStairsConnectSurfaceAndUndergroundCoordinateSpaces()
	{
		TeleportDestination barrows = TeleportCatalog.byId("nexus-barrows").get();
		// Staircase 39092 links 3633,3339,0 to this mapped dungeon destination.
		WorldPoint underground = new WorldPoint(3696, 9764, 2);
		WalkingRouteResult result = new WalkingRouteSearch().search(data.getCollisionMap(),
			data.getTransports(), List.of(underground), List.of(barrows), () -> false);

		assertEquals(WalkingRouteResult.Status.FOUND, result.getStatus());
		assertEquals(underground, result.getTarget());
		assertTrue(result.getTransitionCount() >= 1);
		assertTrue(result.getWalkingTiles() > 0);
		assertTrue("Pinned Darkmeyer dungeon route cost: " + result.getCostHalfTicks(),
			result.getCostHalfTicks() < 5000);
	}

	private static WalkingRouteResult route(WorldPoint target, List<TeleportDestination> arrivals, int radius)
	{
		return new WalkingRouteSearch().search(data.getCollisionMap(), data.getTransports(),
			RouteGoals.qualify(data.getCollisionMap(), List.of(target), radius), arrivals, () -> false);
	}
}

package com.clueteleports.routing;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class RouteGoalsTest
{
	private final SyntheticMap map = new SyntheticMap();

	@Test
	public void walkableDigGoalStaysExact()
	{
		WorldPoint target = point(10, 10);
		map.open(target, point(11, 10));

		assertEquals(List.of(target), RouteGoals.qualify(map, List.of(target), 0));
	}

	@Test
	public void blockedDigGoalNeverSnapsToAConvenientNearbyTile()
	{
		WorldPoint target = point(10, 10);
		map.open(point(11, 10), point(10, 11));

		assertTrue(RouteGoals.qualify(map, List.of(target), 0).isEmpty());
	}

	@Test
	public void walkableNpcUsesOnlyCardinalFacesWithARealForwardEdge()
	{
		WorldPoint target = point(10, 10);
		WorldPoint north = point(10, 11);
		WorldPoint east = point(11, 10);
		WorldPoint south = point(10, 9);
		WorldPoint west = point(9, 10);
		map.open(target, north, east, south, west, point(11, 11));
		map.edge(north, target);
		map.edge(east, target);
		map.edge(target, south); // The reverse direction alone is insufficient.

		assertEquals(Set.of(target, north, east),
			new HashSet<>(RouteGoals.qualify(map, List.of(target), 1)));
	}

	@Test
	public void walkableNpcDoesNotExpandToRadiusTwoThroughItsWall()
	{
		WorldPoint target = point(10, 10);
		map.open(target, point(10, 12));

		assertEquals(List.of(target), RouteGoals.qualify(map, List.of(target), 2));
	}

	@Test
	public void explicitSolidInteractionUsesItsNearestMappedCardinalFaces()
	{
		WorldPoint target = point(10, 10);
		WorldPoint north = point(10, 11);
		WorldPoint east = point(11, 10);
		map.open(north, east, point(10, 12), point(11, 11));

		assertEquals(Set.of(north, east),
			new HashSet<>(RouteGoals.qualify(map, List.of(target), 2)));
	}

	@Test
	public void solidInteractionCanReachRadiusTwoOnlyWhenRadiusOneHasNoFace()
	{
		WorldPoint target = point(10, 10);
		WorldPoint northTwo = point(10, 12);
		map.open(northTwo, point(11, 11));

		assertTrue(RouteGoals.qualify(map, List.of(target), 1).isEmpty());
		assertEquals(List.of(northTwo), RouteGoals.qualify(map, List.of(target), 2));
	}


	@Test
	public void blockedObjectNeverChoosesAFaceAcrossAStructuralWall()
	{
		WorldPoint target = point(10, 10);
		WorldPoint north = point(10, 11);
		WorldPoint east = point(11, 10);
		map.open(north, east);
		map.blockedInteractions.add(((long) RouteGoals.pack(north) << 32) | Integer.toUnsignedLong(RouteGoals.pack(target)));
		assertEquals(List.of(east), RouteGoals.qualify(map, List.of(target), 1));
	}

	@Test
	public void missingCollisionDataDoesNotCreateGoals()
	{
		assertTrue(RouteGoals.qualify(map, List.of(point(10, 10)), 2).isEmpty());
		assertTrue(RouteGoals.qualify(map, Collections.emptyList(), 2).isEmpty());
	}

	@Test
	public void interactionExpansionIsBoundedAndNeverTakesDiagonalFaces()
	{
		WorldPoint target = point(10, 10);
		map.open(point(11, 11), point(10, 13), point(13, 10));

		assertTrue(RouteGoals.qualify(map, List.of(target), 100).isEmpty());
	}

	@Test
	public void goalsRetainTheirPlaneAndDoNotBorrowSurfaceFaces()
	{
		WorldPoint upstairs = new WorldPoint(10, 10, 1);
		map.open(point(10, 11), point(11, 10));

		assertTrue(RouteGoals.qualify(map, List.of(upstairs), 2).isEmpty());
	}

	@Test
	public void worldEdgesDoNotWrapIntoNegativeCoordinates()
	{
		WorldPoint target = point(0, 0);
		map.open(point(0, 1), point(1, 0), point(16383, 0), point(0, 16383));

		assertEquals(Set.of(point(0, 1), point(1, 0)),
			new HashSet<>(RouteGoals.qualify(map, List.of(target), 2)));
	}

	@Test
	public void duplicatedTargetsAndOverlappingFacesAreDeduplicatedWithoutChangingInputs()
	{
		WorldPoint first = point(10, 10);
		WorldPoint second = point(12, 10);
		WorldPoint shared = point(11, 10);
		map.open(shared);
		List<WorldPoint> inputs = new ArrayList<>(List.of(first, second, first));

		assertEquals(List.of(shared), RouteGoals.qualify(map, inputs, 1));
		assertEquals(List.of(first, second, first), inputs);
	}

	@Test(expected = UnsupportedOperationException.class)
	public void qualifiedGoalsAreAnImmutableSnapshot()
	{
		map.open(point(10, 10));
		RouteGoals.qualify(map, List.of(point(10, 10)), 0).clear();
	}

	private static WorldPoint point(int x, int y)
	{
		return new WorldPoint(x, y, 0);
	}

	private static final class SyntheticMap extends WalkingCollisionMap
	{
		private final Set<Integer> open = new HashSet<>();
		private final Set<Long> edges = new HashSet<>();
		private final Set<Long> blockedInteractions = new HashSet<>();

		private void open(WorldPoint... points)
		{
			for (WorldPoint point : points) open.add(RouteGoals.pack(point));
		}

		private void edge(WorldPoint from, WorldPoint to)
		{
			edges.add(((long) RouteGoals.pack(from) << 32) | Integer.toUnsignedLong(RouteGoals.pack(to)));
		}

		@Override public boolean canInteractFrom(int from, int to)
		{
			return isWalkable(from) && (!isWalkable(to) || canWalk(from, to))
				&& !blockedInteractions.contains(((long) from << 32) | Integer.toUnsignedLong(to));
		}

		@Override public boolean isWalkable(int point) { return open.contains(point); }
		@Override public boolean canWalk(int from, int to)
		{
			return edges.contains(((long) from << 32) | Integer.toUnsignedLong(to));
		}
	}
}

package com.clueteleports.routing;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class RouteRequirementsTest
{
	private final State state = new State();

	@Test
	public void emptyRequirementsAcceptAnOtherwiseUnknownSnapshot()
	{
		assertTrue(RouteRequirements.none().isSatisfied(state.build()));
		assertTrue(RouteRequirements.parse(null, "", " ", null, "").orElseThrow().isSatisfied(state.build()));
		assertFalse(RouteRequirements.none().isSatisfied(null));
	}

	@Test
	public void agilityUsesCurrentBoostedLevelAndReactsToDrain()
	{
		RouteRequirements requirement = required("70 Agility", "", "", "", "");
		state.real.put(Skill.AGILITY, 65);
		state.boosted.put(Skill.AGILITY, 70);
		assertTrue(requirement.isSatisfied(state.build()));
		state.real.put(Skill.AGILITY, 75);
		state.boosted.put(Skill.AGILITY, 69);
		assertFalse(requirement.isSatisfied(state.build()));
	}

	@Test
	public void prayerGuildChecksLevelRatherThanRemainingPrayerPoints()
	{
		RouteRequirements requirement = required("31 Prayer", "", "", "", "");
		state.real.put(Skill.PRAYER, 31);
		state.boosted.put(Skill.PRAYER, 0);
		assertTrue(requirement.isSatisfied(state.build()));
		state.real.put(Skill.PRAYER, 30);
		state.boosted.put(Skill.PRAYER, 31);
		assertFalse(requirement.isSatisfied(state.build()));
	}

	@Test
	public void everyDeclaredSkillMustBeMetAndUnknownSkillsCannotPass()
	{
		RouteRequirements requirement = required("8 Agility;37 Ranged;19 Strength", "", "", "", "");
		state.boosted.put(Skill.AGILITY, 8);
		state.boosted.put(Skill.RANGED, 37);
		assertFalse(requirement.isSatisfied(state.build()));
		state.boosted.put(Skill.STRENGTH, 19);
		assertTrue(requirement.isSatisfied(state.build()));
		assertFalse(RouteRequirements.parse("70 Unknown", "", "", "", "").isPresent());
		assertFalse(RouteRequirements.parse("Agility 70", "", "", "", "").isPresent());
	}

	@Test
	public void questsMustBeKnownAndFinished()
	{
		RouteRequirements requirement = required("", "", "Tree Gnome Village", "", "");
		assertFalse(requirement.isSatisfied(state.build()));
		state.quests.put(Quest.TREE_GNOME_VILLAGE, QuestState.IN_PROGRESS);
		assertFalse(requirement.isSatisfied(state.build()));
		state.quests.put(Quest.TREE_GNOME_VILLAGE, QuestState.FINISHED);
		assertTrue(requirement.isSatisfied(state.build()));
		assertFalse(RouteRequirements.parse("", "", "Unknown quest", "", "").isPresent());
	}

	@Test
	public void allQuestTermsAreRequired()
	{
		RouteRequirements requirement = required("", "", "Tree Gnome Village;The Grand Tree", "", "");
		state.quests.put(Quest.TREE_GNOME_VILLAGE, QuestState.FINISHED);
		assertFalse(requirement.isSatisfied(state.build()));
		state.quests.put(Quest.THE_GRAND_TREE, QuestState.FINISHED);
		assertTrue(requirement.isSatisfied(state.build()));
	}

	@Test
	public void varbitAndVarpGatesKeepStrictComparisonsAndMaskSemantics()
	{
		RouteRequirements requirement = required("", "", "", "10=1;11>3;12<5;13&4", "20>2");
		state.bits.put(10, 1);
		state.bits.put(11, 4);
		state.bits.put(12, 4);
		state.bits.put(13, 12);
		state.players.put(20, 3);
		assertTrue(requirement.isSatisfied(state.build()));
		state.bits.put(11, 3);
		assertFalse(requirement.isSatisfied(state.build()));
		state.bits.put(11, 4);
		state.bits.put(13, 2);
		assertFalse(requirement.isSatisfied(state.build()));
	}

	@Test
	public void unknownNativeVariableCannotSatisfyZeroOrLessThanGate()
	{
		assertFalse(required("", "", "", "10=0", "").isSatisfied(state.build()));
		assertFalse(required("", "", "", "", "20<10").isSatisfied(state.build()));
		state.bits.put(10, 0);
		assertTrue(required("", "", "", "10=0", "").isSatisfied(state.build()));
	}

	@Test
	public void malformedVariableNeverDropsTheRestOfItsRequirement()
	{
		for (String value : new String[]{"10>=1", "10!=1", "10@5", "10=1;unknown", "-1=0", "10=1;;11=0"})
		{
			assertFalse(value, RouteRequirements.parse("", "", "", value, "").isPresent());
		}
		assertTrue(RouteRequirements.parse("", "", "", "10=1;", "").isPresent());
	}

	@Test
	public void itemAlternativesKeepTheirOwnQuantitiesAndAndGroups()
	{
		RouteRequirements requirement = required("", "SHANTAY_PASS=1|COINS=5&ROPE=1", "", "", "");
		state.items.put(995, 4);
		state.items.put(954, 1);
		assertFalse(requirement.isSatisfied(state.build()));
		state.items.put(995, 5);
		assertTrue(requirement.isSatisfied(state.build()));
		state.items.remove(995);
		state.items.put(1854, 1);
		assertTrue(requirement.isSatisfied(state.build()));
		state.items.remove(954);
		assertFalse(requirement.isSatisfied(state.build()));
	}

	@Test
	public void aliasesAcceptPortableToolsFromInventoryOrEquipment()
	{
		RouteRequirements requirement = required("", "AXE=1&MACHETE=1", "", "", "");
		state.items.put(1351, 1);
		state.worn.put(975, 1);
		assertTrue(requirement.isSatisfied(state.build()));
		state.worn.clear();
		assertFalse(requirement.isSatisfied(state.build()));
	}

	@Test
	public void grappleRequiresEquippedCrossbowAndCarriedGrapple()
	{
		RouteRequirements requirement = required("", "CROSSBOW=1&MITH_GRAPPLE=1", "", "", "");
		state.items.put(837, 1);
		state.items.put(9419, 1);
		assertFalse(requirement.isSatisfied(state.build()));
		state.worn.put(837, 1);
		assertTrue(requirement.isSatisfied(state.build()));
		state.items.remove(9419);
		assertFalse(requirement.isSatisfied(state.build()));
	}

	@Test
	public void quantityZeroRequiresAbsenceAndKnownItemContainers()
	{
		RouteRequirements requirement = required("", "SKAVID_MAP=0", "", "", "");
		assertTrue(requirement.isSatisfied(state.build()));
		state.items.put(2376, 1);
		assertFalse(requirement.isSatisfied(state.build()));
		state.items.clear();
		state.knownItems = false;
		assertFalse(requirement.isSatisfied(state.build()));
	}

	@Test
	public void zeroQuantityAliasDoesNotPassBecauseAnotherVariantIsMissing()
	{
		RouteRequirements requirement = required("", "AXE=0", "", "", "");
		state.items.put(1351, 1);
		assertFalse(requirement.isSatisfied(state.build()));
	}

	@Test
	public void knownDiaryUnlockUsesCollectedNativeReward()
	{
		RouteRequirements requirement = required("", "UNLOCK_KARAMJA_ELITE=1||6306=100", "", "", "");
		assertTrue(requirement.getRequiredVarbits().contains(VarbitID.KARAMJA_ELITE_REWARD));
		assertFalse(requirement.isSatisfied(state.build()));
		state.bits.put(VarbitID.KARAMJA_ELITE_REWARD, 1);
		assertTrue(requirement.isSatisfied(state.build()));
		state.bits.clear();
		state.items.put(6306, 100);
		assertTrue(requirement.isSatisfied(state.build()));
	}

	@Test
	public void serverOnlyUnlockFailsClosedWhileExplicitCarriedAlternativeStillWorks()
	{
		RouteRequirements requirement = required("", "6570=1|UNLOCK_MOR_UL_REK=1", "", "", "");
		assertFalse(requirement.isSatisfied(state.build()));
		state.items.put(6570, 1);
		assertTrue(requirement.isSatisfied(state.build()));
		assertFalse(RouteRequirements.parse("", "UNLOCK_UNKNOWN=1", "", "", "").isPresent());
	}

	@Test
	public void malformedOrUnknownItemRequirementsRejectWholeTransport()
	{
		for (String value : new String[]{"UNKNOWN_TOOL=1", "ROPE", "ROPE=-1", "0=1", "995=1&", "995=1|", "995=999999999999"})
		{
			assertFalse(value, RouteRequirements.parse("", value, "", "", "").isPresent());
		}
		state.items.put(954, 1);
		state.items.put(995, 5);
		assertTrue(required("", "rope=1 && COINS=5 || 1854=1", "", "", "").isSatisfied(state.build()));
	}

	@Test
	public void requestedNativeIdsAreImmutableAndContainEveryConjunct()
	{
		RouteRequirements requirement = required("", "UNLOCK_KARAMJA_ELITE=1", "Tree Gnome Village", "10=1;11>2", "20=0");
		assertEquals(3, requirement.getRequiredVarbits().size());
		assertEquals(1, requirement.getRequiredVarps().size());
		try
		{
			requirement.getRequiredQuests().clear();
			throw new AssertionError("Expected immutable requirements");
		}
		catch (UnsupportedOperationException expected)
		{
			// Expected.
		}
	}

	@Test
	public void everyPinnedPhysicalDataRequirementHasSupportedGrammar() throws Exception
	{
		List<String> rejected = new ArrayList<>();
		int rows = 0;
		for (String resource : new String[]{"transports.tsv", "agility_shortcuts.tsv"})
		{
			try (BufferedReader reader = new BufferedReader(new InputStreamReader(
				RouteRequirements.class.getResourceAsStream("/routes/" + resource), StandardCharsets.UTF_8)))
			{
				String[] header = reader.readLine().split("\\t", -1);
				Map<String, Integer> columns = new HashMap<>();
				for (int i = 0; i < header.length; i++) columns.put(header[i], i);
				String line;
				while ((line = reader.readLine()) != null)
				{
					if (line.isBlank() || line.startsWith("#")) continue;
					String[] values = line.split("\\t", -1);
					rows++;
					if (!RouteRequirements.parse(cell(values, columns.get("Skills")), cell(values, columns.get("Items")),
						cell(values, columns.get("Quests")), cell(values, columns.get("Varbits")),
						cell(values, columns.get("VarPlayers"))).isPresent()) rejected.add(resource + ":" + line);
				}
			}
		}
		assertTrue(rows > 5000);
		assertTrue(rejected.toString(), rejected.isEmpty());
	}

	private static String cell(String[] values, int column)
	{
		return column < values.length ? values[column] : "";
	}

	private static RouteRequirements required(String skills, String items, String quests, String bits, String players)
	{
		return RouteRequirements.parse(skills, items, quests, bits, players).orElseThrow();
	}

	private static final class State
	{
		private final Map<Skill, Integer> real = new EnumMap<>(Skill.class);
		private final Map<Skill, Integer> boosted = new EnumMap<>(Skill.class);
		private final Map<Quest, QuestState> quests = new EnumMap<>(Quest.class);
		private final Map<Integer, Integer> bits = new HashMap<>();
		private final Map<Integer, Integer> players = new HashMap<>();
		private final Map<Integer, Integer> items = new HashMap<>();
		private final Map<Integer, Integer> worn = new HashMap<>();
		private boolean knownItems = true;

		private AccountRouteState build()
		{
			Map<Integer, Integer> combined = new HashMap<>(items);
			worn.forEach((id, count) -> combined.merge(id, count, Integer::sum));
			return new AccountRouteState(real, boosted, quests, bits, players, combined, worn, knownItems);
		}
	}
}

package com.clueteleports.routing;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import org.junit.Test;

import static com.clueteleports.routing.WalkingCollisionMapTest.pack;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class RoutingDataTest
{
	private static final String HEADER = "# Origin\tDestination\tmenuOption menuTarget objectID\tSkills\tItems\tQuests\tVarbits\tVarPlayers\tDuration\n";

	@Test
	public void loadsPinnedBundledCollisionAndOnlyPhysicalTables() throws Exception
	{
		RoutingData data = RoutingData.load();
		assertTrue(data.getTransports().size() > 5000);
		assertTrue(data.getCollisionMap().hasRegion(pack(3213, 3424, 0)));
		assertTrue(data.getCollisionMap().isWalkable(pack(3213, 3424, 0)));
		assertTrue(data.getTransports().stream().anyMatch(edge -> edge.getAction().equals("Open Door 9398")));
		assertTrue(data.getTransports().stream().allMatch(edge -> edge.getFrom() != edge.getTo() && edge.getDurationTicks() >= 1));
	}

	@Test
	public void headerMappingPreservesDirectionsAndRequirements() throws Exception
	{
		String table = "Destination\tOrigin\tSkills\tDuration\tmenuOption menuTarget objectID\n"
			+ "5 4 0\t4 4 0\t70 Agility\t7\tClimb gate\n";
		RoutingData data = data(table);
		assertEquals(1, data.getTransports().size());
		RouteTransport edge = data.getTransports().get(0);
		assertEquals(pack(4, 4, 0), edge.getFrom());
		assertEquals(pack(5, 4, 0), edge.getTo());
		assertEquals(7, edge.getDurationTicks());
		assertEquals("Climb gate", edge.getAction());
		assertFalse(data.getCollisionMap().canWalk(edge.getFrom(), edge.getTo()));
		assertFalse(data.getCollisionMap().canWalk(edge.getTo(), edge.getFrom()));
	}

	@Test
	public void unknownRequirementsRemovePassageWithoutOpeningItsDoor() throws Exception
	{
		RoutingData data = data(HEADER + "4 4 0\t5 4 0\tOpen locked door\t70 UnknownSkill\t\t\t\t\t1\n");
		assertTrue(data.getTransports().isEmpty());
		assertFalse(data.getCollisionMap().canWalk(pack(4, 4, 0), pack(5, 4, 0)));
		assertFalse(data.getCollisionMap().canWalk(pack(4, 4, 0), pack(5, 5, 0)));
		assertTrue(data.getCollisionMap().canWalk(pack(4, 4, 0), pack(4, 5, 0)));
	}

	@Test
	public void rejectsGlobalOrMalformedRowsAndDoesNotInventReverseEdges() throws Exception
	{
		RoutingData data = data(HEADER
			+ "\t5 4 0\tGlobal teleport\t\t\t\t\t\t1\n"
			+ "4 4 0\t\tMissing arrival\t\t\t\t\t\t1\n"
			+ "20000 4 0\t5 4 0\tOutside world\t\t\t\t\t\t1\n"
			+ "4 4 0\t7 4 0\tEnter stairs\t\t\t\t\t\t3\n");
		assertEquals(1, data.getTransports().size());
		assertEquals(pack(7, 4, 0), data.getTransports().get(0).getTo());
	}

	@Test
	public void blankAndZeroDurationsHaveAPositivePassageCost() throws Exception
	{
		RoutingData data = data(HEADER
			+ "4 4 0\t5 4 0\tOpen door\t\t\t\t\t\t\n"
			+ "5 4 0\t4 4 0\tOpen door\t\t\t\t\t\t0\n");
		assertEquals(2, data.getTransports().size());
		assertEquals(1, data.getTransports().get(0).getDurationTicks());
		assertEquals(1, data.getTransports().get(1).getDurationTicks());
	}

	@Test(expected = UnsupportedOperationException.class)
	public void transportCollectionIsImmutable() throws Exception
	{
		data(HEADER).getTransports().clear();
	}

	@Test(expected = IOException.class)
	public void missingCoordinateHeaderFailsTheLoad() throws Exception
	{
		data("An unknown table\n");
	}

	private static RoutingData data(String table) throws IOException
	{
		return RoutingData.load(WalkingCollisionMapTest.zip("0_0", WalkingCollisionMapTest.openPlane()),
			stream(table), stream(HEADER));
	}

	private static ByteArrayInputStream stream(String text)
	{
		return new ByteArrayInputStream(text.getBytes(StandardCharsets.UTF_8));
	}
}

package com.clueteleports.routing;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.Arrays;
import java.util.Collections;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class WalkingCollisionMapTest
{
	@Test
	public void decodesLittleEndianFourFlagRegionPlanes() throws Exception
	{
		WalkingCollisionMap map = WalkingCollisionMap.load(zip("0_0", openPlane()));
		assertTrue(map.hasRegion(pack(1, 1, 0)));
		assertTrue(map.isWalkable(pack(1, 1, 0)));
		assertTrue(map.canWalk(pack(1, 1, 0), pack(2, 1, 0)));
		assertTrue(map.canWalk(pack(1, 1, 0), pack(2, 2, 0)));
		assertFalse(map.hasRegion(pack(1, 1, 1)));
		assertFalse(map.isWalkable(pack(64, 1, 0)));
	}

	@Test
	public void movementCannotCrossAClosedWallInEitherDirection() throws Exception
	{
		byte[] flags = openPlane();
		clear(flags, 4, 4, 0, 1);
		WalkingCollisionMap map = WalkingCollisionMap.load(zip("0_0", flags));
		assertFalse(map.canWalk(pack(4, 4, 0), pack(5, 4, 0)));
		assertFalse(map.canWalk(pack(5, 4, 0), pack(4, 4, 0)));
		assertTrue(map.canWalk(pack(4, 4, 0), pack(4, 5, 0)));
	}

	@Test
	public void diagonalsRequireAllFourCardinalEdgesAroundTheCorner() throws Exception
	{
		byte[] flags = openPlane();
		clear(flags, 5, 4, 0, 0);
		WalkingCollisionMap map = WalkingCollisionMap.load(zip("0_0", flags));
		assertTrue(map.canWalk(pack(4, 4, 0), pack(5, 4, 0)));
		assertTrue(map.canWalk(pack(4, 4, 0), pack(4, 5, 0)));
		assertFalse(map.canWalk(pack(4, 4, 0), pack(5, 5, 0)));
		assertFalse(map.canWalk(pack(5, 5, 0), pack(4, 4, 0)));
	}

	@Test
	public void crossingARegionBoundaryRequiresBothRegions() throws Exception
	{
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ZipOutputStream zip = new ZipOutputStream(bytes))
		{
			entry(zip, "0_0", openPlane());
			entry(zip, "1_0", openPlane());
		}
		WalkingCollisionMap map = WalkingCollisionMap.load(new ByteArrayInputStream(bytes.toByteArray()));
		assertTrue(map.canWalk(pack(63, 10, 0), pack(64, 10, 0)));
		WalkingCollisionMap partial = WalkingCollisionMap.load(zip("0_0", openPlane()));
		assertFalse(partial.canWalk(pack(63, 10, 0), pack(64, 10, 0)));
	}

	@Test
	public void walkingNeverChangesPlanesOrJumpsAcrossTiles() throws Exception
	{
		byte[] planes = new byte[4096];
		Arrays.fill(planes, (byte) 0x33);
		WalkingCollisionMap map = WalkingCollisionMap.load(zip("0_0", planes));
		assertTrue(map.hasRegion(pack(4, 4, 1)));
		assertFalse(map.canWalk(pack(4, 4, 0), pack(4, 4, 1)));
		assertFalse(map.canWalk(pack(4, 4, 0), pack(6, 4, 0)));
		assertFalse(map.canWalk(pack(4, 4, 0), pack(4, 4, 0)));
		assertFalse(map.isWalkable(-1));
	}

	@Test
	public void explicitPassagesHaveNoOrdinaryOrDiagonalBypass() throws Exception
	{
		WalkingCollisionMap original = WalkingCollisionMap.load(zip("0_0", openPlane()));
		RouteTransport door = new RouteTransport(pack(4, 4, 0), pack(5, 4, 0), 1, "Open locked door",
			RouteRequirements.parse("70 Agility", "", "", "", "").get());
		WalkingCollisionMap guarded = original.withTransportEdges(Collections.singletonList(door));
		assertTrue(original.canWalk(pack(4, 4, 0), pack(5, 4, 0)));
		assertFalse(guarded.canWalk(pack(4, 4, 0), pack(5, 4, 0)));
		assertFalse(guarded.canWalk(pack(5, 4, 0), pack(4, 4, 0)));
		assertFalse(guarded.canWalk(pack(4, 4, 0), pack(5, 5, 0)));
		assertTrue(guarded.canWalk(pack(4, 4, 0), pack(4, 5, 0)));
	}

	@Test(expected = IOException.class)
	public void rejectsMalformedRegionNames() throws Exception
	{
		WalkingCollisionMap.load(zip("../region", openPlane()));
	}

	@Test(expected = IOException.class)
	public void rejectsRegionsLargerThanFourPlanes() throws Exception
	{
		WalkingCollisionMap.load(zip("0_0", new byte[8193]));
	}

	@Test(expected = IOException.class)
	public void rejectsMissingCollisionData() throws Exception
	{
		WalkingCollisionMap.load(null);
	}

	@Test
	public void explicitArrivalCanLeaveSolidFootprintWithoutGrantingOrdinaryWalking() throws Exception
	{
		byte[] flags = openPlane();
		solid(flags, 4, 4, 0);
		WalkingCollisionMap map = WalkingCollisionMap.load(zip("0_0", flags));
		assertFalse(map.isWalkable(pack(4, 4, 0)));
		assertFalse(map.canWalk(pack(4, 4, 0), pack(3, 4, 0)));
		assertTrue(map.canLeaveArrival(pack(4, 4, 0), pack(3, 4, 0)));
		assertTrue(map.canInteractFrom(pack(3, 4, 0), pack(4, 4, 0)));
	}

	@Test
	public void footprintEscapeAndInteractionCannotCrossStructuralWallsOnAnySide() throws Exception
	{
		int[][] sides = {{3, 4, 3, 4, 3}, {5, 4, 4, 4, 3}, {4, 3, 4, 3, 2}, {4, 5, 4, 4, 2}};
		for (int[] side : sides)
		{
			byte[] flags = openPlane();
			solid(flags, 4, 4, 0);
			set(flags, side[2], side[3], 0, side[4]);
			WalkingCollisionMap map = WalkingCollisionMap.load(zip("0_0", flags));
			int face = pack(side[0], side[1], 0);
			assertFalse(map.canLeaveArrival(pack(4, 4, 0), face));
			assertFalse(map.canInteractFrom(face, pack(4, 4, 0)));
		}
	}

	@Test
	public void blockedArrivalEscapeIsOnlyOneCardinalStepOnItsMappedPlane() throws Exception
	{
		byte[] flags = new byte[4096];
		Arrays.fill(flags, (byte) 0x33);
		solid(flags, 4, 4, 0);
		WalkingCollisionMap map = WalkingCollisionMap.load(zip("0_0", flags));
		assertFalse(map.canLeaveArrival(pack(4, 4, 0), pack(3, 3, 0)));
		assertFalse(map.canLeaveArrival(pack(4, 4, 0), pack(2, 4, 0)));
		assertFalse(map.canLeaveArrival(pack(4, 4, 0), pack(4, 4, 1)));
		assertFalse(map.canLeaveArrival(pack(64, 4, 0), pack(63, 4, 0)));
		assertFalse(map.canInteractFrom(pack(63, 4, 0), pack(64, 4, 0)));
	}

	@Test
	public void footprintEscapeAndInteractionDoNotBypassPassageLocks() throws Exception
	{
		byte[] flags = openPlane();
		solid(flags, 4, 4, 0);
		WalkingCollisionMap map = WalkingCollisionMap.load(zip("0_0", flags));
		RouteTransport passage = new RouteTransport(pack(4, 4, 0), pack(3, 4, 0), 1,
			"Locked passage", RouteRequirements.none());
		WalkingCollisionMap guarded = map.withTransportEdges(Collections.singletonList(passage));
		assertFalse(guarded.canLeaveArrival(pack(4, 4, 0), pack(3, 4, 0)));
		assertFalse(guarded.canInteractFrom(pack(3, 4, 0), pack(4, 4, 0)));
	}

	@Test
	public void solidTwoTileObjectCanBeInteractedWithAcrossItsUnwalledFootprint() throws Exception
	{
		byte[] flags = openPlane();
		solid(flags, 3, 4, 0);
		solid(flags, 4, 4, 0);
		WalkingCollisionMap map = WalkingCollisionMap.load(zip("0_0", flags));
		assertTrue(map.canInteractFrom(pack(2, 4, 0), pack(4, 4, 0)));
		assertFalse(map.canWalk(pack(2, 4, 0), pack(3, 4, 0)));
		assertFalse(map.canInteractFrom(pack(1, 4, 0), pack(4, 4, 0)));
		assertFalse(map.canInteractFrom(pack(3, 3, 0), pack(4, 4, 0)));
		set(flags, 3, 4, 0, 3);
		WalkingCollisionMap partitioned = WalkingCollisionMap.load(zip("0_0", flags));
		assertFalse(partitioned.canInteractFrom(pack(2, 4, 0), pack(4, 4, 0)));
	}

	@Test
	public void twoTileInteractionChecksEveryPassageBarrierInTheFootprint() throws Exception
	{
		byte[] flags = openPlane();
		solid(flags, 3, 4, 0);
		solid(flags, 4, 4, 0);
		WalkingCollisionMap map = WalkingCollisionMap.load(zip("0_0", flags));
		RouteTransport passage = new RouteTransport(pack(3, 4, 0), pack(4, 4, 0), 1,
			"Inner lock", RouteRequirements.none());
		WalkingCollisionMap guarded = map.withTransportEdges(Collections.singletonList(passage));
		assertFalse(guarded.canInteractFrom(pack(2, 4, 0), pack(4, 4, 0)));
	}

	@Test
	public void walkableInteractionTargetsStillRequireAnOrdinaryWalkingEdge() throws Exception
	{
		byte[] flags = openPlane();
		clear(flags, 4, 4, 0, 1);
		WalkingCollisionMap map = WalkingCollisionMap.load(zip("0_0", flags));
		assertTrue(map.isWalkable(pack(5, 4, 0)));
		assertFalse(map.canInteractFrom(pack(4, 4, 0), pack(5, 4, 0)));
		assertFalse(map.canInteractFrom(pack(3, 4, 0), pack(5, 4, 0)));
		assertTrue(map.canInteractFrom(pack(5, 5, 0), pack(5, 4, 0)));
	}

	@Test
	public void pinnedCisFairyRingLandingCanLeaveItsSolidFootprintToTheWest() throws Exception
	{
		WalkingCollisionMap map = WalkingCollisionMap.load(
			WalkingCollisionMap.class.getResourceAsStream("/routes/collision-map.zip"));
		int cis = pack(1639, 3868, 0);
		int west = pack(1638, 3868, 0);
		assertTrue(map.hasRegion(cis));
		assertFalse(map.isWalkable(cis));
		assertTrue(map.isWalkable(west));
		assertFalse(map.canWalk(cis, west));
		assertTrue(map.canLeaveArrival(cis, west));
		assertTrue(map.canInteractFrom(west, cis));
	}

	private static void solid(byte[] bytes, int x, int y, int plane)
	{
		clear(bytes, x, y, plane, 0);
		clear(bytes, x, y, plane, 1);
		clear(bytes, x, y - 1, plane, 0);
		clear(bytes, x - 1, y, plane, 1);
	}

	private static void set(byte[] bytes, int x, int y, int plane, int flag)
	{
		int bit = (plane * 4096 + y * 64 + x) * 4 + flag;
		bytes[bit >>> 3] |= 1 << (bit & 7);
	}

	static int pack(int x, int y, int plane) { return plane << 28 | x << 14 | y; }

	static byte[] openPlane()
	{
		byte[] bytes = new byte[2048];
		Arrays.fill(bytes, (byte) 0x33);
		return bytes;
	}

	static ByteArrayInputStream zip(String name, byte[] data) throws IOException
	{
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ZipOutputStream zip = new ZipOutputStream(bytes))
		{
			entry(zip, name, data);
		}
		return new ByteArrayInputStream(bytes.toByteArray());
	}

	private static void entry(ZipOutputStream zip, String name, byte[] bytes) throws IOException
	{
		zip.putNextEntry(new ZipEntry(name));
		zip.write(bytes);
		zip.closeEntry();
	}

	private static void clear(byte[] bytes, int x, int y, int plane, int flag)
	{
		int bit = (plane * 4096 + y * 64 + x) * 4 + flag;
		bytes[bit >>> 3] &= ~(1 << (bit & 7));
	}
}

package com.clueteleports.routing;

import com.clueteleports.TeleportDestination;
import com.clueteleports.TeleportSource;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class WalkingRouteSearchTest
{
	private final SyntheticCollision collision = new SyntheticCollision();
	private final WalkingRouteSearch search = new WalkingRouteSearch(100_000, 5_000);

	@Test
	public void exactArrivalNeedsNoWalkingAndPackedTileZeroIsValid()
	{
		TeleportDestination arrival = arrival("zero", TeleportSource.FAIRY_RING, point(0, 0));

		WalkingRouteResult result = run(Collections.emptyList(), List.of(point(0, 0)), List.of(arrival));

		assertFound(result, arrival, 0, 0, 0);
		assertEquals(point(0, 0), result.getTarget());
		assertEquals(0.0, result.getEstimatedRunTicks(), 0);
	}

	@Test
	public void geographicallyCloserArrivalLosesWhenWallsForceALongerWalk()
	{
		WorldPoint goal = point(10, 10);
		collision.path(point(12, 10), point(12, 9), point(12, 8), point(11, 8),
			point(10, 8), point(10, 9), goal);
		collision.path(point(10, 14), point(10, 13), point(10, 12), point(10, 11), goal);
		TeleportDestination near = arrival("near", TeleportSource.FAIRY_RING, point(12, 10));
		TeleportDestination farther = arrival("farther", TeleportSource.JEWELLERY_BOX, point(10, 14));

		assertFound(run(List.of(), List.of(goal), List.of(near, farther)), farther, 4, 4, 0);
	}

	@Test
	public void eligibleAgilityPassageCanChangeTheWinningArrival()
	{
		for (int x = 0; x < 10; x++) collision.link(point(x, 0), point(x + 1, 0));
		for (int y = 0; y < 4; y++) collision.link(point(10, y), point(10, y + 1));
		TeleportDestination first = arrival("shortcut", TeleportSource.FAIRY_RING, point(0, 0));
		TeleportDestination second = arrival("ordinary", TeleportSource.JEWELLERY_BOX, point(10, 4));
		List<TeleportDestination> arrivals = List.of(first, second);
		RouteTransport shortcut = passage(point(0, 0), point(10, 0), 1);

		assertFound(run(List.of(), List.of(point(10, 0)), arrivals), second, 4, 4, 0);
		assertFound(run(List.of(shortcut), List.of(point(10, 0)), arrivals), first, 2, 0, 1);
	}

	@Test
	public void walkingTilesAndActionDurationHaveSeparateMetrics()
	{
		collision.link(point(0, 0), point(1, 0));
		collision.link(point(9, 0), point(10, 0));
		TeleportDestination arrival = arrival("mixed", TeleportSource.SPIRIT_TREE, point(0, 0));

		WalkingRouteResult result = run(List.of(passage(point(1, 0), point(9, 0), 3)),
			List.of(point(10, 0)), List.of(arrival));

		assertFound(result, arrival, 8, 2, 1);
		assertEquals(4.0, result.getEstimatedRunTicks(), 0);
	}

	@Test
	public void stairsConnectFloorsOnlyInTheirDeclaredDirection()
	{
		WorldPoint downstairs = new WorldPoint(100, 100, 0);
		WorldPoint upstairs = new WorldPoint(100, 100, 1);
		RouteTransport stairs = passage(downstairs, upstairs, 3);
		TeleportDestination lower = arrival("lower", TeleportSource.PORTAL_NEXUS, downstairs);
		TeleportDestination upper = arrival("upper", TeleportSource.PORTAL_NEXUS, upstairs);

		assertFound(run(List.of(stairs), List.of(upstairs), List.of(lower)), lower, 6, 0, 1);
		assertEquals(WalkingRouteResult.Status.NO_ROUTE,
			run(List.of(stairs), List.of(downstairs), List.of(upper)).getStatus());
	}

	@Test
	public void matchingXYOnAnotherFloorDoesNotCountAsAnArrival()
	{
		assertEquals(WalkingRouteResult.Status.NO_ROUTE, run(List.of(),
			List.of(new WorldPoint(100, 100, 1)),
			List.of(arrival("surface", TeleportSource.FAIRY_RING, point(100, 100)))).getStatus());
	}

	@Test
	public void reversedWalkingChecksTheOriginalForwardDirection()
	{
		WorldPoint start = point(10, 10);
		WorldPoint goal = point(11, 10);
		collision.directed(start, goal);
		TeleportDestination outward = arrival("outward", TeleportSource.FAIRY_RING, start);
		TeleportDestination back = arrival("back", TeleportSource.FAIRY_RING, goal);

		assertFound(run(List.of(), List.of(goal), List.of(outward)), outward, 1, 1, 0);
		assertEquals(WalkingRouteResult.Status.NO_ROUTE, run(List.of(), List.of(start), List.of(back)).getStatus());
	}

	@Test
	public void aBlockedArrivalCannotEscapeThroughNearbyWalls()
	{
		collision.link(point(0, 0), point(1, 0));
		TeleportDestination blocked = arrival("blocked", TeleportSource.FAIRY_RING, point(2, 0));

		assertEquals(WalkingRouteResult.Status.NO_ROUTE, run(List.of(), List.of(point(0, 0)),
			List.of(blocked)).getStatus());
	}

	@Test
	public void aKnownTeleportArrivalMayLeaveItsValidatedFixtureFootprint()
	{
		collision.link(point(0, 0), point(1, 0));
		collision.arrivalExit(point(2, 0), point(1, 0));
		TeleportDestination arrival = arrival("known-footprint", TeleportSource.FAIRY_RING, point(2, 0));

		assertFound(run(List.of(), List.of(point(0, 0)), List.of(arrival)), arrival, 2, 2, 0);
	}

	@Test
	public void aNonArrivalBlockedJunctionCannotUseTheTeleportExitException()
	{
		collision.link(point(0, 0), point(1, 0));
		collision.arrivalExit(point(2, 0), point(1, 0));
		TeleportDestination arrival = arrival("ordinary", TeleportSource.FAIRY_RING, point(3, 0));

		assertEquals(WalkingRouteResult.Status.NO_ROUTE,
			run(List.of(passage(point(3, 0), point(2, 0), 1)), List.of(point(0, 0)), List.of(arrival)).getStatus());
	}

	@Test
	public void diagonalMovementRequiresTheCollisionMapsPermission()
	{
		TeleportDestination start = arrival("diagonal", TeleportSource.FAIRY_RING, point(0, 0));
		collision.path(point(0, 0), point(0, 1), point(1, 1));

		assertFound(run(List.of(), List.of(point(1, 1)), List.of(start)), start, 2, 2, 0);
		collision.link(point(0, 0), point(1, 1));
		assertFound(run(List.of(), List.of(point(1, 1)), List.of(start)), start, 1, 1, 0);
	}

	@Test
	public void aCheaperRouteDecreasesAnAlreadyQueuedTransportCost()
	{
		WorldPoint a = point(0, 0);
		WorldPoint b = point(1, 0);
		WorldPoint goal = point(10, 0);
		collision.directed(a, b);
		TeleportDestination start = arrival("decrease", TeleportSource.FAIRY_RING, a);

		assertFound(run(List.of(passage(a, goal, 10), passage(b, goal, 1)),
			List.of(goal), List.of(start)), start, 3, 1, 1);
	}

	@Test
	public void equalCostsUseSourceThenIdEvenWhenAnotherTileLeavesTheHeapFirst()
	{
		WorldPoint goal = point(10, 10);
		collision.link(point(9, 10), goal);
		collision.link(point(10, 9), goal);
		TeleportDestination z = arrival("z", TeleportSource.FAIRY_RING, point(9, 10));
		TeleportDestination a = arrival("a", TeleportSource.FAIRY_RING, point(10, 9));
		TeleportDestination tree = arrival("0", TeleportSource.SPIRIT_TREE, point(9, 10));

		assertFound(run(List.of(), List.of(goal), List.of(z, tree, a)), a, 1, 1, 0);
		assertFound(run(List.of(), List.of(goal), List.of(a, tree, z)), a, 1, 1, 0);
	}

	@Test
	public void equalArrivalTilesStillUseSourceAndIdOrder()
	{
		WorldPoint tile = point(0, 0);
		TeleportDestination tree = arrival("a", TeleportSource.SPIRIT_TREE, tile);
		TeleportDestination ring = arrival("z", TeleportSource.FAIRY_RING, tile);

		assertFound(run(List.of(), List.of(tile), List.of(tree, ring)), ring, 0, 0, 0);
	}

	@Test
	public void allQualifiedClueGoalsParticipateInTheSearch()
	{
		collision.path(point(10, 0), point(11, 0), point(12, 0));
		collision.link(point(10, 0), point(10, 1));
		TeleportDestination start = arrival("multi", TeleportSource.JEWELLERY_BOX, point(10, 0));

		WalkingRouteResult result = run(List.of(), List.of(point(12, 0), point(10, 1)), List.of(start));

		assertFound(result, start, 1, 1, 0);
		assertEquals(point(10, 1), result.getTarget());
	}

	@Test
	public void equalGoalCostsUseStableCoordinatesWithoutMutatingInputs()
	{
		WorldPoint start = point(10, 10);
		collision.link(start, point(9, 10));
		collision.link(start, point(10, 9));
		List<WorldPoint> goals = new ArrayList<>(List.of(point(10, 9), point(9, 10)));
		TeleportDestination arrival = arrival("stable", TeleportSource.FAIRY_RING, start);
		List<TeleportDestination> arrivals = new ArrayList<>(List.of(arrival));
		List<RouteTransport> eligible = new ArrayList<>();

		WalkingRouteResult result = run(eligible, goals, arrivals);

		assertEquals(point(9, 10), result.getTarget());
		assertEquals(List.of(point(10, 9), point(9, 10)), goals);
