		assertEquals(WalkingRouteResult.Status.NO_ROUTE, run(List.of(), List.of(point(0, 0)), List.of()).getStatus());
		assertEquals(WalkingRouteResult.Status.NO_ROUTE, run(List.of(), List.of(), List.of(arrival)).getStatus());
